        ["Tell me what I need to slay next."] = "Dime qué necesito acabar a continuación.",
        ["Again? Okay!"] = "¿Otra vez? ¡Bueno!",
        ["Adventurer! I need to you slay more things for me!"] = "¡Aventurero! ¡Necesito que mates más cosas por mí!",
        ["What must I slay for you, Slayer master?"] = "¿Qué debo matar por ti, Slayer master?",
        ["I have decided that you must slay [number] [monster]."] = "He decidido que debes matar a [número] [monster].",
        ["**Olivia:** They're found inside Kalphite hives under the desert sands. At least that's where I was told..."] = "**Olivia:** Se encuentran dentro de colmenas calfitas bajo las arenas del desierto. Al menos ahí me dijeron...",
        ["I've been tasked to procure supplies for the war effort."] = "Me han encomendado la tarea de conseguir suministros para el esfuerzo bélico.",
        ["Who are we- Who are YOU at war with?"] = "¿Quiénes somos? ¿Con quién estás en guerra TÚ?",
        ["All will be revealed. First up I need [number] [items]. Can I rely on you?"] = "Todo será revelado. Primero necesito [número] [items]. ¿Puedo confiar en ti?",
        ["Affirmative."] = "Afirmativo.",
        ["Negative."] = "Negativo.",
        ["Do you have the [number] [item] at hand, soldier? ([number] remaining)"] = "¿Tienes el [número] [item] a mano, soldado? ([número] restantes)",
        ["Good work, soldier!"] = "¡Buen trabajo, soldado!",
        ["Now that's done, we need the next block of supplies."] = "Ahora que está hecho, necesitamos el siguiente bloque de suministros.",
        ["The next supplies I require are a load of [item]."] = "Los siguientes suministros que necesito son una carga de [item].",
        ["Have you ever tried to fight a war without [item]? I didn't think so."] = "¿Alguna vez has intentado pelear una guerra sin [item]? No lo creo.",
        ["The war effort requires [number] [item]. I assume I can trust you to obtain the [item]?"] = "El esfuerzo de guerra requiere [número] [item]. ¿Asumo que puedo confiar en usted para obtener el [item]?",
        ["You sure can."] = "Seguro que puedes.",
        ["Do you have the supplies, soldier? This war won't fund itself! We need [number] [item]! ([number] remaining)"] = "¿Tienes los suministros, soldado? ¡Esta guerra no se financiará sola! ¡Necesitamos [número] [item]! ([número] restantes)",
        ["Great! Now we are ready to drive the offensive home!"] = "¡Genial! ¡Ahora estamos listos para llevar la ofensiva a casa!",
        ["Can I ask why you're talking like this?"] = "¿Puedo preguntar por qué hablas así?",
        ["Whatever do you mean, soldier?"] = "¿Qué quieres decir, soldado?",
        ["You're talking like an imperial general. It's a bit off-putting."] = "Estás hablando como un general imperial. Es un poco desagradable.",
        ["The guards are always watching. I have to keep up appearances."] = "Los guardias siempre están mirando. Tengo que guardar las apariencias.",
        ["Right...fair enough. What else do...we...need for the war effort?"] = "Cierto... bastante justo. ¿Qué más... nosotros... necesitamos para el esfuerzo bélico?",
        ["Now is the time you have been waiting for, soldier! The killing!"] = "¡Ahora es el momento que estabas esperando, soldado! ¡La matanza!",
        ["We will finally vanquish our dreaded enemy, the [monster]!"] = "¡Finalmente venceremos a nuestro temido enemigo, el [monster]!",
        ["What?"] = "¿Qué?",
        ["Yes, kill [number] [monster] in the name of the Pharaoh himself!"] = "¡Sí, mata a [número] [monster] en nombre del propio Faraón!",
        ["Okay."] = "Está bien.",
        ["Have you killed [number] kalphites? They're found inside Kalphite hives under the desert sands. We might win this war yet! ([number] remaining)"] = "¿Has matado a los calfitos de [número]? Se encuentran dentro de colmenas calfitas bajo las arenas del desierto. ¡Podríamos ganar esta guerra todavía! ([número] restante)",
        ["Have you killed [number] plague frogs? They're usually sliming around Sophanem. We might win this war yet! ([number] remaining)"] = "¿Has matado las ranas plaga [número]? Por lo general, están adelgazando alrededor de Sophanem. ¡Podríamos ganar esta guerra todavía! ([número] restante)",
        ["Have you killed [number] plague frogs? They're usually sliming around Sophanem. We might win this war yet! (0 remaining)"] = "¿Has matado las ranas plaga [número]? Por lo general, están adelgazando alrededor de Sophanem. ¡Podríamos ganar esta guerra todavía! (0 restante)",
        ["Yes, I have killed the [monster]."] = "Sí, he matado al [monster].",
        ["Have you danced, as they say, in the blood of your enemies? Have you sent the souls of [number] [monster] to the Underworld?"] = "¿Has bailado, como dicen, en la sangre de tus enemigos? ¿Has enviado las almas de [número] [monster] al Inframundo?",
        ["Not that those [monster] have souls, I believe they are truly beyond help."] = "No es que esos [monster] tengan alma, creo que realmente no pueden recibir ayuda.",
        ["I fear you still need a lot more help."] = "Me temo que todavía necesitas mucha más ayuda.",
        ["Sorry, what?"] = "Lo siento, ¿qué?",
        ["Nothing. It was my pleasure."] = "Nada. Fue un placer.",
        ["*Olivia will occasionally produce overhead dialogue.*"] = "*Olivia ocasionalmente producirá diálogos generales.*",
        ["What would you like to say?"] = "¿Qué te gustaría decir?",
        ["Would you like to trade?"] = "¿Le gustaría negociar?",
        ["Certainly."] = "Por supuesto.",
        ["Where do I get higher-level seeds?"] = "¿Dónde consigo semillas de nivel superior?",
        ["Master farmers usually carry a few higher-level seeds around with them, although I don't know if they'd want to part with them for any price, to be honest."] = "Los grandes agricultores suelen llevar consigo algunas semillas de nivel superior, aunque, para ser honesto, no sé si querrían desprenderse de ellas por algún precio.",
        ["About the recent bank robbery..."] = "Sobre el reciente robo al banco...",
        ["About the recent bank robbery... The robber attacked you, didn't he?"] = "Sobre el reciente robo al banco... El ladrón te atacó, ¿no?",
        ["Something like that, yes. I was just minding my own business, trying to keep these pesky thieves off my stalls, when I heard a strange noise and a scream."] = "Algo así, sí. Estaba ocupándome de mis propios asuntos, tratando de mantener a estos molestos ladrones fuera de mis puestos, cuando escuché un ruido extraño y un grito.",
        ["I went across to see what was going on, but there was a bright purple flash and everything went black. Before I knew what had happened, I was standing in Falador!"] = "Fui a ver qué estaba pasando, pero hubo un destello violeta brillante y todo se volvió negro. Antes de darme cuenta de lo que había sucedido, ¡estaba parada en Falador!",
        ["It took me ages to get back, and when I arrived I saw there was a huge hole in the bank wall and some of the bankers had been killed!"] = "Me tomó mucho tiempo regresar, y cuando llegué vi que había un enorme agujero en la pared del banco y ¡algunos de los banqueros habían sido asesinados!",
        ["Did you see who teleported you to Falador?"] = "¿Viste quién te teletransportó a Falador?",
        ["No, they were standing behind that old man's door."] = "No, estaban parados detrás de la puerta de ese old man.",
        ["He really shouldn't leave his door open all day, especially in this neighbourhood - there are thousands of thieves around, and anyone could wander in!"] = "Realmente no debería dejar la puerta abierta todo el día, especialmente en este vecindario: ¡hay miles de ladrones por ahí y cualquiera podría entrar!",
        ["Okay, thanks for your time."] = "Bien, gracias por tu tiempo.",
        ["You're welcome. Would you like to see my fine selection of seeds?"] = "De nada. ¿Te gustaría ver mi excelente selección de semillas?",
        ["Would you like to see Olivia's stock?"] = "¿Quieres ver las acciones de Olivia?",
        ["Yes please."] = "Sí por favor.",
        ["No thanks."] = "No gracias.",
        ["No, thanks."] = "No, gracias.",
    },
    ["Olivia the Chronicler"] = {
        ["Pirates? Inside the temple?"] = "¿Piratas? ¿Dentro del templo?",
        ["Well we can't have that..."] = "Bueno, no podemos permitir eso...",
        ["We have been warned about your type."] = "Nos han advertido sobre tu tipo.",
        ["No one is permitted inside the sanctum!"] = "¡No se permite a nadie dentro del santuario!",
    },
    ["Ollie the Camel"] = {
        ["What Would You Like To Do"] = "¿Qué te gustaría hacer?",
        ["Ask the camel about its dung."] = "Pregúntale al camello por su estiércol.",
        ["I'm sorry to bother you, but could you spare me a little dung?"] = "Lamento molestarte, pero ¿podrías ahorrarme un poco de estiércol?",
        ["Are you serious?"] = "¿Hablas en serio?",
        ["Oh yes. If you'd be so kind..."] = "Ah, sí. Si fueras tan amable...",
        ["Well, just you close your eyes first. I'm not doing it while you're watching me!"] = "Bueno, primero cierra los ojos. ¡No lo haré mientras me miras!",
        ["I hope that's what you wanted!"] = "¡Espero que eso sea lo que querías!",
        ["Ohhh yes. Lovely."] = "Ohhh, sí. Hermoso.",
        ["Say something unpleasant."] = "Di algo desagradable.",
        ["*The player says one of the following at random:*"] = "*el player dice uno de los siguientes al azar:*",
        ["*Dialogue 1:*"] = "*Diálogo 1:*",
        ["If I go near that camel, it'll probably bite my hand off."] = "Si me acerco a ese camello, probablemente me arrancará la mano de un mordisco.",
        ["What did you say?"] = "¿Qué dijiste?",
        ["Er, nothing important."] = "Er, nada importante.",
        ["Ah, a human. Do you know anything about flying?"] = "Ah, un humano. ¿Sabes algo sobre volar?",
        ["Flying?"] = "¿Volando?",
        ["Yes, flying. It's a wonderful thing. I've seen this glider fly, and it's so elegant and fast. If I could fly, I wouldn't want to do anything else. I'd just fly around all day, swooping and soaring."] = "Sí, volando. Es algo maravilloso. He visto volar este planeador y es muy elegante y rápido. Si pudiera volar, no querría hacer nada más. Simplemente volaría todo el día, descendiendo y elevándose.",
        ["*Dialogue 2:*"] = "*Diálogo 2:*",
        ["Mmm... Looks like that camel would make a nice kebab."] = "Mmm... Parece que ese camello sería un buen kebab.",
        ["*(Same as above)*"] = "*(Igual que arriba)*",
        ["*Dialogue 3:*"] = "*Diálogo 3:*",
        ["I wonder if that camel has fleas..."] = "Me pregunto si ese camello tendrá pulgas...",
        ["Neither - I'm a polite person."] = "Ninguno de los dos, soy una persona educada.",
        ["*You decide not to be rude.*"] = "*Decides no ser grosero.*",
    },
    ["Omart"] = {
        ["Hello there."] = "Hola.",
        ["Hello."] = "Hola.",
        ["How are you?"] = "¿Cómo estás?",
        ["Fine thanks."] = "Bien, gracias.",
        ["Hello Omart."] = "Hola Omart.",
        ["Hello Adventurer. I'm afraid it's too risky to use the ladder again, but I believe that Edmond's working on another tunnel."] = "Hola aventurero. Me temo que es demasiado arriesgado volver a usar la escalera, pero creo que Edmond está trabajando en otro túnel.",
        ["Looks like you won't be needing the rope ladder any more, adventurer. I heard it was you who started the revolution and freed West Ardougne!"] = "Parece que ya no necesitarás la escalera de cuerda, aventurero. ¡Escuché que fuiste tú quien inició la revolución y liberó a West Ardougne!",
    },
    ["One-Eyed Willy"] = {
        ["So that's why they call you One-Eyed Willy."] = "Por eso te llaman One-Eyed Willy.",
        ["What, just because I'm a cyclops?"] = "¿Qué? ¿Solo porque soy un cíclope?",
        ["How incredibly rude of you to assume that. I've never been so insulted."] = "Qué increíblemente grosero de tu parte asumir eso. Nunca me había sentido tan insultado.",
        ["So, you're not One-Eyed Willy? If that's true, who is?"] = "Entonces, ¿no eres One-Eyed Willy? Si eso es verdad, ¿quién lo es?",
        ["The parrot."] = "El loro.",
        ["You named your parrot One-Eyed Willy? Okay..."] = "¿Le pusiste a tu loro el nombre One-Eyed Willy? Está bien...",
        ["I didn't name him - that's his name! And he's not MY parrot; I'm HIS cyclops! His seeing-eye cyclops!"] = "No le puse el nombre, ¡ese es su nombre! Y él no es MI loro; ¡Soy SU cíclope! ¡Su cíclope que ve!",
        ["But you're wearing an eyepatch, and the parrot isn't. I don't..."] = "Pero tú llevas un parche en el ojo y el loro no. Yo no...",
        ["The parrot seems to whisper-squawk something in the cyclops's ear."] = "El loro parece susurrar algo al oído del cíclope.",
        ["I know, right. Tourists!"] = "Lo sé, cierto. ¡Turistas!",
        ["The parrot seems to whisper-squawk something foreboding in the cyclops's ear."] = "El loro parece susurrar algo siniestro al oído del cíclope.",
        ["No, I don't think we should tell them about The Harbinger."] = "No, no creo que debamos contarles sobre The Harbinger.",
        ["The parrot seems to whisper-squawk something rude into the cyclops's ear."] = "El loro parece susurrar algo grosero al oído del cíclope.",
        ["He says you should probably go. He doesn't like you."] = "Dice que probablemente deberías irte. No le gustas.",
        ["I'm sorry, I'll try not to rescue castaways in the future."] = "Lo siento, intentaré no rescatar náufragos en el futuro.",
        ["I don't like you either."] = "A mí tampoco me gustas.",
    },
    ["Oneiromancer"] = {
        ["Hello."] = "Hola.",
        ["Why hello there."] = "Hola.",
        ["Where am I?"] = "¿Dónde estoy?",
        ["Lunar Isle - why don't you go have a look around town."] = "Lunar Isle - ¿Por qué no vas a echar un vistazo a la ciudad?",
        ["The state of the island"] = "El estado de la isla.",
        ["Hi, how are things going?"] = "Hola, ¿cómo van las cosas?",
        ["Well, hopefully a lot better now that you've initiated the calm between the Moon Clan and the Fremenniks."] = "Bueno, espero que mucho mejor ahora que has iniciado la calma entre el Clan Luna y los Fremenniks.",
        ["Remember, if you want to use our Lunar Spells at any time, pray at the altar beside me and you can modify your knowledge!"] = "Recuerda, si quieres usar nuestros Hechizos Lunares en cualquier momento, ¡reza en el altar a mi lado y podrás modificar tus conocimientos!",
        ["*(If the player owns the full set of Lunar equipment)*"] = "*(Si el player posee el conjunto completo de equipo Lunar)*",
        ["How about giving me some Lunar Robes?"] = "¿Qué tal si me regalas algunas túnicas lunares?",
        ["I would gladly say yes... if you didn't already have some in the costume room of your house!"] = "Con mucho gusto diría que sí... ¡si aún no tienes algunos en el salón de disfraces de tu casa!",
        ["Foiled again!"] = "¡Frustrado de nuevo!",
        ["*(If the player is missing any piece of the Lunar equipment)*"] = "*(Si a el player le falta alguna pieza del equipo Lunar)*",
        ["I've lost my [Lunar item]."] = "He perdido mi [Lunar item].",
        ["I know. Good job, I knew you would drop it!"] = "Lo sé. ¡Buen trabajo, sabía que lo dejarías!",
