        ["Yeah, I'll pay that!"] = "¡Sí, lo pagaré!",
        ["No thanks."] = "No, gracias.",
        ["The war against the daggermouths"] = "La guerra contra los bocadagas",
        ["Hello again. Seen Cyrisus recently?"] = "Hola de nuevo. ¿Has visto Cyrisus recientemente?",
        ["As you mention it, yes. He wanted to create more astral runes."] = "Como lo mencionas, sí. Quería crear más runas astrales.",
        ["Interesting."] = "Interesante.",
        ["He said something about fighting kalphites, whatever they are."] = "Dijo algo sobre luchar contra los calfitos, sean lo que sean.",
        ["Sounds like his fear of combat really is a problem of the past!"] = "¡Parece que su miedo al combate realmente es un problema del pasado!",
        ["You've done well. Very well."] = "Lo has hecho bien. Muy bien.",
        ["Hi."] = "Hola.",
        ["Hello. Still fighting evil with Cyrisus?"] = "Hola. ¿Sigues luchando contra el mal con Cyrisus?",
        ["Oh. You've not heard: he's no longer with us. He passed away."] = "Oh. No lo has oído: ya no está con nosotros. Él falleció.",
        ["What? Oh no."] = "¿Qué? Oh, no.",
        ["But he died fighting for a good cause. He'll be remembered as a great hero."] = "Pero murió luchando por una buena causa. Será recordado como un gran héroe.",
        ["I suppose the good do die young."] = "Supongo que los buenos mueren jóvenes.",
    },
    ["Onyx dragon"] = {
