        ["Category:Non-spoken transcripts"] = "Categoría: Transcripciones no habladas",
    },
    ["Onyx the Black"] = {
        ["Meow!"] = "¡Miau!",
        ["Meow."] = "Miau.",
        ["Meow..."] = "Miau...",
        ["Meow?"] = "¿Miau?",
        ["Meowwwwww."] = "Miauwwwwww.",
        ["Defeat the evil, Ben the Wise!"] = "¡Derrota al mal, Ben el Sabio!",
        ["Humphrey catches any crows that land on the farm, and I get to eat them. It's a wonderful deal we have going on."] = "Humphrey atrapa los cuervos que aterrizan en la granja y yo puedo comérmelos. Es un trato maravilloso el que tenemos en marcha.",
