    ["Oomad Arrow"] = {
        ["Hello there. What can I do for you today?"] = "Hola. ¿Qué puedo hacer por ti hoy?",
        ["I'd like to ask about the Gielinor Games."] = "Me gustaría preguntar sobre los juegos Gielinor.",
        ["What would you like to know?"] = "¿Qué te gustaría saber?",
        ["What are the games?"] = "¿Cuáles son los juegos?",
        ["[missing]"] = "[desaparecido]",
        ["What events are running?"] = "¿Qué eventos se están ejecutando?",
        ["We have a number of events running. Which would you like to know more about?"] = "Tenemos varios eventos en marcha. ¿Sobre cuál te gustaría saber más?",
        ["Head-to-Head."] = "Cara a cara.",
        ["Cheese Wheel Rolling."] = "Rueda de queso rodante.",
        ["*(Same as below)*"] = "*(Igual que a continuación)*",
        ["Resource Race."] = "Carrera de recursos.",
        ["Marathon."] = "Maratón.",
        ["I'd like to talk about something else."] = "Me gustaría hablar de otra cosa.",
        ["*(Returns to initial options)*"] = "*(Vuelve a las opciones iniciales)*",
        ["Oh, this event is one of my personal favourites. The athlete rolls a wheel of cheese down a hill and then chases after it."] = "Oh, este evento es uno de mis favoritos personales. El atleta hace rodar una rueda de queso colina abajo y luego la persigue.",
        ["Why?"] = "¿Por qué?",
        ["Erm... Do you know, I've never asked. It's a lot of fun, though. Manic, naturally, and it's really hard to navigate when you're running downhill at, like, a billion miles an hour."] = "Erm... ¿Sabes? Nunca te lo he preguntado. Aunque es muy divertido. Maníaco, naturalmente, y es muy difícil navegar cuando corres cuesta abajo a mil millones de millas por hora.",
        ["*(Same as above)*"] = "*(Igual que arriba)*",
        ["What rewards can I get?"] = "¿Qué recompensas puedo obtener?",
        ["Actually I'm good for now."] = "En realidad estoy bien por ahora.",
        ["Let me see the reward shop."] = "Déjame ver la tienda de recompensas.",
        ["*(Welcome to the Gielinor Games Rewards Shop opens)*"] = "*(Se abre la tienda de recompensas de juegos Gielinor)*",
        ["I'd like to trade in my previous rewards for points."] = "Me gustaría canjear mis recompensas anteriores por puntos.",
        ["I'd just like to chat."] = "Sólo me gustaría charlar.",
    },
    ["Ophelia"] = {
        ["*When speaking to Ophelia in the Clan Threatre.*"] = "*Al hablar con Ophelia en Clan Threatre.*",
        ["Welcome to the theatre, sir."] = "Bienvenido al teatro, señor.",
        ["What would you like to know about?"] = "¿Qué te gustaría saber sobre?",
        ["What is this place?"] = "¿Qué es este lugar?",
        ["It's a theatre, isn't it? Great big stage, curtains, rows of seats."] = "Es un teatro, ¿no? Gran escenario, telones, filas de asientos.",
        ["What can I do here?"] = "¿Qué puedo hacer aquí?",
        ["Tell me about the stage."] = "Cuéntame sobre el escenario.",
        ["Theatre technicians can restrict who has access to the stage, building a list of up to 15 people who are allowed onstage. Guests to the citadel can be added to the list, allowing them to join in the fun too. What you do with the stage is up to you. Try not to get stage-fright, though!"] = "Los técnicos de teatro pueden restringir quién tiene acceso al escenario, creando una lista de hasta 15 personas a las que se les permite subir al escenario. Los invitados a la ciudadela se pueden agregar a la lista, lo que les permitirá unirse a la diversión también. Lo que hagas con el escenario depende de ti. ¡Pero intenta no tener miedo escénico!",
        ["Tell me about sound and spotlights."] = "Cuéntame sobre el sonido y los focos.",
        ["You'll find machines for controlling spotlights and sound effects backstage. If your clan has given you permission to be a theatre technician, then you can use these machines. There are four spotlights that can be targeted at people on the stage, and you can change their colour to suit the scene. With the sound effects machine, you're able to build a list of suitable sounds, ready for easy playback in front of an audience."] = "Encontrarás máquinas para controlar focos y efectos de sonido detrás del escenario. Si tu clan te ha dado permiso para ser técnico de teatro, entonces podrás utilizar estas máquinas. Hay cuatro focos que pueden apuntar a las personas en el escenario y puedes cambiar su color para adaptarlo a la escena. Con la máquina de efectos de sonido, puedes crear una lista de sonidos adecuados, listos para reproducirlos fácilmente frente a una audiencia.",
        ["Tell me about backdrops and props."] = "Cuéntame sobre fondos y accesorios.",
        ["Tell me about the backdrop and scenery props."] = "Cuéntame sobre el telón de fondo y los accesorios del escenario.",
        ["The backdrop is chosen by theatre technicians, and can be changed to other backdrops as needed. Technicians can also add scenery props to the stage to add decoration, such as rocks and clouds. Technicians can draw the stage curtains while adjusting the set."] = "El telón de fondo lo eligen los técnicos del teatro y se puede cambiar a otros fondos según sea necesario. Los técnicos también pueden agregar accesorios de escenografía al escenario para agregar decoración, como rocas y nubes. Los técnicos pueden correr las cortinas del escenario mientras ajustan el decorado.",
        ["Let's talk about something else."] = "Hablemos de otra cosa.",
        ["What's that you're selling?"] = "¿Qué es eso que estás vendiendo?",
        ["Oh, these aren't for sale. They're free. Would you like an Orb of Oculus? It should help you get a good view of the stage."] = "Oh, estos no están a la venta. Son gratis. ¿Quieres un orbe de Oculus? Debería ayudarte a tener una buena vista del escenario.",
        ["Yes, give me an Orb of Oculus."] = "Sí, dame un Orbe de Oculus.",
        ["Here you go."] = "Aquí tienes.",
        ["Ophelia hands you an Orb of Oculus."] = "Ophelia te entrega un Orbe de Oculus.",
        ["What is an Orb of Oculus?"] = "¿Qué es un orbe de Oculus?",
        ["It's an outstanding piece of kit, allowing you to get a great view of the world around you, so it should be handy while watching the stage. Wield it, operate it, and you'll be able to adjust your perspective on the world."] = "Es un excelente kit que te permite obtener una excelente vista del mundo que te rodea, por lo que debería ser útil mientras miras el escenario. Manéjalo, utilízalo y podrás ajustar tu perspectiva del mundo.",
        ["It looked like you were selling sweets."] = "Parecía que estabas vendiendo dulces.",
        ["Well, please don't eat the orbs, they've got glass, metal and magic But, yes, I can see how you'd think they look tasty."] = "Bueno, por favor no te comas los orbes, tienen vidrio, metal y magia. Pero sí, puedo ver cómo pensarías que se ven sabrosos.",
        ["No, thank you."] = "No, gracias.",
        ["Never mind."] = "No importa.",
    },
    ["Oracle"] = {
