        ["Jas left a stone behind."] = "Jas dejó una piedra detrás.",
        ["The last shall become the first."] = "El último se convertirá en el primero.",
        ["The light at the end of the tunnel is the demon-infested lava pit."] = "La luz al final del túnel es el pozo de lava infestado de demonios.",
        ["Many secrets are buried under this land."] = "Muchos secretos están enterrados bajo esta tierra.",
        ["Nothing like a tasty fish."] = "Nada como un rico pescado.",
