    ["Orange Flame director"] = {
        ["Oh, a human, I don't have time for you."] = "Oh, humano, no tengo tiempo para ti.",
        ["I just want to know a little bit more about your company. You're new here, aren't you?"] = "Sólo quiero saber un poco más sobre su empresa. Eres nuevo aquí, ¿no?",
        ["That is none of your concern! Get out before I have the Black Guard throw you out!"] = "¡Eso no es de tu incumbencia! ¡Sal antes de que haga que el Black Guard te eche!",
    },
    ["Orange Flame secretary"] = {
        ["That's odd, isn't this the office of the Red Axe?"] = "Eso es extraño, ¿no es esta la oficina del Hacha Roja?",
        ["No, quite clearly this is not. Can't you see the banner?"] = "No, claramente no lo es. ¿No ves el cartel?",
        ["Hmm... it looks like some kind of orange flame."] = "Hmm... parece una especie de llama naranja.",
        ["Very clever, yes. That's us, that is. The Orange Flame."] = "Muy inteligente, sí. Esos somos nosotros, eso es. La Llama Naranja.",
        ["But what are you doing here?"] = "¿Pero qué haces aquí?",
        ["The Red Axe has committed treason. They have departed the city. We have clawed our way up from the rabble of the minor companies. We're now wealthy enough to trade on the Trade Octagon."] = "El Hacha Roja ha cometido traición. Han abandonado la ciudad. Nos hemos abierto camino entre la chusma de las empresas menores. Ahora somos lo suficientemente ricos como para comerciar en el octágono comercial.",
        ["Need any help with that at all?"] = "¿Necesitas ayuda con eso?",
        ["That is a scandalous suggestion! Get out of here!"] = "¡Esa es una sugerencia escandalosa! ¡Fuera de aquí!",
        ["I hear you finally defeated the Red Axe in their secret base! That's what a company gets for committing treason and leaving the city. The Orange Flame will make no such mistake!"] = "¡He oído que finalmente derrotaste al Hacha Roja en su base secreta! Eso es lo que obtiene una empresa por cometer traición y abandonar la ciudad. ¡La Llama Naranja no cometerá tal error!",
    },
    ["Ordan"] = {
        ["*When talking to Ordan at the Blast Furnace in Keldagrim.*"] = "*Al hablar con Ordan en el Alto Horno en Keldagrim.*",
        ["Can you un-note any of my items?"] = "¿Puedes eliminar la nota de alguno de mis artículos?",
        ["I can un-note tin, copper, iron, coal, mithril, adamantite, luminite and rune ores."] = "Puedo eliminar los minerales de estaño, cobre, hierro, carbón, mithril, adamantita, luminita y runas.",
        ["*Occasionally a dwarven miner will bring ores to Ordan, which will result in overhead dialogue.*"] = "*Ocasionalmente, un dwarven miner traerá minerales a Ordan, lo que resultará en un diálogo general.*",
        ["*The Dwarven Miner will always engage the dialogue by acknowledging amount and type of ores brought, to which Ordan will always reply with the same dialogue.*"] = "*El Dwarven Miner siempre iniciará el diálogo reconociendo la cantidad y el tipo de minerales traídos, a lo que Ordan siempre responderá con el mismo diálogo.*",
