        ["I've no idea what is going on there. It's all on a need-to-know basis, so I'm not going to be asking you for information either."] = "No tengo idea de lo que está pasando allí. Todo se basa en la necesidad de saberlo, por lo que tampoco le pediré información.",
        ["Who are you? Osman can't possibly be here!"] = "¿Quién eres? ¡Osman no puede estar aquí!",
        ["You can call me Osman, even though I am the man who is not Osman."] = "Puedes llamarme Osman, aunque soy el hombre que no es Osman.",
        ["So...you are one of his agents, but you look just like him?"] = "Entonces... ¿eres uno de sus agentes, pero te pareces a él?",
        ["Of course I look like him, I'm in disguise. What sort of spy would look like a spy?"] = "Por supuesto que me parezco a él, estoy disfrazado. ¿Qué tipo de espía parecería un espía?",
        ["Well, I seem to remember some business with really bad wigs."] = "Bueno, creo recordar un negocio con pelucas realmente malas.",
        ["Let's change the subject to something Osman might talk about. I don't want to blow my cover."] = "Cambiemos el tema a algo de lo que Osman podría hablar. No quiero revelar mi tapadera.",
        ["I believe I have a plan to save Prince Ali, but I can't talk to you about it here..."] = "Creo que tengo un plan para salvar al Príncipe Ali, pero no puedo hablar contigo sobre eso aquí...",
        ["You need to log into a members' world to begin the Diamond in the Rough quest."] = "Debes iniciar sesión en el mundo de un miembro para comenzar la misión Diamante en bruto.",
        ["Well done. A great rescue. I will remember you if I have anything dangerous to do."] = "Bien hecho. Un gran rescate. Te recordaré si tengo algo peligroso que hacer.",
        ["One other thing... Ozan gave me something to give to you."] = "Otra cosa... Ozan me dio algo para darte.",
        ["Would you like to claim your reward lamps?"] = "¿Quieres reclamar tus lámparas de recompensa?",
        ["Yes."] = "Sí.",
        ["You will need at least [1/2/3/4/5/6] inventory spaces to receive all of your lamps from Osman."] = "Necesitará al menos [1/2/3/4/5/6] espacios de inventario para recibir todas sus lámparas de Osman.",
        ["[Osman hands you [1/2/3/4/5/6] reward lamps for your help in rescuing Prince Ali.]"] = "[Osman te entrega lámparas de recompensa [1/2/3/4/5/6] por tu ayuda para rescatar al Príncipe Ali.]",
        ["Is there anything with which I can help you?"] = "¿Hay algo en lo que pueda ayudarte?",
        ["Actually, there is one thing you could do for me."] = "En realidad, hay una cosa que podrías hacer por mí.",
        ["And what would that be?"] = "¿Y cuál sería?",
        ["You could get me some sq'irk juice."] = "Podrías traerme un poco de jugo de sq'irk.",
        ["I'd like to talk to you about sq'irks."] = "Me gustaría hablarte sobre los sq'irks.",
        ["I have some sq'irk juice for you."] = "Tengo un poco de jugo de sq'irk para ti.",
        ["You receive some Thieving advice ([number] Thieving experience points) as a reward for the sq'irk juice."] = "Recibirás algunos consejos Thieving (puntos de experiencia [número] Thieving) como recompensa por el jugo sq'irk.",
        ["Thank you very much Player. If you get some more sq'irks be sure to come back."] = "Muchas gracias Player. Si consigues más preguntas, asegúrate de volver.",
        ["I will. It's been a pleasure doing business with you."] = "Lo haré. Ha sido un placer hacer negocios con usted.",
        ["Select an Option"] = "Selecciona una opción",
        ["Where am I meant to find sq'irks?"] = "¿Dónde debo encontrar sq'irks?",
        ["There is a sorceress near the south-eastern edge of Al Kharid who grows them. She used to be a friend to Al Kharid, but there was a falling out."] = "Hay una hechicera cerca del borde sureste de Al Kharid que los cultiva. Solía ​​ser amiga de Al Kharid, pero hubo una pelea.",
        ["That is a story for another time. However, now she won't give me any more fruit."] = "Esa es una historia para otro momento. Sin embargo, ahora ya no me da más frutos.",
        ["Oh, come on, it should be easy enough to find."] = "Oh, vamos, debería ser bastante fácil de encontrar.",
        ["Her garden is well hidden. I believe her garden must be hidden by magical means."] = "Su jardín está bien escondido. Creo que su jardín debe estar escondido por medios mágicos.",
        ["I'll reward you for as many as you can get your hands on, but could you please squeeze the fruit into a glass first?"] = "Te recompensaré por todas las que puedas conseguir, pero ¿podrías exprimir la fruta en un vaso primero?",
        ["I've another question about sq'irks."] = "Tengo otra pregunta sobre los sq'irks.",
        ["What would you like to know?"] = "¿Qué te gustaría saber?",
        ["Thanks for the information."] = "Gracias por la información.",
        ["There was an incident between her and the city. Now she won't give us fruit from her garden."] = "Hubo un incidente entre ella y la ciudad. Ahora no nos dará frutos de su jardín.",
        ["Ah it's sweet, sweet nectar; it makes light fingers lighter, fleet feet flightier and comes in four different colours for those who are easily amused."] = "Ah, es dulce, dulce néctar; hace que los dedos ligeros sean más ligeros y los pies ligeros más voladores y viene en cuatro colores diferentes para quienes se divierten fácilmente.",
        ["He starts salivating at the thought of sq'irk juice."] = "Empieza a salivar al pensar en el jugo de sq'irk.",
        ["Hi, Osman! How are you doing?"] = "¡Hola, Osman! ¿Cómo estás?",
        ["My wounds are healing slowly but I think I'll make a full recovery."] = "Mis heridas se están curando lentamente pero creo que me recuperaré por completo.",
        ["How is Maisa? Is she back in Al Kharid?"] = "¿Cómo es Maisa? ¿Está de vuelta en Al Kharid?",
        ["Maisa is fine. Where she is or what she's doing, I couldn't possibly tell you."] = "Maisa está bien. Dónde está o qué está haciendo, no podría decírtelo.",
        ["One piece of espionage gossip I can tell you is that I won't be returning to Sophanem or Menaphos any time soon."] = "Un chisme de espionaje que puedo contarles es que no volveré a Sophanem o Menaphos en el corto plazo.",
        ["Did you know Maisa is in Sophanem, giving out quests?"] = "¿Sabías que Maisa está en Sophanem y ofrece misiones?",
        ["It's my job to know everything. Just don't believe everything you hear about me. I'm going to surprise them all one day... Pleasantly, that is."] = "Mi trabajo es saberlo todo. Simplemente no creas todo lo que oyes sobre mí. Algún día los sorprenderé a todos... Gratamente, eso es.",
        ["Is there anything else with which I can help you?"] = "¿Hay algo más en lo que pueda ayudarte?",
        ["Do you know anything about Keris, the dagger I recovered in the course of my last mission?"] = "¿Sabes algo sobre Keris, la dagger que recuperé durante mi última misión?",
        ["We discovered a stash of them in some of our investigations. As far as we have been able to determine, it was created by worshippers of Elidinis in order to smite the followers of Scabaras."] = "Descubrimos un alijo de ellos en algunas de nuestras investigaciones. Hasta donde hemos podido determinar, fue creado por adoradores de Elidinis para herir a los seguidores de Scabaras.",
        ["So what is so good about them?"] = "Entonces, ¿qué tienen de bueno?",
        ["They are specially enchanted against both scarab creatures and kalphites...which is odd, since we thought the two races to be entirely different. Any more details you'll have to discover yourself by using it in the field."] = "Están especialmente encantados contra criaturas escarabajos y kalfitas... lo cual es extraño, ya que pensábamos que las dos razas eran completamente diferentes. Cualquier detalle más tendrás que descubrirlo tú mismo usándolo en el campo.",
        ["Thanks."] = "Gracias.",
    },
    ["Ospak"] = {
        ["Shhh! I'm waiting for the show!"] = "¡Shhh! ¡Estoy esperando el espectáculo!",
        ["What's on the bill?"] = "¿Qué hay en la factura?",
        ["Nothing an outerlander would enjoy!"] = "¡Nada que un extranjero disfrutaría!",
        ["There's a performance of an epic from olden times tonight! The epic of Bukalla!"] = "¡Esta noche hay una presentación de una epopeya de tiempos antiguos! ¡The epic of Bukalla!",
        ["Select an option"] = "Seleccione una opción",
        ["Bukalla?"] = "¿Bukalla?",
        ["He was a famed slayer of daggermouths in olden times. It's a very inspirational song."] = "Era un famoso cazador de bocas de daga en la antigüedad. Es una canción muy inspiradora.",
        ["Sounds interesting! Maybe I'll stick around."] = "¡Suena interesante! Quizás me quede por aquí.",
        ["The Epic of Bukalla is a live recorded poem, roughly five minutes in length. We suggest that you turn your sound on in order to get the most out of it."] = "The Epic of Bukalla es un poema grabado en vivo, de aproximadamente cinco minutos de duración. Le sugerimos que active el sonido para aprovecharlo al máximo.",
        ["I'm ready to hear it!"] = "¡Estoy listo para escucharlo!",
        ["Wait a second!"] = "¡Espera un segundo!",
        ["Sounds boring"] = "Suena aburrido",
        ["Sounds boring."] = "Suena aburrido.",
        ["Well, you're missing out on a glorious piece of history."] = "Bueno, te estás perdiendo una gloriosa parte de la historia.",
    },
    ["Osvald"] = {
        ["Welcome to the Miscellania food store. We've only opened recently."] = "Bienvenido a la tienda de alimentos Miscellania. Abrimos recientemente.",
        ["Would you like to buy anything, your Royal Highness?"] = "¿Le gustaría comprar algo, Alteza Real?",
        ["Select an Option"] = "Selecciona una opción",
        ["Could you show me what you have for sale?"] = "¿Podrías mostrarme lo que tienes a la venta?",
        ["No thank you, I don't need food just now."] = "No, gracias, no necesito comida en este momento.",
        ["What's it like living down here?"] = "¿Cómo es vivir aquí abajo?",
        ["The town's thriving. I'm sure it'll soon be as busy as Rellekka!"] = "La ciudad está prosperando. ¡Estoy seguro de que pronto estará tan ocupado como Rellekka!",
    },
    ["Otavea"] = {
        ["**Otavea** Hello Player, Lovely weather we're having today."] = "**Otavea** Hola Player, Hoy tenemos un clima maravilloso.",
        ["Greetings Player, what brings you here?"] = "Saludos Player, ¿qué te trae por aquí?",
        ["Hello Otavea. I've been sent to make sure you and your people are doing okay, under the circumstances."] = "Hola Otavea. Me han enviado para asegurarme de que usted y su gente estén bien, dadas las circunstancias.",
        ["That's much appreciated Player. There has been some trying times recently. But there is hope on the horizon for our people, with new land for us and new generations in the future."] = "Eso se lo agradece mucho Player. Ha habido algunos momentos difíciles recientemente. Pero hay esperanza en el horizonte para nuestro pueblo, con nuevas tierras para nosotros y nuevas generaciones en el futuro.",
        ["Speaking of. I'm in the process of running supplies from the mainland to the island you refer to as Anachronia."] = "Hablando de eso. Estoy en el proceso de llevar suministros desde el continente a la isla a la que te refieres como Anacronia.",
        ["Some of my ilujanka have began integrating into life on the island. Apparently rearing some mighty creatures, and 'pruning' some of the local fungi!"] = "Algunos de mis ilujanka han comenzado a integrarse a la vida en la isla. ¡Aparentemente criando algunas criaturas poderosas y \"podando\" algunos de los hongos locales!",
        ["I have Luke the Gurh here with me. Could you put together a nice dish for him to eat? He's been working hard and needs to keep his energy up."] = "Tengo a Luke the Gurh aquí conmigo. ¿Podrías prepararle un rico plato para comer? Ha estado trabajando duro y necesita mantener su energía.",
        ["Just mix this redcane together with some fresh vegetables, that should perk him up!"] = "Simplemente mezcla este caña roja con algunas verduras frescas, ¡eso debería animarlo!",
        ["On it!"] = "¡Adelante!",
        ["Thank you kindly Player. Here is some redcane!"] = "Gracias amablemente Player. ¡Aquí hay algo de caña roja!",
        ["Hello Player. Have you had any success with my gurh?"] = "Hola Player. ¿Has tenido algún éxito con mi gurh?",
        ["I'm still working on it."] = "Todavía estoy trabajando en ello.",
        ["You'll be needing some redcane to make a nice medley. I'll give you some redcane once you have some space in your backpack."] = "Necesitarás un poco de caña roja para hacer un buen popurrí. Te daré un poco de caña roja una vez que tengas algo de espacio en tu backpack.",
        ["You'll be needing some redcane to make a nice medley. Here you go!"] = "Necesitarás un poco de caña roja para hacer un buen popurrí. ¡Aquí tienes!",
        ["Not to worry. Don't forget to use that redcane to create a tasty treat!"] = "No te preocupes. ¡No olvides usar ese bastón rojo para crear un delicioso manjar!",
        ["**Otavea** Thanks for the assistance Player. Luke the Gurh seems much happier now."] = "**Otavea** Gracias por la ayuda Player. Luke the Gurh parece mucho más feliz ahora.",
        ["**Otavea** I'll get these supplies shipped off shortly. Do pay a visit to my friends on the island if you get a chance. I hear they're creating some items of interest with a nice young lady."] = "**Otavea** Enviaré estos suministros en breve. Visita a mis amigos en la isla si tienes la oportunidad. He oído que están creando algunos artículos de interés con una simpática joven.",
    },
    ["Otto Godblessed"] = {
        ["*When speaking to Otto Godblessed without items related to Barbarian training; Barbarian skills will always be given before My notes.*"] = "*Al hablar con Otto Godblessed sin elementos relacionados con el entrenamiento bárbaro; Las habilidades bárbaras siempre se darán antes de Mis notas.*",
        ["*If the player has a free inventory slot and no copy of Barbarian skills in their bank or inventory:*"] = "*Si el player tiene un espacio de inventario libre y no tiene ninguna copia de las habilidades de Bárbaro en su banco o inventario:*",
        ["I see you have free space and no record of the tasks I have set you. Please take this book as a record of your progress - between the spirits and your diligence, I expect it will always be up to date."] = "Veo que tienes espacio libre y no tienes registro de las tareas que te he asignado. Por favor, tome este libro como un registro de su progreso; entre el espíritu y su diligencia, espero que siempre esté actualizado.",
        ["*If the player has a free inventory slot and no copy of My notes in their bank or inventory:*"] = "*Si el player tiene un espacio de inventario libre y no tiene ninguna copia de Mis notas en su banco o inventario:*",
        ["I see you have free space and no way to record any information you may recover from the caverns. Please take this book as a record of your researches - between the spirits and your diligence I expect it will always be up to date."] = "Veo que tienes espacio libre y no hay forma de registrar la información que puedas recuperar de las cavernas. Por favor, tome este libro como un registro de sus investigaciones; entre el espíritu y su diligencia espero que siempre esté actualizado.",
        ["Why might I need such a thing? I already have a book of notes."] = "¿Por qué podría necesitar algo así? Ya tengo un libro de notas.",
        ["Those who have previously entered the cavern have not all returned, some of them seemed intent upon research and discovery as much as loot and daring deeds. It would be a shame if you were to recover any of their notes and be unable to record them handily. I hope the new book will give you space for such discoveries."] = "No todos los que entraron previamente a la caverna han regresado, algunos de ellos parecían decididos a investigar y descubrir tanto como a saquear y realizar hazañas audaces. Sería una pena que recuperaras alguna de sus notas y no pudieras registrarlas cómodamente. Espero que el nuevo libro le dé espacio para tales descubrimientos.",
        ["*When speaking to Otto Godblessed at Otto's Grotto, after having completed all of Barbarian training.*"] = "*Al hablar con Otto Godblessed en Otto's Grotto, después de haber completado todo el entrenamiento bárbaro.*",
        ["Welcome back oh friend of the spirits, I am humbled in your presence."] = "Bienvenido de nuevo, oh amigo de los espíritus, me siento honrado en tu presencia.",
        ["That's very kind, but I was wondering whether you have any more information for me?"] = "Es muy amable, pero me preguntaba si tienes más información para mí.",
        ["You are no longer the apprentice, but the master. Seek to inspire us with your daring deeds and legendary feats. Aspire to join the spirits when your time comes."] = "Ya no eres el aprendiz, sino el maestro. Busca inspirarnos con tus audaces hazañas y hazañas legendarias. Aspira a unirte a los espíritus cuando llegue tu momento.",
        ["Choose an option"] = "Elige una opción:",
        ["Could you tell me more of these spirits you continually refer to?"] = "¿Podrías contarme más sobre estos espíritus a los que te refieres continuamente?",
        ["Certainly, though it is quite simple - they are the barbarians of the past, who have died in the passing of the years. There are three categories which learned sages claim may describe all spirits encountered. The majority are at peace, having died with their ambitions sated, even if this ambition was as simple as a glorious death. They can contact those in our world in order to spur us on to glory. Of course, they cannot or will not contact all inhabitants of these lands. All are not worthy."] = "Ciertamente, aunque es bastante simple: son los bárbaros del pasado, que han muerto con el paso de los años. Hay tres categorías que, según los sabios eruditos, pueden describir todos los espíritus encontrados. La mayoría está en paz, habiendo muerto con sus ambiciones saciadas, aunque esta ambición fuera tan simple como una muerte gloriosa. Pueden contactar a aquellos en nuestro mundo para impulsarnos a la gloria. Por supuesto, no pueden o no quieren contactar a todos los habitantes de estas tierras. No todos son dignos.",
        ["So those are the spirits who give us guidance. What of the other sorts?"] = "Entonces esos son los espíritus que nos guían. ¿Qué pasa con los otros tipos?",
        ["A second category of spirit is made up of those who are not yet at peace. However, all that is needed is for their mortal remains to be laid to rest and they will join the peaceful majority."] = "Una segunda categoría de espíritu está formada por aquellos que aún no están en paz. Sin embargo, todo lo que se necesita es que sus restos mortales sean enterrados y se unan a la mayoría pacífica.",
        ["I can see the pyres serve this purpose. The final category is also restless?"] = "Veo que las piras sirven para este propósito. ¿La categoría final también está inquieta?",
        ["Alas, there is a small minority who will never be at rest. These have been slain in moments of insanity by their brothers or by adventurers. They are not at rest and will attack those they blame for their tortured state. They are not known, however, for being able to determine this blame with any great accuracy, so may be considered as dangerous to all."] = "Lamentablemente, hay una pequeña minoría que nunca descansará. Estos han sido asesinados en momentos de locura por sus hermanos o por aventureros. No están tranquilos y atacarán a quienes culpan de su estado de tortura. Sin embargo, no son conocidos por ser capaces de determinar esta culpa con gran precisión, por lo que pueden considerarse peligrosos para todos.",
        ["I thank you Otto, it makes a bit more sense now."] = "Te agradezco Otto, ahora tiene un poco más de sentido.",
        ["I wish to change my fishing style"] = "Deseo cambiar mi estilo de pesca",
        ["I wish to change how I fish."] = "Deseo cambiar mi forma de pescar.",
        ["So be it."] = "Que así sea.",
        ["You revert to default fishing techniques."] = "Vuelve a las técnicas de pesca predeterminadas.",
        ["You revert to barbarian fishing techniques."] = "Vuelves a las técnicas de pesca bárbaras.",
        ["I have no more questions at this time."] = "No tengo más preguntas en este momento.",
        ["In that case, farewell."] = "En ese caso, adiós.",
    },
    ["Overseer Siv"] = {
        ["This looks like a good spot for a command centre."] = "Este parece un buen lugar para un centro de mando.",
        ["Welcome to the command centre."] = "Bienvenido al centro de mando.",
        ["**Select an Option**"] = "**Seleccione una opción**",
        ["What does a command centre do?"] = "¿Qué hace un centro de mando?",
        ["With a functioning command centre you will have remote access to all your global operations."] = "Con un centro de comando en funcionamiento, tendrá acceso remoto a todas sus operaciones globales.",
        ["Global operations?"] = "¿Operaciones globales?",
        ["Surely a great person like you must have more going on beyond these walls. You can manage all of it from here."] = "Seguramente una gran persona como tú debe tener más cosas que hacer más allá de estos muros. Puedes gestionarlo todo desde aquí.",
        ["Surely a [Title] like you must have more going on beyond these walls. You can manage all of it from here."] = "Seguramente un [Title] como tú debe tener más cosas que hacer más allá de estas paredes. Puedes gestionarlo todo desde aquí.",
        ["Ask about Miscellania."] = "Pregunta por Miscellania.",
        ["Do you have any holdings in Miscellania?"] = "¿Tiene alguna participación en Miscellania?",
        ["Not as such, no."] = "No como tal, no.",
        ["Complete the Throne of Miscellania quest to unlock Managing Miscellania."] = "Completa la misión del Trono de Miscellania para desbloquear la Gestión de Miscellania.",
        ["I have a whole Kingdom in Miscellania, actually."] = "De hecho, tengo todo un reino en Miscellania.",
        ["You're [Fremennik name]? I had no idea."] = "¿Eres [Fremennik name]? No tenía ni idea.",
        ["I imagine you're finding it hard to keep your subjects happy?"] = "Me imagino que te resultará difícil mantener contentos a tus súbditos.",
        ["It can be a bit of a chore."] = "Puede ser un poco complicado.",
        ["Through the command we could organise a care package system, if we have the resources and you can fund it."] = "A través del comando podríamos organizar un sistema de paquetes de atención, si tenemos los recursos y puedes financiarlo.",
        ["You can pay gold to improve subject approval. This requires a tier 3 command centre."] = "Puedes pagar oro para mejorar la aprobación de los sujetos. Esto requiere un centro de mando de nivel 3.",
        ["Ask about Anachronia."] = "Pregunta sobre Anacronía.",
        ["Anachronia? Have you been there?"] = "¿Anacronía? ¿Has estado allí?",
        ["Travel to Anachronia aboard the Stormbreaker, docked at the Archaeology Guild, to unlock the Base Camp."] = "Viaja a Anacronia a bordo del Stormbreaker, atracado en el gremio Archaeology, para desbloquear el campamento base.",
        ["I manage the base camp on Anachronia."] = "Administro el campamento base en Anacronia.",
        ["Always in need of more labour, I assume. I'm sure we can organise something."] = "Supongo que siempre necesito más mano de obra. Estoy seguro de que podemos organizar algo.",
        ["Couldn't hurt."] = "No podría hacer daño.",
        ["Building tier 2 and 3 of the command centre each add 5 workers to your Base Camp."] = "Los niveles de construcción 2 y 3 del centro de comando agregan cada uno 5 trabajadores a su campamento base.",
        ["Ask about Archaeology."] = "Pregunta por Archaeology.",
        ["Archaeology? Is that a specialisation of yours?"] = "¿Archaeology? ¿Es esa una especialización tuya?",
        ["Not really."] = "En realidad, no.",
        ["Reach level 40 Archaeology and attain the Assistant qualification to unlock Research."] = "Alcanza el nivel 40 Archaeology y obtén la calificación de Asistente para desbloquear la Investigación.",
        ["My team of crack researchers are always busy at the Archaeology Guild."] = "Mi equipo de investigadores de crack siempre está ocupado en el Gremio Archaeology.",
        ["We are in the Wilderness. I'm sure we can dig up something interesting to send them."] = "Estamos en el Wilderness. Estoy seguro de que podemos encontrar algo interesante para enviarles.",
        ["A tier 2 command centre reduces research costs by 3%. A tier 3 command centre increases research speed by 3%."] = "Un centro de mando de nivel 2 reduce los costos de investigación en un 3%. Un centro de mando de nivel 3 aumenta la velocidad de investigación en un 3%.",
        ["Ask about Player-owned Ports."] = "Pregunte acerca de los puertos propiedad de Player.",
        ["Do you spend much of your time hanging around in ports?"] = "¿Pasas gran parte de tu tiempo merodeando por los puertos?",
        ["Reach level 90 Agility, Construction, Cooking, Divination, Dungeoneering, Fishing, Herblore-"] = "Alcanza el nivel 90 Agility, Construction, Cooking, Divination, Dungeoneering, Fishing, Herblore-",
        ["*gasp*"] = "*jadeo*",
        ["-Hunter, Prayer, Runecrafting, Slayer or Thieving to unlock Player-owned Ports."] = "-Hunter, Prayer, Runecrafting, Slayer o Thieving para desbloquear puertos propiedad de Player.",
        ["I do like to send the occasional voyage out to the Eastern Lands from my merchant venture."] = "Me gusta enviar algún viaje ocasional a las Tierras del Este desde mi empresa comercial.",
        ["Well that's no problem. We Fremennik are the world's greatest merchant sailors."] = "Bueno, eso no es problema. Nosotros, los Fremennik, somos los mejores marinos mercantes del mundo.",
        ["With enough resources, I'm sure we can make some efficiency savings."] = "Con suficientes recursos, estoy seguro de que podemos lograr algunos ahorros de eficiencia.",
        ["Ports missions gain a 3%, 6% and 10% boost to success chance at tier 1, 2 and 3 of the command centre respectively."] = "Las misiones de los puertos obtienen un aumento del 3%, 6% y 10% en las posibilidades de éxito en los niveles 1, 2 y 3 del centro de comando, respectivamente.",
        ["Goodbye."] = "Adiós.",
    },
    ["Overseer"] = {
        ["*When speaking to Overseer at the Sawmill*"] = "*Al hablar con Overseer en el Aserradero*",
        ["Yes? What do you want? I'm very busy!"] = "¿Sí? ¿Qué deseas? ¡Estoy muy ocupado!",
        ["Select an option"] = "Seleccione una opción",
        ["What is this place?"] = "¿Qué es este lugar?",
        ["This is the sawmill training area, where we take the more qualified woodcutters on work experience."] = "Esta es el área de capacitación del aserradero, donde llevamos a los leñadores más calificados en experiencia laboral.",
        ["Work experience?"] = "¿Experiencia laboral?",
        ["Yeah. You work, you gain experience. You DO NOT gain planks, as I have to tell everyone."] = "Sí. Trabajas, ganas experiencia. NO ganas planks, como tengo que decirles a todos.",
        ["Not even a few..."] = "Ni siquiera unos pocos...",
        ["NO PLANKS!"] = "¡NO PLANKS!",
        ["Okay, okay."] = "Está bien, está bien.",
        ["Who are you?"] = "¿Quién eres?",
        ["The name's Jill. I'm the sawmill overseer."] = "El nombre es Jill. Soy el supervisor del aserradero.",
        ["Pleased to meet y-"] = "Encantado de conocerte-",
        ["I'm in charge of this place, so no fooling around!"] = "Estoy a cargo de este lugar, ¡así que no pierdas el tiempo!",
        ["What should I be doing?"] = "¿Qué debería estar haciendo?",
        ["Well, first grab a job from the board. There's short and long jobs: pick whichever you fancy. Then you stock up on wood from the piles and stack it in the hopper. The machine will do its magic and, before you know it, you'll have a stack of planks at the other end. Take these, with a saw, to the workbench to cut the planks you need. All the finished planks go straight into the cart, but you can take out any excess planks and use them for the next batch, if you like. Just let me know when you're ready to send an order."] = "Bueno, primero consigue un trabajo del tablero. Hay trabajos cortos y largos: elige el que más te guste. Luego se abastece de madera de las pilas y se apila en la tolva. La máquina hará su magia y, antes de que te des cuenta, tendrás una pila de planks en el otro extremo. Llévalos, con una sierra, al banco de trabajo para cortar el planks que necesitas. Todo el planks terminado va directamente al carrito, pero puedes sacar el exceso de planks y usarlo para el siguiente lote, si lo deseas. Sólo avíseme cuando esté listo para enviar un pedido.",
        ["Bye."] = "Adiós.",
        ["Nothing, thanks."] = "Nada, gracias.",
    },
    ["Oxi"] = {
        ["Hello. What are you doing?"] = "Hola. ¿Qué estás haciendo?",
        ["I'm the rat keeper, it's my job to look after these here rats."] = "Soy el cuidador de las ratas, mi trabajo es cuidar de estas ratas.",
        ["You do know that there are some rats running loose?"] = "¿Sabes que hay algunas ratas sueltas?",
        ["Some nibble their way out from time to time. Don't worry there's enough cats down here to sort anything that gets out."] = "Algunos mordisquean para salir de vez en cuando. No te preocupes, hay suficientes gatos aquí abajo para clasificar cualquier cosa que salga.",
        ["So how do these rat pits work?"] = "Entonces, ¿cómo funcionan estos pozos de ratas?",
        ["The Keldagrim pits cater for those with the larger variety of cats."] = "Las fosas Keldagrim atienden a aquellos con una mayor variedad de gatos.",
        ["If you have an overgrown cat and a couple of coins you can challenge someone else who also has an overgrown cat and some spare change."] = "Si tienes un gato grande y un par de coins, puedes desafiar a otra persona que también tenga un gato grande y algo de cambio.",
        ["That sounds simple enough so far."] = "Eso suena bastante simple hasta ahora.",
        ["You then agree on a wager. It's rumoured that some ratcatchers can talk to their own cats and give them tactics to aid them."] = "Luego aceptas una apuesta. Se rumorea que algunos cazadores de ratas pueden hablar con sus propios gatos y darles tácticas para ayudarlos.",
        ["So then how do you win the challenge?"] = "Entonces, ¿cómo se gana el desafío?",
        ["I was just getting to that. Both the gamblers' cats are placed inside of the fenced off area, and whoever kills 9 rats first wins."] = "Estaba llegando a eso. Los gatos de ambos jugadores se colocan dentro del área vallada y quien mate primero a 9 ratas gana.",
        ["That sounds vile and cruel."] = "Eso suena vil y cruel.",
        ["It's a cruel world and the pits are no exception."] = "Es un mundo cruel y los boxes no son una excepción.",
        ["Each to their own I say."] = "Cada uno por su lado digo.",
        ["One more thing..."] = "Una cosa más...",
        ["Thanks for your help."] = "Gracias por tu ayuda.",
        ["It sounds a little dangerous for my cat."] = "Suena un poco peligroso para mi gato.",
        ["I agree. Cats have been known to be killed in fights."] = "Estoy de acuerdo. Se sabe que los gatos mueren en peleas.",
        ["Oh how terrible. Is there nothing you can do to save your cat?"] = "Oh, qué terrible. ¿No hay nada que puedas hacer para salvar a tu gato?",
        ["Of course there is, you can instruct it to be cautious, and it will leave once it feels as if it is in danger."] = "Por supuesto que sí, puedes indicarle que tenga cuidado y se irá una vez que sienta que está en peligro.",
        ["Oh that sounds quite wise."] = "Oh, eso suena muy sabio.",
        ["That depends on how you value your cat."] = "Eso depende de cómo valoras a tu gato.",
        ["Sorry, I don't follow."] = "Lo siento, no te sigo.",
        ["Well if your cat dies or it runs away you lose."] = "Bueno, si tu gato muere o se escapa, pierdes.",
        ["So the longer it stays in the fight the better chance you have of winning."] = "Entonces, cuanto más tiempo permanezca en la pelea, más posibilidades tendrás de ganar.",
        ["Wow that sounds like fun!"] = "¡Vaya, eso suena divertido!",
        ["I don't know about that."] = "No sé nada de eso.",
        ["One thing I know though is that it's a quick way to make and lose money."] = "Una cosa que sé es que es una forma rápida de ganar y perder dinero.",
        ["Is there a limit to how much you can bet?"] = "¿Existe un límite de cuánto puedes apostar?",
        ["Hmmm...let me see. If I'm not mistaken, you can currently bet up to a maximum of [number] coins."] = "Hmmm... déjame ver. Si no me equivoco, actualmente puedes apostar hasta un máximo de [número] coins.",
        ["That sounds like a silly amount of money to bet on a cat fight."] = "Suena como una cantidad tonta de dinero para apostar en una pelea de gatos.",
        ["You'd be surprised what some people would be willing to bet."] = "Te sorprendería lo que algunas personas estarían dispuestas a apostar.",
        ["There is a minimum bet of 100 coins too."] = "También hay una apuesta mínima de 100 coins.",
        ["Can I challenge you and your cat?"] = "¿Puedo desafiarte a ti y a tu gato?",
        ["No, not now, we don't really bet with outsiders."] = "No, ahora no, realmente no apostamos con forasteros.",
        ["But I'm not an outsider, am I not inside in the pits now?"] = "Pero no soy un outsider, ¿no estoy ahora en boxes?",
        ["I don't know, maybe once you've done something to win over my trust."] = "No lo sé, tal vez una vez que hayas hecho algo para ganarte mi confianza.",
        ["Can it be bought?"] = "¿Se puede comprar?",
        ["What?"] = "¿Qué?",
        ["Your trust."] = "Tu confianza.",
        ["No. Regular townsfolk don't like us, which leads us to distrust them and anyone else."] = "No. No agradamos a la gente común del pueblo, lo que nos lleva a desconfiar de ellos y de cualquier otra persona.",
    },
    ["Ozan"] = {
        ["It was you?"] = "¿Fuiste tú?",
        ["Ha ha ha!"] = "¡Ja, ja, ja!",
        ["It's not funny, Ozan!"] = "¡No es gracioso, Ozan!",
        ["It is, though! The look on your face..."] = "¡Pero lo es! La mirada en tu cara...",
        ["I risked life and limb to retrieve those artefacts for the museum. Then I find out that you had stolen them from the museum again!"] = "Arriesgué mi vida para recuperar esos artefactos para el museo. ¡Entonces descubrí que los habías robado otra vez del museo!",
        ["The artefacts were in storage. They'd finished studying them."] = "Los artefactos estaban almacenados. Habían terminado de estudiarlos.",
        ["You never finish studying something."] = "Nunca terminas de estudiar algo.",
        ["We've often had to steal museum artefacts for a mission."] = "A menudo hemos tenido que robar objetos de museo para una misión.",
        ["Yes, when we needed something and the museum wouldn't give it up, and then we returned them afterwards. Ozan stole these for private collectors."] = "Sí, cuando necesitábamos algo y el museo no nos lo daba, y luego lo devolvíamos. Ozan los robó para coleccionistas privados.",
        ["Aw, it was just from a museum. It wasn't like I took food from poor families..."] = "Ah, era sólo de un museo. No era como si tomara comida de familias pobres...",
        ["That old man nearly took down the Tower. Traiborn had to break out one of his thingummywuts."] = "Ese old man casi derriba la Torre. Traiborn tuvo que sacar una de sus cositas.",
        ["Ozan, you must have heard stories about him."] = "Ozan, debes haber escuchado historias sobre él.",
        ["Hundreds. They can't possibly be true, though. I know exaggeration when I see it."] = "Cientos. Sin embargo, no es posible que sean ciertas. Reconozco la exageración cuando la veo.",
        ["Hey, it's our newest guild member!"] = "¡Oye, es nuestro miembro más nuevo del gremio!",
        ["I told you Player would make it into the guild. Didn't I tell you?"] = "Te dije que Player entraría al gremio. ¿No te lo dije?",
        ["Several times, at length."] = "Varias veces, extensamente.",
        ["It was nothing."] = "No fue nada.",
        ["I don't think you understand what being an adventurer is all about."] = "No creo que entiendas de qué se trata ser un aventurero.",
        ["It's about the legend! The glory! Bards will sing of our exploits for generations - but only if we teach them the songs!"] = "¡Se trata de la leyenda! ¡La gloria! Los bardos cantarán nuestras hazañas durante generaciones, ¡pero sólo si les enseñamos las canciones!",
        ["What about you, Ariane?"] = "¿Y tú, Ariane?",
        ["It's about making the world a better place."] = "Se trata de hacer del mundo un lugar mejor.",
        ["Goodbye."] = "Adiós.",
        ["It was one of many epic adventures!"] = "¡Fue una de muchas aventuras épicas!",
        ["I know! I've heard the stories about you. I've passed some of them on myself!"] = "¡Lo sé! He oído historias sobre ti. ¡Me he pasado algunos de ellos!",
        ["Changing them to stories about you."] = "Cambiándolas a historias sobre ti.",
        ["Or inserting yourself as the one who saves the day."] = "O insertarte como quien salva el día.",
        ["Don't listen to her, Player! All my stories are the unembellished facts."] = "¡No la escuches, Player! Todas mis historias son hechos sin adornos.",
        ["That's the tallest tale I've heard for a while."] = "Ese es el cuento más fantástico que he escuchado en mucho tiempo.",
        ["Who are you people?"] = "¿Quiénes son ustedes?",
        ["I'm sorry, I thought you knew each other."] = "Lo siento, pensé que se conocían.",
        ["Player, sadly there's just the two of us at the moment. This is Ozan."] = "Player, lamentablemente solo estamos nosotros dos en este momento. Este es Ozan.",
        ["We have not seen Sir Owen here for some time..."] = "Hace tiempo que no vemos a Sir Owen por aquí...",
        ["No need to introduce yourself, Player. Ariane has told me all about you."] = "No es necesario que te presentes, Player. Ariane me ha contado todo sobre ti.",
        ["You're a worthy addition to the guild."] = "Eres una valiosa incorporación al gremio.",
        ["Okay, you got into the tomb. How big was it?"] = "Está bien, entraste en la tumba. ¿Qué tan grande era?",
        ["It was about fifty metres long, ten wide, and five high."] = "Tenía unos cincuenta metros de largo, diez de ancho y cinco de alto.",
        ["No, no! I don't want to know its measurements. You've got to say how big it was!"] = "¡No, no! No quiero saber sus medidas. ¡Tienes que decir lo grande que era!",
        ["I just said..."] = "Acabo de decir...",
        ["You need to give a sense of how big it was. Your flickering torchlight could not penetrate the dust to the far wall. The sound of your footfalls was lost in the immensity as the weight of ages pressed down on you..."] = "Tienes que dar una idea de lo grande que era. La luz parpadeante de tu antorcha no pudo atravesar el polvo hasta la pared del fondo. El sonido de tus pasos se perdió en la inmensidad mientras el peso de las edades te presionaba...",
        ["Um, alright. It was...very big?"] = "Mmm, está bien. Era... ¿muy grande?",
        ["That's a start. What did you find in the tomb?"] = "Eso es un comienzo. ¿Qué encontraste en la tumba?",
        ["There were fourteen skeletons in various states of-"] = "Había catorce esqueletos en varios estados de-",
        ["Ah! So you battled with the skeletons! Unsleeping guardians, enraged at your intrusion into-"] = "¡Ah! ¡Así que luchaste con los esqueletos! Guardianes insomnes, enfurecidos por vuestra intrusión en...",
        ["No, ordinary skeletons. The old king's servants had been buried in the outer chamber to provide for him in the next life."] = "No, esqueletos ordinarios. Los sirvientes del viejo rey habían sido enterrados en la cámara exterior para sustentarlo en la próxima vida.",
        ["The old king's guards had been buried there to protect him, and you fought them with magic fireballs! No one wants to hear a story about burial customs."] = "Los guardias del viejo rey habían sido enterrados allí para protegerlo, ¡y tú luchaste contra ellos con bolas de fuego mágicas! Nadie quiere oír una historia sobre costumbres funerarias.",
        ["Well, okay. Whgen I had...got past...the skeletons, there was a locked door. I had to figure out its mechanism."] = "Bueno, está bien. Cuando había... superado... los esqueletos, había una puerta cerrada con llave. Tuve que descubrir su mecanismo.",
        ["While the walls were closing in? With spikes?"] = "¿Mientras los muros se cerraban? ¿Con púas?",
        ["No, there was no pressure. Actually, I left the tomb at that point to read up on that type of mechanism, back at the Tower."] = "No, no hubo presión. En realidad, salí de la tumba en ese momento para leer sobre ese tipo de mecanismo, allá en la Torre.",
        ["You can't make an exciting story about reading books! No, the walls were closing in, and you got the door open just in time. And, on the other side, you saw..."] = "¡No se puede crear una historia emocionante leyendo libros! No, las paredes se estaban cerrando y abriste la puerta justo a tiempo. Y, del otro lado, viste...",
        ["There was a marble sarcophagus about three metres-"] = "Había un sarcófago de mármol de unos tres metros-",
        ["*Ahem*"] = "*Ejem*",
        ["A...huge...marble sarcophagus...studded with jewels, and carved into a...terrifying visage."] = "Un... enorme... sarcófago de mármol... tachonado de joyas y tallado en un... rostro aterrador.",
        ["That's better. And then?"] = "Eso está mejor. ¿Y luego?",
        ["Inside the sarcophagus...inside the sarcophagus, I found the king's burial mask, solid gold and carved all over with hieroglyphics."] = "Dentro del sarcófago... dentro del sarcófago, encontré la máscara funeraria del rey, de oro macizo y tallada con jeroglíficos por todas partes.",
        ["An ancient artefact of mystical power!"] = "¡Un antiguo artefacto de poder místico!",
        ["It wasn't..."] = "No fue...",
        ["An ancient artefact...whose powers we have yet to unlock."] = "Un artefacto antiguo... cuyos poderes aún tenemos que desbloquear.",
        ["There! You're getting the idea. Now change the main character to me, and you've got the perfect story!"] = "¡Ahí! Estás entendiendo la idea. ¡Ahora cambia el personaje principal por mí y tendrás la historia perfecta!",
        ["I found Sir Prysin in the Blue Moon Inn the other day, telling everyone how he single-handedly defeated Delrith!"] = "¡Encontré a Sir Prysin en el Blue Moon Inn el otro día, contándoles a todos cómo derrotó a Delrith sin ayuda de nadie!",
        ["Don't worry, I set the record straight and told everyone it was you who killed the demon."] = "No te preocupes, dejé las cosas claras y les dije a todos que fuiste tú quien mató al demonio.",
        ["After that, I turned the conversation back around to myself and my own fantastic demon-slaying exploits, of course! I can't let your reputation to surpass mine!"] = "Después de eso, volví a centrar la conversación en mí y en mis fantásticas hazañas para matar demonios, ¡por supuesto! ¡No puedo permitir que tu reputación supere la mía!",
        ["I heard the story that Radimus Erkle's been telling about you in the Legends' Guild. I don't know how you got him to buy it! I mean, I've been known to exaggerate, but I keep it plausible."] = "Escuché la historia que Radimus Erkle ha estado contando sobre ti en Legends' Guild. ¡No sé cómo conseguiste que lo comprara! Quiero decir, se sabe que exagero, pero lo mantengo plausible.",
        ["Mapping a whole swathe of jungle by yourself! Going toe-to-toe with Nezikchened and defeating him - three times?"] = "¡Mapea toda una franja de jungla tú mismo! ¿Enfrentarse cara a cara con Nezikchened y derrotarlo... tres veces?",
        ["Normally I embellish the stories I tell about you, but this one I'm having to tone down or people will laugh me off the stage!"] = "Normalmente embellezco las historias que cuento sobre ti, pero esta tengo que bajarle el tono o la gente se reirá de mí fuera del escenario.",
        ["Hazelmere, dead. Cyrisus, dead. Lucien is going to pay for that someday."] = "Hazelmere, muerto. Cyrisus, muerto. Lucien va a pagar por eso algún día.",
        ["I should have been there. The Crux Eqal recruited me, Owen and Ariane to attack another of Lucien's bases, but it turned out he'd already abandoned it."] = "Debería haber estado allí. El Crux Eqal nos reclutó a Owen, a Ariane y a mí para atacar otra de las bases de Lucien, pero resultó que ya la había abandonado.",
        ["So, the other day, I went out with a cute wizard apprentice, Ilona, and she told me how you rescued her from a cult in the Lumbridge Catacombs."] = "Entonces, el otro día, salí con una linda aprendiz de mago, Ilona, y ella me contó cómo la rescataste de una secta en las catacumbas de Lumbridge.",
        ["I told her some stories about my adventures, but she kept turning the conversation back to you!"] = "Le conté algunas historias sobre mis aventuras, ¡pero ella siguió volviendo la conversación hacia ti!",
        ["If anyone asks about the time you and I got shipwrecked together and had to fight a horde of zombie trolls, or the time I saved you from the lair of the fire spiders, just nod, okay?"] = "Si alguien pregunta sobre la vez que tú y yo naufragamos juntos y tuvimos que luchar contra una horda de trolls zombies, o la vez que te salvé de la guarida de las arañas de fuego, simplemente asiente, ¿de acuerdo?",
        ["I've been adventuring with your friend Zanik lately. We teamed up to steal back some gold that the H.A.M. group had taken from Varrock Palace."] = "Últimamente he estado de aventuras con tu amigo Zanik. Nos unimos para recuperar algo de oro que H.A.M. grupo había tomado del Palacio Varrock.",
        ["We got in and out without being spotted, and returned the money. Well, we returned most of the money. Some of it might have ended up paying for that holiday we took together down to Oo'glog..."] = "Entramos y salimos sin que nos vieran y devolvimos el dinero. Bueno, devolvimos la mayor parte del dinero. Parte de ello podría haber terminado pagando esas vacaciones que tomamos juntos hasta Oo'glog...",
        ["She thinks very highly of you, you know. She says you saved her city and defeated an evil god, and when I look into those big eyes I can't believe she's exaggerating."] = "Ella piensa muy bien en ti, ¿sabes? Ella dice que salvaste su ciudad y derrotaste a un dios maligno, y cuando miro esos grandes ojos no puedo creer que esté exagerando.",
        ["Whoa, slow down there with the world-saving! At this rate, people will be telling more stories about you than me!"] = "¡Vaya, más despacio con el salvamundos! ¡A este paso, la gente contará más historias sobre ti que sobre mí!",
        ["Still, I have to hand it to you, I couldn't have done much better myself."] = "Aún así, tengo que admitirlo: yo no podría haberlo hecho mucho mejor.",
        ["Hey, you're the Champion of Crandor! Eviscerator of Elvarg! Dragon's Doom!"] = "¡Oye, eres el campeón de Crandor! ¡Destripador de Elvarg! ¡La perdición del dragón!",
        ["How Elvarg burned Crandor used to be one of my standard stories, but no one wants to hear it any more - they want to hear how you killed the dragon."] = "Cómo Elvarg quemó Crandor solía ser una de mis historias estándar, pero ya nadie quiere escucharla: quieren escuchar cómo mataste al dragón.",
        ["So, congratulations: you've become a story, and you've earned me a few storytelling coins in the taverns around here."] = "Entonces, enhorabuena: te has convertido en una historia, y me has ganado unos cuantos coins de storytelling en las tabernas de por aquí.",
        ["Did you hear? Gudrun is settling down! She's marrying a dwarf poet!"] = "¿Escuchaste? ¡Gudrun se está calmando! ¡Se va a casar con un poeta enano!",
        ["I guess that means no more nights out on the town with her. All the times she drank me under the table at the Blue Moon Inn..."] = "Supongo que eso significa no más noches de fiesta con ella. Todas las veces que me bebió debajo de la mesa en el Blue Moon Inn...",
        ["If poetry can make someone marry you, I'd better watch out! I don't want to wake up one morning and find I'd accidentally gotten married the night before!"] = "Si la poesía puede hacer que alguien se case contigo, ¡será mejor que tenga cuidado! ¡No quiero despertarme una mañana y descubrir que me casé accidentalmente la noche anterior!",
        ["Hartwin tells me that you were there when those zombies attacked Varrock. I was there too - we must have missed each other."] = "Hartwin me dice que estabas allí cuando esos zombies atacaron a Varrock. Yo también estuve allí; debimos habernos extrañado.",
        ["I guess I should thank you for saving the city! We can't let Varrock be destroyed. It's where I keep all my things! And all the things that aren't mine yet, but I'll get around to stealing someday..."] = "¡Supongo que debería agradecerte por salvar la ciudad! No podemos permitir que Varrock sea destruido. ¡Es donde guardo todas mis cosas! Y todas las cosas que aún no son mías, pero que algún día empezaré a robar...",
        ["I'm going to have to step up my game, Player! After what you did for Darren Lightfinger and his guild, it looks like I've got a challenger for the title of Master Thief of RuneScape!"] = "¡Tendré que mejorar mi juego, Player! Después de lo que hiciste por Darren Lightfinger y su gremio, ¡parece que tengo un retador por el título de Maestro Ladrón de RuneScape!",
        ["I'll need to steal something truly epic. Perhaps the Crown Jewels of Falador...or the River Salve..."] = "Necesitaré robar algo realmente épico. Quizás las Joyas de la Corona de Falador... o el Río Salve...",
        ["I heard you're another Tear of Guthix drinker! Juna is one tough audience, isn't she?"] = "¡Escuché que eres otro bebedor de Lágrimas de Guthix! Juna es un público difícil, ¿no?",
        ["She peers at me with those reptile eyes and all my banter dries up. She's got mental powers or something - I think it might be impossible to lie to her."] = "Ella me mira con esos ojos de reptil y todas mis bromas se agotan. Tiene poderes mentales o algo así. Creo que sería imposible mentirle.",
        ["Olaf the Bard has been repeating the song you played in the Rellekka Longhall! It sounds like you're a contender for RuneScape's second-best musician. The very best being me, of course!"] = "¡Olaf the Bard ha estado repitiendo la canción que tocaste en el Rellekka Longhall! Parece que eres un candidato al segundo mejor músico de RuneScape. ¡El mejor soy yo, por supuesto!",
        ["I often play on the enchanted Fremennik harp. It's true! But when I tell Olaf of that, he accuses me of being dishonest."] = "A menudo toco el arpa encantada Fremennik. ¡Es cierto! Pero cuando se lo cuento a Olaf, me acusa de ser deshonesto.",
        ["Achiettes tells me she let you try for Heroes' Guild membership. Clearly she was impressed by all the stories I'd told about you! She says you got in, too. Congratulations!"] = "Achiettes me dice que te dejó probar la membresía de Heroes' Guild. ¡Claramente quedó impresionada por todas las historias que le conté sobre ti! Ella dice que tú también entraste. ¡Felicidades!",
        ["She set me a fiendish set of tasks, and every time I came back, she thought of another one. I'm not sure those later tasks were strictly to do with Heroes' Guild membership, though..."] = "Ella me asignó una serie de tareas diabólicas y cada vez que regresaba, pensaba en otra. Sin embargo, no estoy seguro de que esas tareas posteriores tuvieran que ver estrictamente con la membresía de Heroes' Guild...",
        ["I've got you now, you thief! You've broken into the palace for the last time."] = "¡Ya te tengo, ladrón! Has irrumpido en el palacio por última vez.",
        ["What's happening here?"] = "¿Qué está pasando aquí?",
        ["I caught this man breaking into the palace. I need to hold him here until Captain Rovin comes to take him into custody."] = "Atrapé a este hombre irrumpiendo en el palacio. Necesito retenerlo aquí hasta que venga Captain Rovin y lo detenga.",
        ["I was already inside. You caught me breaking out!"] = "Ya estaba dentro. ¡Me pillaste estallando!",
        ["Alright, I caught this man breaking out of the palace. He was stealing Queen Ellamaria's bedroom slippers!"] = "Muy bien, pillé a este hombre escapando del palacio. ¡Estaba robando las pantuflas de la reina Ellamaria!",
        ["Tell the story properly, man! I leaped from the battlements into the branches of a yew tree, scaled the perimeter wall, and jumped down here, where I knew my accomplice would be waiting."] = "¡Cuenta la historia correctamente, hombre! Salté desde las almenas a las ramas de un yew tree, escalé el muro perimetral y salté aquí, donde sabía que mi cómplice estaría esperando.",
        ["Accomplice!"] = "¡Cómplice!",
        ["Accomplice? What?"] = "¿Cómplice? ¿Qué?",
        ["Accomplice Watt! You're under arrest for aiding a notorious criminal!"] = "¡Cómplice Watt! ¡Estás arrestado por ayudar a un criminal notorio!",
        ["...that was a distraction. He's gone, isn't he?"] = "...eso fue una distracción. Se ha ido, ¿no?",
        ["Yes."] = "Sí.",
        ["Thank you, stranger! I will sing the tale of how you aided Ozan, the Master Thief!"] = "¡Gracias, extraño! ¡Cantaré la historia de cómo ayudaste a Ozan, el maestro ladrón!",
        ["Look at me! I'm in Port Sarim jail!"] = "¡Mírame! ¡Estoy en la cárcel de Port Sarim!",
        ["I'm sorry?"] = "¿Lo siento?",
        ["No prison cell can hold Ozan, the Master Thief! They say he's broken out of every prison cell in Gielinor!"] = "¡Ninguna celda de prisión puede albergar a Ozan, el maestro ladrón! ¡Dicen que se ha escapado de todas las celdas de la prisión en Gielinor!",
        ["At least that's what they should say. But no one believes I've broken out of Port Sarim."] = "Al menos eso es lo que deberían decir. Pero nadie cree que me he escapado de Port Sarim.",
        ["So, I let myself get caught smuggling Karamja Rum, in the bottom of the Entrana Monks' ship - but that's another story - and I waited here for someone to come along so you could..."] = "Entonces, me dejé atrapar contrabandeando ron Karamja, en el fondo del barco de los Monjes Entrana - pero esa es otra historia - y esperé aquí a que alguien viniera para que tú pudieras...",
        ["Watch this!"] = "¡Mira esto!",
        ["And there we are!"] = "¡Y ahí estamos!",
        ["Farewell! Tell your friends about the day you saw Ozan, Master Thief of Gielinor, escape from Port Sarim jail!"] = "¡Adiós! ¡Cuéntale a tus amigos sobre el día que viste a Ozan, el maestro ladrón de Gielinor, escapar de la cárcel de Port Sarim!",
        ["Player! I didn't know you were a member of the Thieves' Guild!"] = "¡Player! ¡No sabía que eras miembro del Gremio de Ladrones!",
        ["Not only a member, Ozan. Player helped us to get the Guild up and running."] = "No solo un miembro, Ozan. Player nos ayudó a poner en funcionamiento el gremio.",
        ["Haha! Darren, you rogue, I knew you'd swindle someone into doing all your work for you!"] = "¡Jaja! Darren, pícaro, ¡sabía que estafarías a alguien para que hiciera todo el trabajo por ti!",
        ["That's not how it was at all, Ozan. Player here may be the best thief in the Guild."] = "No fue así en absoluto, Ozan. Player aquí puede ser el mejor ladrón del Gremio.",
        ["I have a competitor! I must go and plan a truly elaborate heist. One that will live on in legend for a thousand years!"] = "¡Tengo un competidor! Debo ir y planear un atraco verdaderamente elaborado. ¡Uno que vivirá en la leyenda durante mil años!",
        ["Farewell, Player!"] = "¡Adiós, Player!",
        ["That Ozan...if the stories he told about himself were all true, he could be a guild full of thieves on his own. I think he's mostly hot air, though."] = "Ese Ozan... si las historias que contó sobre sí mismo fueran todas ciertas, podría ser un gremio lleno de ladrones por su cuenta. Aunque creo que es más que nada palabrería.",
        ["Anyway, back to work."] = "De todos modos, volvamos al trabajo.",
        ["Robin, have you seen my pocket watch? I'm sure I had it a moment ago..."] = "Robin, ¿has visto mi reloj de bolsillo? Estoy seguro de que lo tuve hace un momento...",
        ["Wait!"] = "¡Espera!",
        ["Come talk to me first. That is not a happy place."] = "Ven a hablar conmigo primero. Ese no es un lugar feliz.",
        ["So, about these tombs beneath the city?"] = "Entonces, ¿sobre estas tumbas debajo de la ciudad?",
        ["You should totally check them out - they are full of treasures!"] = "Deberías echarles un vistazo: ¡están llenos de tesoros!",
        ["I was more thinking about helping people and returning stolen property..."] = "Estaba pensando más en ayudar a la gente y devolver objetos robados...",
        ["Yeah, right! You want to know about the mad stacks of loot down there, and experience aplenty!"] = "¡Sí, claro! ¡Quieres saber más sobre los locos montones de botín que hay allí abajo y experimentar en abundancia!",
        ["In fact, if experience is your thing, you should check out these four statues and braziers before heading in, pick what you want to learn about."] = "De hecho, si lo tuyo es la experiencia, deberías ver estas cuatro estatuas y braseros antes de entrar y elegir lo que quieras aprender.",
        ["Well, I mean, I'm sure that will come in handy as well."] = "Bueno, quiero decir, estoy seguro de que eso también será útil.",
        ["You can't hang about down there, though. There's some magic protecting these old tombs."] = "Pero no puedes quedarte ahí abajo. Hay algo de magia protegiendo estas viejas tumbas.",
        ["They shift around all the time to disorient tomb robbers, and to protect the treasures and secrets of the pharaohs of old."] = "Se mueven todo el tiempo para desorientar a los ladrones de tumbas y proteger los tesoros y secretos de los faraones de antaño.",
        ["And whatever Amascut is doing down there is creating this icky, green corruption stuff."] = "Y lo que sea que Amascut esté haciendo ahí abajo está creando esta corrupción verde y repugnante.",
        ["I swear, I can't stay down there for more than five minutes before having to come up for fresh air."] = "Lo juro, no puedo quedarme ahí abajo más de cinco minutos antes de tener que salir a tomar aire fresco.",
        ["I dread to think what would happen to me if I stayed any longer."] = "Me da miedo pensar qué me pasaría si me quedara más tiempo.",
        ["Hey, how are things going down there? I haven't been able to find Amascut yet, nor the Kharid-ib, unfortunately. I hope you're having better luck...or at least having fun!"] = "Oye, ¿cómo van las cosas ahí abajo? Desafortunadamente, todavía no he podido encontrar a Amascut ni tampoco a Kharid-ib. Espero que tengas mejor suerte... ¡o al menos te diviertas!",
        ["**Ozan:** Any questions about these shifting tombs?"] = "**Ozan:** ¿Alguna pregunta sobre estas tumbas móviles?",
        ["Ask about shifting tombs?"] = "¿Preguntar sobre las tumbas móviles?",
        ["What's down there?"] = "¿Qué hay ahí abajo?",
        ["In one word: opportunity! There is a wealth of knowledge and, more importantly, valuable trinkets in the tombs of long-dead pharaohs below us."] = "En una palabra: ¡oportunidad! Hay una gran cantidad de conocimientos y, lo que es más importante, baratijas valiosas en las tumbas de faraones muertos hace mucho tiempo debajo de nosotros.",
        ["These tombs are magically warded to deter grave robbers, though, so you'll find that they are ever- changing."] = "Sin embargo, estas tumbas están protegidas mágicamente para disuadir a los ladrones de tumbas, por lo que descubrirás que están en constante cambio.",
        ["There do seem to be a few constants, though - the most notable of which are sealed chests - each requires a certain skill to unlock, sometimes one which you might not have...but if someone else unlocks it first, you can search"] = "Sin embargo, parece haber algunas constantes, la más notable de las cuales son los cofres sellados. Cada uno requiere una determinada habilidad para desbloquearse, a veces una que quizás no tengas... pero si alguien más la desbloquea primero, puedes buscar.",
        ["it for your share of loot."] = "tíralo por tu parte del botín.",
        ["Also, there is a crystallised form of the corruption to mine through, and lots of urns that you should smash."] = "Además, hay una forma cristalizada de corrupción que puedes extraer y muchas urnas que debes romper.",
        ["It may seem odd, but if you smash enough urns, you become empowered, and can mine through a lot of corrupt crystals very quickly!"] = "Puede parecer extraño, pero si rompes suficientes urnas, ganarás poder y podrás extraer muchos cristales corruptos muy rápidamente.",
        ["Then there are sarcophagi, each sealed with a combination - inspect each sarcophagus carefully, then look for nearby panels to open it."] = "Luego están los sarcófagos, cada uno sellado con una combinación: inspecciona cada sarcófago con atención y luego busca paneles cercanos para abrirlos.",
        ["Finally, you'll need to find the exit. If you don't escape within the time limit, you'll lose out on some of what you found, as it gets lost to the corruption."] = "Finalmente, necesitarás encontrar la salida. Si no escapas dentro del límite de tiempo, perderás parte de lo que encontraste, ya que se perderá en la corrupción.",
        ["Oh, there's actually one last thing! You won't have time to do everything alone...so take others with you. Together, you should be able to find everything, and everyone can share in the bounty. There is no downside for other people"] = "¡Oh, en realidad hay una última cosa! No tendrás tiempo para hacer todo solo... así que lleva a otros contigo. Juntos, deberían poder encontrar todo y todos podrán compartir la recompensa. No hay desventajas para otras personas.",
        ["helping you!"] = "¡ayudándote!",
        ["What are the statues and braziers for?"] = "¿Para qué sirven las estatuas y los braseros?",
        ["That's where you decide what sort of an experience you'll gain in the tombs. Each of the four statues you activate will gain the favour of a lesser god, and you'll learn different things from them."] = "Ahí es donde decides qué tipo de experiencia obtendrás en las tumbas. Cada una de las cuatro estatuas que actives obtendrá el favor de un dios menor y aprenderás cosas diferentes de ellas.",
        ["Activate each statue to start receiving XP in the relevant skill, from activities within the tombs below: Apmeken - Thieving Crondis - Construction"] = "Activa cada estatua para comenzar a recibir XP en la habilidad correspondiente, desde las actividades dentro de las tumbas a continuación: Apmeken - Thieving Crondis - Construction",
        ["It's the same deal with the braziers in front of each statue, though to a lesser degree. Those are for different skills that you'll gain less experience in, when within the tombs below."] = "Lo mismo ocurre con los braseros frente a cada estatua, aunque en menor grado. Estas son para diferentes habilidades en las que obtendrás menos experiencia cuando estés dentro de las tumbas de abajo.",
        ["Light each brazier to start receiving XP in the relevant skill, from activities within the tombs below: Apmeken - Runecrafting Crondis - Crafting"] = "Enciende cada brasero para comenzar a recibir XP en la habilidad correspondiente, de las actividades dentro de las tumbas a continuación: Apmeken - Runecrafting Crondis - Crafting",
        ["Het - Divination Scabaras - Prayer"] = "Het - Adivinación Scabaras - Prayer",
        ["The tombs will reward you more if you're higher levels in these skills too!"] = "¡Las tumbas te recompensarán más si también tienes niveles más altos en estas habilidades!",
        ["Once you reach a certain level across all the aforementioned skills, you will have access to higher tier experience rates: Tier 1: Level 50+ Tier 2: Level 70+"] = "Una vez que alcances un cierto nivel en todas las habilidades antes mencionadas, tendrás acceso a tasas de experiencia de niveles más altos: Nivel 1: Nivel 50+ Nivel 2: Nivel 70+",
        ["Tier 3: Level 90+"] = "Nivel 3: Nivel 90+",
        ["Don't just take my word for it, though. You should inspect each of the statues and braziers, and activate those of interest to you."] = "Pero no confíes sólo en mi palabra. Deberás inspeccionar cada una de las estatuas y braseros, y activar aquellos que sean de tu interés.",
        ["There's a time limit?"] = "¿Hay un límite de tiempo?",
        ["Yeah, whatever Amascut is doing down there, it's having some sort of corrupting effect. If we spend too long down there at one time, I fear it might affect us."] = "Sí, sea lo que sea que Amascut esté haciendo ahí abajo, está teniendo algún tipo de efecto corruptor. Si pasamos demasiado tiempo allí abajo, temo que nos afecte.",
        ["I wouldn't spend more than five minutes down there before coming back up for some fresh air."] = "No pasaría más de cinco minutos allí abajo antes de volver a subir para tomar un poco de aire fresco.",
        ["More importantly, you need to find and use the exit BEFORE your time runs out, else you'll lose out on some of what you've found down there."] = "Más importante aún, debes encontrar y usar la salida ANTES de que se acabe el tiempo; de lo contrario, perderás parte de lo que has encontrado allí abajo.",
        ["Will it affect me?"] = "¿Me afectará?",
        ["Hey, I'm sure you'll be fine - just don't risk it and put it to the test. Once your time is up, you can always just head straight back in."] = "Oye, estoy seguro de que estarás bien, pero no te arriesgues y ponlo a prueba. Una vez que se acabe el tiempo, siempre puedes regresar directamente.",
        ["Simply coming back to this area seems to be enough to clear any corruption that's attached itself to me."] = "Simplemente regresar a esta área parece ser suficiente para eliminar cualquier corrupción que se me haya adherido.",
        ["No questions."] = "Sin preguntas.",
        ["I heard about these sandcastles and had to come see them with my own eyes. I'd love to see a Menaphos-inspired one."] = "Escuché sobre estos castillos de arena y tuve que venir a verlos con mis propios ojos. Me encantaría ver uno inspirado en Menaphos.",
        ["You're not very subtle about what you want are you?"] = "No eres muy sutil acerca de lo que quieres, ¿verdad?",
        ["I never saw myself fighting side by side with an elf!"] = "¡Nunca me vi peleando al lado de un elfo!",
    },
    ["Oziach"] = {
        ["Good day to you."] = "Buenos días para ti.",
        ["Aye, 'tis a fair day my friend."] = "Sí, es un buen día, amigo mío.",
        ["Select an Option"] = "Selecciona una opción",
        ["I'm not your friend."] = "No soy tu amigo.",
        ["I'm surprised if you're anyone's friend with those kind of manners."] = "Me sorprende que seas amigo de alguien con ese tipo de modales.",
        ["Yes, it's a very nice day."] = "Sí, es un día muy bonito.",
        ["Aye, may the gods walk by yer side. Now leave me alone."] = "Sí, que los dioses caminen a tu lado. Ahora déjame en paz.",
        ["I ain't got nothing to sell ye, adventurer. Leave me be!"] = "No tengo nada que venderte, aventurero. ¡Déjame en paz!",
        ["Do you want to reclaim your 18,650 [Strength/Defence] XP reward lamp? It has a level 40 requirement."] = "¿Quieres reclamar tu lámpara de recompensa de 18,650 [Strength/Defence] XP? Tiene un requisito de nivel 40.",
        ["Cancel"] = "Cancelar",
        ["[You have reclaimed your 18,650 [Strength/Defence] XP lamp.]"] = "[Ha reclamado su lámpara 18,650 [Strength/Defence] XP.]",
        ["Aye, 'tis a fair day, mighty dragon-slaying friend."] = "Sí, es un buen día, poderoso amigo cazador de dragones.",
        ["Can I buy a rune platebody now, please?"] = "¿Puedo comprar un cuerpo de placas rúnicas ahora, por favor?",
        ["Can I buy a rune platebody now please?"] = "¿Puedo comprar un cuerpo de placas rúnicas ahora, por favor?",
        ["Can I have another key to Melzar's Maze?"] = "¿Puedo tener otra llave del Laberinto de Melzar?",
        ["It's the Guildmaster in the Champion's Guild who hands those keys out now. Go talk to him. No need to bother me if you don't need armour."] = "Es el Guildmaster del Gremio de Campeones quien entrega esas llaves ahora. Ve a hablar con él. No es necesario que me molestes si no necesitas armadura.",
        ["Aye, 'tis a fair day, mighty dragon-slaying friend. That's an interesting shield yer wearing. Could I have a look at it?"] = "Sí, es un buen día, poderoso amigo cazador de dragones. Es un escudo interesante el que llevas. ¿Podría echarle un vistazo?",
        ["Here you go"] = "Aquí tienes",
        ["Here you go."] = "Aquí tienes.",
        ["Hmm...where did ye get it?"] = "Hmm... ¿de dónde lo conseguiste?",
        ["The Duke of Lumbridge gave it to me. It's an anti-dragonbreath shield."] = "Me lo regaló el duque de Lumbridge. Es un escudo anti-aliento de dragón.",
        ["Ah, I thought as much!"] = "¡Ah, eso mismo pensé!",
        ["Feel how it's warm to the touch. This shield must be storing dragonfire and just letting it radiate away."] = "Siente lo cálido que es al tacto. Este escudo debe almacenar fuego de dragón y simplemente dejarlo irradiar.",
        ["Now, if there was only a way to get the dragonfire out again..."] = "Ahora, si solo hubiera una manera de sacar el fuego del dragón nuevamente...",
        ["What use would that be?"] = "¿De qué serviría eso?",
        ["Why, ain't it obvious? Ye could project blasts of dragonfire from yer shield!"] = "¿Por qué, no es obvio? ¡Podrías proyectar ráfagas de fuego de dragón desde tu escudo!",
        ["Ye know, I think there might be a way."] = "Sabes, creo que podría haber una manera.",
        ["What way?"] = "¿De qué manera?",
        ["I've heard legends of a thing called a 'draconic visage'. It was made by the dragonkin themselves, creators of the dragons, or so they say."] = "He oído leyendas sobre algo llamado \"rostro dracónico\". Fue hecho por los propios dragonantes, creadores de los dragones, o eso dicen.",
        ["This 'draconic visage' had the power to channel dragonfire. Now, if I could attach the visage to the front of this shield..."] = "Este 'rostro dracónico' tenía el poder de canalizar el fuego de dragón. Ahora, si pudiera unir el rostro al frente de este escudo...",
        ["I will look for this draconic visage!"] = "¡Buscaré este rostro dracónico!",
        ["Good luck wi' that. They're mighty rare, so yer quest will take some time. If any monsters have them, it'll be the dragons."] = "Buena suerte con eso. Son muy raros, por lo que tu búsqueda llevará algún tiempo. Si algún monstruo los tiene, serán los dragones.",
        ["Aye, 'tis a fair day, mighty dragon-slaying friend. Ye've got... Ye've found a draconic visage! Could I look at it?"] = "Sí, es un buen día, poderoso amigo cazador de dragones. Tienes... ¡Has encontrado un rostro dracónico! ¿Podría mirarlo?",
        ["Amazin'! Ye can almost feel it pulsing with draconic power!"] = "¡Increíble! ¡Casi puedes sentirlo palpitar con poder dracónico!",
        ["Now, if ye bring me this and the anti-dragonbreath shield, I reckon I could combine them into something pretty special!"] = "Ahora, si me traes esto y el escudo anti-aliento de dragón, ¡creo que podría combinarlos en algo bastante especial!",
        ["Now, if ye want me to, I could attach this to yer anti-dragonbreath shield and make something pretty special."] = "Ahora, si quieres, podría adjuntar esto a tu escudo anti-aliento de dragón y hacer algo muy especial.",
        ["The shield won't be easy to wield though; ye'll need level 70 Defence."] = "Sin embargo, el escudo no será fácil de manejar; Necesitarás el nivel 70 Defence.",
        ["I'll charge 1,250,000 coins to construct it. What d'ye say?"] = "Cobraré 1.250.000 coins por construirlo. ¿Qué dices?",
        ["Yes, please!"] = "¡Sí, por favor!",
        ["Yes please!"] = "¡Sí, por favor!",
        ["Oh yeah - how did yer want this smithed exactly?."] = "Oh, sí, ¿cómo querías que se forjara esto exactamente?",
        ["How would you like Oziach to forge the shield?"] = "¿Cómo te gustaría que Oziach forjara el escudo?",
        ["Forge towards Melee."] = "Forja hacia cuerpo a cuerpo.",
        ["[Oziach skillfully forges the shield and visage into a new shield.]"] = "[Oziach forja hábilmente el escudo y el rostro en un nuevo escudo.]",
        ["Forge towards Magic."] = "Avanza hacia Magic.",
        ["Forge towards Ranged."] = "Avanza hacia Ranged.",
        ["Forge towards Necromancy."] = "Avanza hacia Necromancy.",
        ["There ye go. Now, the more dragonfire the shield absorbs, the more powerful it'll become."] = "Ahí tienes. Ahora, cuanto más fuego de dragón absorba el escudo, más poderoso se volverá.",
        ["No, thanks."] = "No, gracias.",
        ["Suit yerself."] = "Haz lo que quieras.",
        ["That's a bit expensive!"] = "¡Eso es un poco caro!",
        ["Yes it is. But I'm a master smith so I reckon I can charge what I like. Unless ye've got level 90 Smithing too, which I doubt!"] = "Sí, lo es. Pero soy un maestro herrero así que creo que puedo cargar lo que quiera. A menos que también tengas el nivel 90 de Smithing, ¡lo cual lo dudo!",
        ["No, I don't have level 90 Smithing."] = "No, no tengo el nivel 90 de Smithing.",
        ["I thought not. I'm the master smith of Misthalin! So, shall I construct the shield for you?"] = "Pensé que no. ¡Soy el maestro herrero de Misthalin! Entonces, ¿te construyo el escudo?",
        ["Actually, I have got level 90 Smithing."] = "En realidad, tengo el nivel 90 Smithing.",
        ["Oh! Well, I suppose ye don't need me for this then."] = "¡Oh! Bueno, entonces supongo que no me necesitas para esto.",
        ["The solving of this puzzle could be the key to your treasure."] = "Resolver este rompecabezas podría ser la clave para encontrar tu tesoro.",
        ["[Oziach has given you a puzzle box!]"] = "[¡Oziach te ha regalado una caja de rompecabezas!]",
        ["That isn't right, keep trying."] = "Eso no está bien, sigue intentándolo.",
        ["[Oziach has given you another clue scroll!]"] = "[¡Oziach te ha dado otro pergamino de pistas!]",
        ["[You've found a casket!]"] = "[¡Has encontrado un ataúd!]",
        ["Well done, traveller."] = "Bien hecho, viajero.",
    },
}

dialogues.all = {
    ["Uhh... Hello?"] = "Uhh... ¿Hola?",
    ["...fully grown and right inside the walls. It's great to see a [duke/duchess/dux] that appreciates the-"] = "...completamente crecido y justo dentro de las paredes. Es genial ver un [duke/duchess/dux] que aprecia el-",
    ["Excuse me?"] = "¿Perdón?",
    ["Ah, your grace, my apologies I did not see you there."] = "Ah, majestad, mis disculpas no la vi allí.",
    ["That's quite alright. What brings you out here to Fort Forinthry?"] = "Está muy bien. ¿Qué te trae por aquí a Fort Forinthry?",
    ["That's quite alright. Aster mentioned you had an expansion proposal to discuss with me?"] = "Está muy bien. ¿Aster mencionó que tenía una propuesta de expansión que discutir conmigo?",
    ["Ah yes, your grace, have you noticed how the area to the east has been looking much healthier in recent years?"] = "Ah sí, excelencia, ¿ha notado cómo la zona del este se ha visto mucho más saludable en los últimos años?",
    ["... Now you mention it, it definitely seems to be greener out there."] = "... Ahora que lo mencionas, definitivamente parece ser más ecológico por ahí.",
    ["Indeed! Well with the area recovering, Aster reached out and suggested I inspect it to see if we could make use of it."] = "¡Efectivamente! Bueno, una vez que el área se recuperó, Aster se acercó y me sugirió que la inspeccionara para ver si podíamos utilizarla.",
    ["I've taken a look around and it looks like the area provides the perfect conditions for cultivating some trees."] = "He echado un vistazo y parece que la zona ofrece las condiciones perfectas para cultivar algunos árboles.",
    ["Hmm, I see."] = "Mmm, ya veo.",
    ["With all this construction lately, it would certainly be convenient for the fort to have own supply of timber."] = "Con toda esta construcción últimamente, sin duda sería conveniente que el fuerte tuviera propio suministro de madera.",
    ["Precisely! All I would need is a small cabin to work from and I'd be happy to look after this grove for you."] = "¡Precisamente! Todo lo que necesitaría es una pequeña cabaña para trabajar y estaré encantado de cuidar esta arboleda para ti.",
    ["Hmm, before I consider building beyond the fort walls, I'd want to ensure the area is truly safe."] = "Hmm, antes de considerar construir más allá de los muros del fuerte, me gustaría asegurarme de que el área sea verdaderamente segura.",
    ["I'll speak with Bill, about drawing up some plans to fortify the wilderness border to the east."] = "Hablaré con Bill para elaborar algunos planes para fortificar la frontera de wilderness hacia el este.",
    ["Understandable, please let me know if there's anything I can do to help."] = "Es comprensible. Avíseme si hay algo que pueda hacer para ayudar.",
    ["Oh, I didn't even introduce myself! Please call me Oak."] = "¡Oh, ni siquiera me presenté! Por favor llámame roble.",
    ["It was nice to meet you Oak."] = "Fue un placer conocerte, Oak.",
    ["Good day your grace, is there anything I can do to help?"] = "Buenos días, excelencia, ¿hay algo que pueda hacer para ayudar?",
    ["Thanks Oak, but there's nothing you can assist with at the moment. Currently I still need to speak with Bill about planning the fortifications."] = "Gracias Oak, pero no hay nada en lo que puedas ayudar en este momento. Actualmente todavía necesito hablar con Bill sobre la planificación de las fortificaciones.",
    ["Thanks Oak, but there's nothing you can assist with at the moment. I still need to construct the fortifications before we proceed with any other plans."] = "Gracias Oak, pero no hay nada en lo que puedas ayudar en este momento. Todavía necesito construir las fortificaciones antes de continuar con otros planes.",
    ["Understood, your grace, I'll remain here until you inform me otherwise."] = "Entendido, excelencia, permaneceré aquí hasta que me informe lo contrario.",
    ["Greetings, your grace."] = "Saludos, excelencia.",
    ["Hello Oak, I've extended the walls of the fort. The land to the east should be safe for working now."] = "Hola Oak, he ampliado los muros del fuerte. La tierra al este debería ser segura para trabajar ahora.",
    ["That's great news."] = "Esa es una gran noticia.",
    ["You mentioned a cabin earlier, is there anything else I can help provide that you would need?"] = "Mencionaste una cabaña antes, ¿hay algo más que pueda ayudarte a proporcionar y que necesites?",
    ["No, your grace. You're very kind, but as long as I have a roof over my head, I can start tending to the Grove."] = "No, excelencia. Eres muy amable, pero mientras tenga un techo sobre mi cabeza, puedo empezar a cuidar el Grove.",
    ["Great, I'll go speak with Bill about what we can get built."] = "Genial, hablaré con Bill sobre lo que podemos construir.",
    ["At tier 1, you will gain access to normal and oak trees in the grove. Bird's nests found whilst woodcutting will be automatically placed into your backpack and you will gain the ability to store wood spirits in the wood box."] = "En el nivel 1, obtendrá acceso a árboles normales y robles en la arboleda. Los nidos de pájaros que se encuentren mientras corta madera se colocarán automáticamente en su backpack y podrá almacenar alcohol de madera en la caja de madera.",
    ["At tier 2, you will gain access to willow trees, yew trees, choking ivy and a fairy ring in the grove. Access to a new tree farming patch and you will gain the ability to store bird's nests in the wood box."] = "En el nivel 2, obtendrás acceso a sauces, tejos, hiedra asfixiante y un anillo de hadas en la arboleda. Accede a una nueva parcela de cultivo de árboles y obtendrás la posibilidad de almacenar nidos de pájaros en la caja de madera.",
    ["At tier 3, you will gain access to an elder tree in the grove. The ability to obtain bird's nests containing Imcando hatchet pieces. Additionally, newly obtained bird's nest have improved contents."] = "En el nivel 3, obtendrás acceso a un saúco en la arboleda. La capacidad de obtener nidos de pájaros que contienen piezas de hacha Imcando. Además, los nidos de pájaros recién obtenidos tienen contenidos mejorados.",
    ["Greetings, your grace, did you need any more details about the grove from me?"] = "Saludos, excelencia, ¿necesitaba más detalles sobre la arboleda de mi parte?",
    ["Thanks Oak, but I have everything I need. I'll go speak with Bill about those plans."] = "Gracias Oak, pero tengo todo lo que necesito. Iré a hablar con Bill sobre esos planes.",
    ["Hello Oak, Bill has finalised the cabin plans. Once I finish the construction you should be all set."] = "Hola Oak, Bill ha finalizado los planos de la cabaña. Una vez que termine la construcción, deberías estar todo listo.",
    ["Thanks, your grace, I look forward to settling in and seeing what new types of trees will flourish here."] = "Gracias, excelencia, espero instalarme y ver qué nuevos tipos de árboles florecerán aquí.",
    ["Greetings, your grace, I see you've completed the construction of the cabin!"] = "Saludos, excelencia, ¡veo que ha completado la construcción de la cabaña!",
    ["I couldn't have you working out here all day without somewhere comfortable to reside."] = "No podría tenerte trabajando aquí todo el día sin un lugar cómodo donde residir.",
    ["I know it may look somewhat basic for now, but I'm sure we'll have the opportunity to improve it in the future."] = "Sé que puede parecer algo básico por ahora, pero estoy seguro de que tendremos la oportunidad de mejorarlo en el futuro.",
    ["Thanks, your grace, but there's no need to be so humble, this is more than enough."] = "Gracias, excelencia, pero no hay necesidad de ser tan humilde, esto es más que suficiente.",
    ["I'm glad you like it Oak. If you need anything else do let me know."] = "Me alegra que te guste Roble. Si necesitas algo más, házmelo saber.",
    ["**Select an Option**"] = "**Seleccione una opción**",
    ["Grove benefits"] = "Beneficios de arboleda",
    ["At tier 3, you will gain access to the elder tree in the grove. The ability to obtain bird's nests containing Imcando hatchet pieces. Additionally, newly obtained bird's nest have improved contents."] = "En el nivel 3, obtendrás acceso al saúco en la arboleda. La capacidad de obtener nidos de pájaros que contienen piezas de hacha Imcando. Además, los nidos de pájaros recién obtenidos tienen contenidos mejorados.",
    ["Goodbye"] = "Adiós",
    ["Hello Oak, I see the trees have taken to the grove well."] = "Hola Oak, veo que los árboles se han adaptado bien a la arboleda.",
    ["Greetings your grace, they have indeed, with the latest expansion, even the Elder tree has recovered."] = "Saludos, excelencia. De hecho, con la última expansión, incluso el árbol anciano se ha recuperado.",
    ["In fact, with the new trees and plant life growing around the fort, there have been reports that new birds have been sighted migrating in from the north-east."] = "De hecho, con los nuevos árboles y plantas que crecen alrededor del fuerte, ha habido informes de que se han avistado nuevas aves migrando desde el noreste.",
    ["How interesting, have you seen these birds yourself?"] = "Qué interesante, ¿has visto estas aves tú mismo?",
    ["Sadly not, but I found this among their nests. I don't know what it is, but maybe you can make some use of it?"] = "Lamentablemente no, pero encontré esto entre sus nidos. No sé qué es, pero ¿tal vez puedas aprovecharlo?",
    ["Sorry Oak, I don't have the space to take that right now. I'll come back later."] = "Lo siento Oak, no tengo espacio para tomar eso en este momento. Volveré más tarde.",
    ["Congratulations! You have completed: 'A New Discovery' - After upgrading the grove at Fort Forinthry to Tier 3, return to Oak to learn about his new discovery."] = "¡Felicitaciones! Has completado: 'Un nuevo descubrimiento': después de actualizar la arboleda en Fort Forinthry al nivel 3, regresa a Oak para conocer su nuevo descubrimiento.",
    ["Is this a piece of dwarven metal? How was it even able to carry this!"] = "¿Es esto una pieza de metal enano? ¡Cómo pudo siquiera llevar esto!",
    ["It appears to be part of a hatchet, I'll have to see if I can find the rest of this. Thanks again for watching over the grove Oak."] = "Parece ser parte de un hacha, tendré que ver si puedo encontrar el resto de esto. Gracias de nuevo por cuidar la arboleda de robles.",
    ["You can now find Imcando hatchet piece birds nests whilst woodcutting across Gielinor. If you can acquire all four pieces, Thurgo at can reassemble them."] = "Ahora puede encontrar nidos de pájaros con piezas de hacha Imcando mientras corta madera en Gielinor. Si puede adquirir las cuatro piezas, Thurgo en puede volver a ensamblarlas.",
    ["I'm getting out of here Bwana, the place is infested with zombies."] = "Me voy de aquí Bwana, el lugar está infestado de zombies.",
    ["I'm getting out of here, bwana; the place is infested with zombies."] = "Me voy de aquí, bwana; el lugar está infestado de zombies.",
    ["Welcome to Obli's General Store Bwana! Would you like to see my items?"] = "¡Bienvenido a General Store Bwana de Obli! ¿Quieres ver mis artículos?",
    ["Select an Option"] = "Selecciona una opción",
    ["Yes please!"] = "¡Sí, por favor!",
    ["No, but thanks for the offer."] = "No, pero gracias por la oferta.",
    ["Hi assistant."] = "Hola asistente.",
    ["Wait a minute."] = "Espera un minuto.",
    ["What's your real name?"] = "¿Cuál es tu verdadero nombre?",
    ["My real name?"] = "¿Mi verdadero nombre?",
    ["I only know you as the professor's assistant. What's your actual name?"] = "Solo te conozco como asistente del profesor. ¿Cuál es tu nombre real?",
    ["Patrick."] = "Patricio.",
    ["Hi, Patrick, I'm Player."] = "Hola, Patrick, soy Player.",
    ["Well, hello again, and thanks for helping out the professor."] = "Bueno, hola de nuevo y gracias por ayudar al profesor.",
    ["Oh, and, believe it or not, his name is Mambo-duna-roona, but don't tell him I told you."] = "Ah, y, lo creas o no, su nombre es Mambo-duna-roona, pero no le digas que te lo dije.",
    ["You made that up!"] = "¡Eso lo inventaste!",
    ["No, honest! Anyways, you've made my life much easier. Have a drink on me!"] = "¡No, sincero! De todos modos, me has hecho la vida mucho más fácil. ¡Toma una copa por mi cuenta!",
    ["[The assistant gives you some wine.]"] = "[El asistente te da un poco de vino.]",
    ["Thanks very much."] = "Muchas gracias.",
    ["No problem. Scorpius would be proud."] = "No hay problema. Scorpius estaría orgulloso.",
    ["Sorry?"] = "¿Perdón?",
    ["You may want to check out the book on the table, and perhaps look around for a grave..."] = "Quizás quieras echar un vistazo al libro que está sobre la mesa y quizás buscar una tumba a tu alrededor...",
    ["How was the wine?"] = "¿Cómo estuvo el vino?",
    ["That was good stuff, <nowiki>*hic*</nowiki>! Wheresh the professher?"] = "¡Eso fue bueno, <nowiki>*hic*</nowiki>! ¿Dónde está el profesor?",
    ["The professor? He's up in the Observatory. Since the bridge was ruined, you will have to travel through the dungeon under the goblins' settlement."] = "¿El profesor? Está en el Observatorio. Como el puente quedó en ruinas, tendrás que atravesar la mazmorra debajo del asentamiento de los duendes.",
    ["What would you like to talk about?"] = "¿De qué te gustaría hablar?",
    ["Talk about the Observatory Quest."] = "Hable sobre el Observatorio Quest.",
    ["Hello, friend."] = "Hola amigo.",
    ["Welcome back."] = "Bienvenido de nuevo.",
    ["Thanks for all your help with the telescope."] = "Gracias por toda tu ayuda con el telescopio.",
    ["What can I do for you?"] = "¿Qué puedo hacer por ti?",
    ["**SELECT AN OPTION**"] = "**SELECCIONA UNA OPCIÓN**",
    ["Do you need any more help with the telescope?"] = "¿Necesitas más ayuda con el telescopio?",
    ["Not right now,"] = "Ahora no,",
    ["but the stars may hold a secret for you."] = "pero las estrellas pueden tener un secreto para ti.",
    ["*If the player has claimed the jug of wine from Observatory assistant:*"] = "*Si el player ha reclamado la jarra de vino de Observatory assistant:*",
    ["Is it true your name is Mambo-duna-roona?"] = "¿Es cierto que tu nombre es Mambo-duna-roona?",
    ["How do you know tha-"] = "¿Cómo sabes que-",
    ["I mean, of course not, what a silly idea."] = "Quiero decir, por supuesto que no, qué idea más tonta.",
    ["Nothing, thanks."] = "Nada, gracias.",
    ["Okay, no problem. See you again."] = "Está bien, no hay problema. Nos vemos de nuevo.",
    ["Talk about Treasure Trails."] = "Hable sobre los senderos del tesoro.",
    ["*Talking about Treasure Trails for the first time—before obtaining a sextant and a watch*"] = "*Hablando de Treasure Trails por primera vez, antes de obtener un sextante y un reloj*",
    ["Can you teach me to solve Treasure Trails clues?"] = "¿Puedes enseñarme a resolver las pistas de Treasure Trails?",
    ["Ah, I get asked about Treasure Trails all the time! Listen carefully and I shall tell you what I know. Lots of clues have <span style=\"color:red;\">degrees</span> and <span style=\"color:red;\">minutes</span> written on them. These are coordinates of the place where the treasure is buried. You will have to walk to the correct spot, so that your coordinates are exactly the same as the values written on the clue scroll. To do this, you must use a <span style=\"color:red;\">sextant</span>, a <span style=\"color:red;\">watch</span> and a <span style=\"color:red;\">chart</span> to find the coordinates of where you are. Once you know the coordinates of your position, you know which way you have to walk to get to the treasure's coordinates!"] = "¡Ah, todo el tiempo me preguntan sobre Treasure Trails! Escucha atentamente y te diré lo que sé. Muchas pistas tienen escritos <span style=\"color:red;\">grados</span> y <span style=\"color:red;\">minutos</span>. Estas son las coordenadas del lugar donde está enterrado el tesoro. Tendrás que caminar hasta el lugar correcto, de modo que tus coordenadas sean exactamente las mismas que los valores escritos en el rollo de pistas. Para ello deberás utilizar un <span style=\"color:red;\">sextant</span>, un <span style=\"color:red;\">watch</span> y un <span style=\"color:red;\">chart</span> para encontrar las coordenadas de donde te encuentras. Una vez que conozcas las coordenadas de tu posición, sabrás en qué dirección debes caminar para llegar a las coordenadas del tesoro.",
    ["Riiight. So, where do I get these items from?"] = "Correcto. Entonces, ¿de dónde consigo estos artículos?",
    ["I think Murphy, the owner of the Fishing Trawler moored at Port Khazard, might be able to spare you a sextant. After that, the nearest clock tower is south of Ardougne - you could probably get a watch there. I've got plenty of charts myself; just come back here when you've got the sextant and watch, and I'll give you one and teach you how to use them."] = "Creo que Murphy, el propietario del arrastrero Fishing amarrado en Port Khazard, podría ahorrarte un sextante. Después de eso, la torre del reloj más cercana está al sur de Ardougne; probablemente puedas conseguir un reloj allí. Yo mismo tengo muchos gráficos; Vuelve aquí cuando tengas el sextante y mira, te daré uno y te enseñaré cómo usarlo.",
    ["Thanks, I'll see you later."] = "Gracias, nos vemos luego.",
    ["*Talking about Treasure Trails after obtaining a sextant and a watch—before obtaining a chart*"] = "*Hablando de Treasure Trails después de obtener un sextante y un reloj, antes de obtener una carta*",
    ["I've got the sextant and watch!"] = "¡Tengo el sextante y mira!",
    ["Well done! You use the sextant to measure the angle that the sun is currently at. You need the watch so that you know what the time is back here at the Observatory. You then need this chart to work out your position. Your position is recorded in terms of latitude and longitude. Latitude is your position above the equator and longitude is your position relative to here."] = "¡Bien hecho! Usas el sextante para medir el ángulo en el que se encuentra actualmente el sol. Necesitas el reloj para saber qué hora es aquí en el Observatorio. Luego necesitará este gráfico para determinar su posición. Su posición se registra en términos de latitud y longitud. La latitud es su posición sobre el ecuador y la longitud es su posición relativa a aquí.",
    ["The professor has given you a navigation chart."] = "El profesor te ha dado una carta de navegación.",
    ["So, if you have your sextant, watch and chart with you, then you can work out exactly where you are!"] = "Entonces, si tienes tu sextante, observas y trazas contigo, ¡podrás determinar exactamente dónde estás!",
    ["*Talking about Treasure Trails after obtaining a sextant, a watch, and a chart*"] = "*Hablando de Treasure Trails después de obtener un sextante, un reloj y una carta*",
    ["How can I help you today?"] = "¿Cómo puedo ayudarte hoy?",
    ["Can you remind me how to navigate?"] = "¿Puedes recordarme cómo navegar?",
    ["Certainly, it's not difficult."] = "Ciertamente, no es difícil.",
    ["Lots of clues have degrees and minutes written on them. These are the coordinates of where the treasure is buried."] = "Muchas pistas tienen grados y minutos escritos. Estas son las coordenadas de donde está enterrado el tesoro.",
    ["You have to walk to the correct spot so that your coordinates are exactly the same as the values written on the clue scroll."] = "Tienes que caminar hasta el lugar correcto para que tus coordenadas sean exactamente las mismas que los valores escritos en el rollo de pistas.",
    ["To do this, you must use a sextant, a watch and a chart to find the coordinates of where you are."] = "Para ello, deberás utilizar un sextante, un reloj y una carta para encontrar las coordenadas de dónde te encuentras.",
    ["Once you know the coordinates of your position, you know which way you have to walk to get to the treasure's coordinates."] = "Una vez que conozcas las coordenadas de tu posición, sabrás en qué dirección debes caminar para llegar a las coordenadas del tesoro.",
    ["What do you see now?"] = "¿Qué ves ahora?",
    ["I can see a constellation through the telescope. It looks like Scorpio."] = "Puedo ver una constelación a través del telescopio. Parece Escorpio.",
    ["Scorpio? Interesting. How very fitting."] = "¿Escorpio? Interesante. Qué apropiado.",
    ["What do you mean?"] = "¿Qué quieres decir?",
    ["Scorpius, the founder of all we know relating to astronomy. There's a book about him in the reception. Perhaps you should check it out, you might learn something."] = "Escorpio, el fundador de todo lo que sabemos relacionado con la astronomía. Hay un libro sobre él en la recepción. Quizás deberías echarle un vistazo, quizá aprendas algo.",
    ["Then perhaps I shall."] = "Entonces quizás lo haga.",
    ["What?"] = "¿Qué?",
    ["What's the Order of Ascension?"] = "¿Cuál es el Orden de Ascensión?",
    ["Disappointment. Failure. Worshippers of Guthix."] = "Decepción. Falla. Adoradores de Guthix.",
    ["Why should I fight worshippers of Guthix?"] = "¿Por qué debería luchar contra los adoradores de Guthix?",
    ["Guthix refuse worship. Worship is slavery. Worse crime though. Ascended doing terrible thing. Terrible thing in Guthix's name."] = "Guthix rechaza la adoración. La adoración es esclavitud. Aunque el crimen es peor. Ascendió haciendo algo terrible. Algo terrible en nombre de Guthix.",
    ["What are they doing?"] = "¿Qué están haciendo?",
    ["Death of Guthix shock Ascended. Create bad plan. Creating new god. New Guthix to worship. Body of crystal matrix. Spirit from humans. Dead humans. Still unfinished. Stop before they finish."] = "La muerte de Guthix impacta a Ascendido. Crea un mal plan. Creando un nuevo dios. Nuevo Guthix para adorar. Cuerpo de matriz cristalina. Spirit de humanos. Humanos muertos. Aún sin terminar. Detente antes de que terminen.",
    ["Isn't creating a new Guthix a good thing?"] = "¿No es bueno crear un nuevo Guthix?",
    ["Ascended creation mindless monster. Not Guthix at all. Would have much power and no wisdom. Like god. Bring ruin."] = "Monstruo sin sentido de creación ascendida. Para nada Guthix. Tendría mucho poder y ninguna sabiduría. Como dios. Trae ruina.",
    ["*(returns to previous options)*"] = "*(vuelve a opciones anteriores)*",
    ["Where did they come from?"] = "¿De dónde vinieron?",
    ["Founded in this place. Long history. Secret. Mistake. Made to stand against worship. Now stands for worship."] = "Fundada en este lugar. Larga historia. Secreto. Error. Hecho para oponerse a la adoración. Ahora significa adoración.",
    ["How do I fight them?"] = "¿Cómo lucho contra ellos?",
    ["Ascended use powerful magic. Taken from Guthix. Bring bows, crossbows. Pierce magic. Kill Ascended."] = "Los ascendidos usan magia poderosa. Tomado de Guthix. Trae arcos, ballestas. Perforar magia. Matar a los ascendidos.",
    ["You need a ranged weapon and a Slayer level of 81 to fight Ascended."] = "Necesitas un arma a distancia y un nivel Slayer de 81 para luchar contra los Ascendidos.",
    ["Who are you?"] = "¿Quién eres?",
    ["Ocellus. Virius. Guardian."] = "Ocellus. Virio. Guardián.",
    ["Guardian of what?"] = "¿Guardián de qué?",
    ["Why weren't you with us at Cres's chamber?"] = "¿Por qué no estabas con nosotros en la habitación de Cres?",
    ["Important work. Guthix need work. Not need bodyguards."] = "Trabajo importante. Guthix necesita trabajo. No necesito guardaespaldas.",
    ["What does Virius mean?"] = "¿Qué significa Virio?",
    ["My people. Virii. Not from this world."] = "Mi gente. Virii. No de este mundo.",
    ["Why are you here?"] = "¿Por qué estás aquí?",
    ["Ascended need stopping. Mock Guthix. Kill humans wastefully. Create aberration."] = "Los ascendidos necesitan detenerse. Simulacro de Guthix. Matar humanos desperdiciadamente. Crea aberración.",
    ["Can you give me anything to help?"] = "¿Puedes darme algo para ayudar?",
    ["Crossbow? Algarum thread?"] = "¿Ballesta? ¿Hilo de algarum?",
    ["Crossbow."] = "Ballesta.",
    ["Legiones. Ascended leaders. Carry magical signets. Kill Legiones. Take signets. Kill lesser Ascended. Take shards. Many shards. Bring signets and shards. Bring powerful crossbow. Dragonkin-made. Fashion more powerful weapon. Very powerful."] = "Legiones. Líderes ascendidos. Lleva sellos mágicos. Mata legiones. Lleva sellos. Mata a Ascendidos menores. Toma fragmentos. Muchos fragmentos. Traed sellos y fragmentos. Trae una poderosa ballesta. Hecho por Dragonkin. Crea un arma más poderosa. Muy poderoso.",
    ["Bring 1 dragon crossbow, 6 different Ascension signets and 100 Ascension shards to Ocellus and he will create an Ascension crossbow."] = "Lleva 1 ballesta de dragón, 6 sellos de Ascensión diferentes y 100 fragmentos de Ascensión a Ocellus y él creará una ballesta de Ascensión.",
    ["Do I have everything you need?"] = "¿Tengo todo lo que necesitas?",
    ["*If you have the items.*"] = "*Si tienes los artículos.*",
    ["Yes. Create?"] = "Sí. ¿Crear?",
    ["Yes, create an Ascension crossbow using this dragon crossbow."] = "Sí, crea una ballesta de Ascensión usando esta ballesta de dragón.",
    ["Work complete."] = "Trabajo completo.",
    ["I've changed my mind."] = "He cambiado de opinión.",
    ["*If you don't have the items.*"] = "*Si no tienes los artículos.*",
    ["That's all."] = "Eso es todo.",
    ["*(dialogue terminates)*"] = "*(termina el diálogo)*",
    ["Algarum thread."] = "Hilo de algarum.",
    ["Algarum thread. Taken from Ascended. 500,000 coins to you."] = "Hilo de algarum. Tomado de Ascendidos. 500.000 coins para ti.",
    ["What is it?"] = "¿Qué es?",
    ["Found deep in ocean. Woven together. Strong thread. Traders found. Brought to surface. Ascended stole it. Making armour. Took it from them. Stopped them making. Combine with sirenic scale. Make very strong armour. Good to use with bow, crossbow."] = "Encontrado en lo profundo del océano. Tejidos juntos. Hilo fuerte. Los comerciantes encontraron. Llevado a la superficie. Ascendido lo robó. Fabricación de armaduras. Se lo quité. Dejó de hacerlo. Combinar con escala sirénica. Haz una armadura muy fuerte. Bueno para usar con arco, ballesta.",
    ["I'll take it."] = "Yo lo tomaré.",
    ["*Ocellus's Store opens if you have enough gold.*"] = "*La tienda de Ocellus se abre si tienes suficiente oro.*",
    ["*If you do not have enough gold.*"] = "*Si no tienes suficiente oro.*",
    ["Not enough gold."] = "No hay suficiente oro.",
    ["No thanks."] = "No, gracias.",
    ["Okay then."] = "Está bien, entonces.",
    ["Neither."] = "Ninguno de los dos.",
    ["*(Dialogue terminates)*"] = "*(El diálogo termina)*",
    ["Journal. Perhaps wisdom. Not of consequence."] = "Diario. Quizás sabiduría. No de importancia.",
    ["You wrote this book! You created the Order of Ascension!"] = "¡Tú escribiste este libro! ¡Tú creaste la Orden de la Ascensión!",
    ["Yes. Great work."] = "Sí. Gran trabajo.",
    ["Third attempt. Third failure."] = "Tercer intento. Tercer fracaso.",
    ["Minor setback. Learned much. Begin again."] = "Contratiempo menor. Aprendí mucho. Empezar de nuevo.",
    ["Legiones were mistake. Too powerful. Too independent."] = "Legiones se equivocaron. Demasiado poderoso. Demasiado independiente.",
    ["Too powerful to control. Without control, disobedience."] = "Demasiado poderoso para controlarlo. Sin control, desobediencia.",
    ["You're the real monster!"] = "¡Tú eres el verdadero monstruo!",
    ["Begin again. Work needed. More now than ever."] = "Empieza de nuevo. Trabajo necesario. Más ahora que nunca.",
    ["Worship is slavery. Worship is intrinsic. Worship is unavoidable."] = "La adoración es esclavitud. La adoración es intrínseca. La adoración es inevitable.",
    ["Need focus for worship. Guided. Intentional. Not Guthix. Disrespectful."] = "Necesito concentración para la adoración. Guiado. Intencional. Guthix no. Irrespetuoso.",
    ["Me. Worship me."] = "Yo. Adórame.",
    ["Your work is misguided."] = "Tu trabajo está equivocado.",
    ["I don't care about any of this."] = "No me importa nada de esto.",
    ["Ascended leaders - Legiones - protected by sealed doors. Keystones allow access. Specific stone. Specific door. Specific Legio."] = "Líderes ascendidos - Legiones - protegidos por puertas selladas. Las piedras angulares permiten el acceso. Piedra específica. Puerta específica. Legio específico.",
    ["Shards of Ascended power. Broken. Some power. Could carve into powerful ammunition. Would require equally powerful weapon to fire."] = "Fragmentos de poder ascendido. Roto. Algo de poder. Podría tallar municiones poderosas. Se necesitaría un arma igualmente poderosa para disparar.",
    ["Powerful talisman. Bring all six. Create powerful weapon."] = "Poderoso talismán. Trae los seis. Crea un arma poderosa.",
    ["**Note: This includes the Ascension crossbows.**"] = "**Nota: Esto incluye las ballestas de Ascensión.**",
    ["Not of interest."] = "No es de interés.",
    ["*Ocga says one of these randomly, and then the dialogue terminates*"] = "*Ocga dice uno de estos al azar, y luego el diálogo termina*",
    ["Hello there!"] = "¡Hola!",
    ["Good day!"] = "¡Buenos días!",
    ["Lovely day, isn't it?"] = "Precioso día, ¿no?",
    ["Oh, hello."] = "Oh, hola.",
    ["Good to see you!"] = "¡Qué bueno verte!",
    ["Can't talk to you, too busy!"] = "¡No puedo hablar contigo, estoy demasiado ocupado!",
    ["Clear out!"] = "¡Fuera!",
    ["Talk to the secretaries, not to me!"] = "¡Habla con las secretarias, no conmigo!",
    ["Stay out of the octagon center!"] = "¡Manténgase alejado del centro del octágono!",
    ["I can't help you!"] = "¡No puedo ayudarte!",
    ["Skreeeee! An adventurer! Perfect! You must assist me!"] = "¡Screeeee! ¡Un aventurero! ¡Perfecto! ¡Debes ayudarme!",
    ["What do you need?"] = "¿Qué necesitas?",
    ["I study all things with feathers. I've travelled the world to make a compendium of all bird life!"] = "Estudio todas las cosas con plumas. ¡He viajado por todo el mundo para hacer un compendio de todas las aves!",
    ["There's just one small problem..."] = "Sólo hay un pequeño problema...",
    ["What's wrong?"] = "¿Qué pasa?",
    ["Skreeeee! Pirates! Pirates are what's wrong! I often stow away on boats to get around, but one day I lost all my notes on the Arc region in an...unwanted visit."] = "¡Screeeee! ¡Piratas! ¡Los piratas son lo que pasa! A menudo viajo como polizón en barcos para desplazarme, pero un día perdí todas mis notas sobre la región de Arc en una... visita no deseada.",
    ["Sorry to hear that. How can I help?"] = "Lamento escuchar eso. ¿Cómo puedo ayudar?",
    ["Skreeeee! I only need you to observe any tropical birds you see and take some notes! Nothing too taxing!"] = "¡Screeeee! ¡Solo necesito que observes las aves tropicales que veas y tomes algunas notas! ¡Nada demasiado exigente!",
    ["That seems easy enough! Sure. Count me in."] = "¡Eso parece bastante fácil! Seguro. Cuenta conmigo.",
    ["Maybe you should take a look at this..."] = "Quizás deberías echarle un vistazo a esto...",
    ["You show him your journal."] = "Le muestras tu diario.",
    ["Skreeeee! BRILLIANT! That's a great start!"] = "¡Screeeee! ¡BRILLANTE! ¡Ese es un gran comienzo!",
    ["Count me in, though. I'll continue to look for more."] = "Pero cuenta conmigo. Seguiré buscando más.",
    ["Skreeeee! THIS IS THE BEST DAY EVER! Another adventurer on my list of lackeys!"] = "¡Screeeee! ¡ESTE ES EL MEJOR DÍA DE TODOS! ¡Otro aventurero en mi lista de lacayos!",
    ["I mean, thank you for your help! Skreeeee..."] = "Quiero decir, ¡gracias por tu ayuda! Skreeeee...",
    ["Skreeeee! Have you found any birds yet?"] = "¡Screeeee! ¿Ya has encontrado algún pájaro?",
    ["None so far! I'll keep looking, I promise."] = "¡Ninguno hasta ahora! Seguiré buscando, lo prometo.",
    ["Skreeeee! Have you found any more birds yet?"] = "¡Screeeee! ¿Ya has encontrado más pájaros?",
    ["A few. I'll keep looking, I promise."] = "Algunos. Seguiré buscando, lo prometo.",
    ["Skreeeee! Good job! Some only appear in particular areas on certain days!"] = "¡Screeeee! ¡Buen trabajo! ¡Algunos solo aparecen en áreas particulares en ciertos días!",
    ["Thanks for the advice!"] = "¡Gracias por el consejo!",
    ["Yes, lots. Here, take a look!"] = "Sí, mucho. ¡Aquí, echa un vistazo!",
    ["Skreeeee! Excellent! That's almost all of the ones I've ever seen!"] = "¡Screeeee! ¡Excelente! ¡Esos son casi todos los que he visto!",
    ["Some birds only appear in particular areas on certain days, some appear while gathering resources, and some are only found way out in the uncharted isles."] = "Algunas aves solo aparecen en áreas particulares en ciertos días, algunas aparecen mientras recolectan recursos y otras solo se encuentran en islas inexploradas.",
    ["Yes, sixteen! Here, take a look!"] = "¡Sí, dieciséis! ¡Aquí, echa un vistazo!",
    ["Skreeeeeeeeeeeeeeeeeeeeeeeeeeeeeeeeeeeeee!"] = "¡Skreeeeeeeeeeeeeeeeeeeeeeeeeeeeeeeeeeeee!",
    ["... Are you okay?"] = "... ¿Estás bien?",
    ["You've done it! These are all the birds I ever found in the Arc! Thank you, thank you, thank you! Skreeee!"] = "¡Lo has logrado! ¡Estas son todas las aves que encontré en el Arco! ¡Gracias, gracias, gracias! ¡Screeee!",
    ["No problem!"] = "¡No hay problema!",
    ["Please take this beautiful specimen as a reward!"] = "¡Llévate este hermoso ejemplar como recompensa!",
    ["You have unlocked Iago, a colourful tropical bird, as a pet."] = "Has desbloqueado a Iago, un colorido pájaro tropical, como mascota.",
    ["You have unlocked a new pet!"] = "¡Has desbloqueado una nueva mascota!",
    ["Skreee!"] = "¡Screee!",
    ["Hey again..."] = "Hola de nuevo...",
    ["Thanks again, adventurer. I'm still compiling all of your lovely notes and drawings. Skreeeee!"] = "Gracias de nuevo, aventurero. Todavía estoy recopilando todas tus hermosas notas y dibujos. ¡Screeeee!",
    ["Can I help you with something?"] = "¿Puedo ayudarte en algo?",
    ["Well, err...who are you, and what are all these bones doing here?"] = "Bueno, err... ¿quién eres y qué están haciendo todos estos huesos aquí?",
    ["I'm an archaeologist and I work with the museum."] = "Soy arqueólogo y trabajo en el museo.",
    ["An archaeologist?"] = "¿Un arqueólogo?",
    ["Yes."] = "Sí.",
    ["Well, that explains the bones - sort of - but what are you doing all the way out here?"] = "Bueno, eso explica los huesos, más o menos, pero ¿qué estás haciendo hasta aquí?",
    ["Mumblemumble. Mumblemumblemumble."] = "Mumblemumble. Murmullo murmullo murmullo.",
    ["I'm collecting bones for the museum."] = "Estoy coleccionando huesos para el museo.",
    ["They've asked me to rig up some displays of Second and Third Age creatures, using their bones, so that people can come and, well, look at them."] = "Me pidieron que montara algunas exhibiciones de criaturas de la Segunda y Tercera Edad, usando sus huesos, para que la gente pueda venir y, bueno, mirarlas.",
    ["I need to get them into some sort of order before I begin, but I've run into a bit of a snag."] = "Necesito ponerlos en algún tipo de orden antes de comenzar, pero me he encontrado con un pequeño problema.",
    ["What sort of a snag?"] = "¿Qué tipo de problema?",
    ["Well, I need to have all the bones I'm going to use here first, then I've got to put them in some sort of order."] = "Bueno, primero necesito tener todos los huesos que voy a usar aquí, luego tengo que ponerlos en algún tipo de orden.",
    ["I seem to be a few bones short of a skeleton, though."] = "Aunque parece que me faltan unos huesos para llegar a ser un esqueleto.",
    ["Choose an option"] = "Elige una opción:",
    ["Anything I can do to help?"] = "¿Puedo hacer algo para ayudar?",
    ["There is something you could do for me. I'm going to be busy, er..."] = "Hay algo que podrías hacer por mí. Voy a estar ocupado, eh...",
    ["Mumble."] = "Murmura.",
    ["Sorting! Yes, sorting these bones out ready for the museum. I still need a few more, though."] = "¡Clasificando! Sí, clasificando estos huesos para prepararlos para el museo. Aunque todavía necesito algunos más.",
    ["Will you help me out?"] = "¿Me ayudarás?",
    ["*If quest is declined:*"] = "*Si se rechaza la misión:*",
    ["*(continues below.)*"] = "*(continúa a continuación.)*",
    ["*If quest is accepted:*"] = "*Si se acepta la misión:*",
    ["Well, good luck with that."] = "Bueno, buena suerte con eso.",
    ["Where is that mumbling coming from?"] = "¿De dónde viene ese murmullo?",
    ["I was just passing and wondered if you still needed someone to help with the bones."] = "Estaba de paso y me preguntaba si todavía necesitabas a alguien que te ayudara con los huesos.",
    ["Sorting! Yes, busy sorting these bones out ready for the museum. I still need a few more, though."] = "¡Clasificando! Sí, ocupado clasificando estos huesos para prepararlos para el museo. Aunque todavía necesito algunos más.",
    ["Oh, I see."] = "Oh, ya veo.",
    ["Well, never mind me, young man, I'll just stagger over here under my massive burden, and continue my thankless task."] = "Bueno, no me hagas caso, jovencito, simplemente me acercaré tambaleándome bajo mi enorme carga y continuaré con mi ingrata tarea.",
    ["Unaided and alone..."] = "Sin ayuda y solo...",
    ["Wow, trying a guilt trip much?"] = "Vaya, ¿intentas mucho el sentimiento de culpa?",
    ["Yes. I'll give you a hand."] = "Sí. Te daré una mano.",
    ["You will? Excellent!"] = "¿Lo harás? ¡Excelente!",
    ["Sniggersnigger."] = "Risitasnigger.",
    ["Where do you need me to dig?"] = "¿Dónde necesitas que excave?",
    ["Dig?"] = "¿Excavar?",
    ["Oh, you must have got the wrong end of the stick."] = "Oh, debes haber entendido el extremo equivocado del palo.",
    ["I need some fresh, whole bones to replace ones that have become damaged."] = "Necesito algunos huesos enteros y frescos para reemplazar los que se han dañado.",
    ["Mumblemumblemumblemumblemumble. Mumblemumblemumblemumble. Mumble."] = "Mumblemumblemumblemumblemumble. Murmullo murmullo murmullo. Mascullar.",
    ["Shh!"] = "¡Shh!",
    ["Sorry..."] = "Lo siento...",
    ["Okay, got it."] = "Está bien, lo tengo.",
    ["Here's the thing: while sorting out what bones I do have I managed to lose or damage a few. If you can get me some fresh, unbroken bones to use as replacements, then I can get on with things."] = "Esta es la cuestión: mientras ordenaba los huesos que tengo, logré perder o dañar algunos. Si puedes conseguirme algunos huesos frescos e intactos para usarlos como reemplazo, entonces podré seguir con las cosas.",
    ["Does that make things clearer?"] = "¿Eso aclara las cosas?",
    ["Well, it makes some sense I suppose..."] = "Bueno, supongo que tiene algún sentido...",
    ["Great. If you can get me a bone from a goblin, a bear, a big frog, a ram, a unicorn, a monkey, a giant rat and a giant bat, then I'll be able to move on with the, er..."] = "Genial. Si puedes conseguirme un hueso de un duende, un oso, una rana grande, un carnero, un unicornio, un mono, una rata gigante y un murciélago gigante, entonces podré seguir adelante con...",
    ["...displays."] = "...muestra.",
    ["So you just want me to bring you these bones and that will be that?"] = "¿Entonces solo quieres que te traiga estos huesos y eso será todo?",
    ["Well, I wouldn't mind you boiling them in vinegar first. If you don't mind."] = "Bueno, no me importaría que los hirvieras primero en vinagre. Si no te importa.",
    ["There is a wine merchant in Draynor called Fortunato who sells the stuff you'll need."] = "Hay un comerciante de vinos en Draynor llamado Fortunato que vende todo lo que necesitas.",
    ["You can even use my pot boiler if you want."] = "Incluso puedes usar mi olla si quieres.",
    ["Why do I need to boil them in vinegar?"] = "¿Por qué necesito hervirlos en vinagre?",
    ["It gets them bright and sparkling white..."] = "Les da un color blanco brillante y chispeante...",
    ["It's an archaeologist thing."] = "Es una cosa de arqueólogos.",
    ["Just put the bone in a pot of vinegar, throw some logs on the fire, put the pot on the boiler, then light the logs."] = "Simplemente pon el hueso en una olla con vinagre, echa un poco de logs al fuego, pon la olla en la caldera y luego enciende el logs.",
    ["It takes a short while for the vinegar to evaporate, but the bone will be nice and clean in the end."] = "El vinagre tarda un poco en evaporarse, pero al final el hueso quedará bonito y limpio.",
    ["Alright, I'll be back later."] = "Muy bien, volveré más tarde.",
    ["Bye!"] = "¡Adiós!",
    ["Have you brought me any bones?"] = "¿Me has traído algún hueso?",
    ["Not at the moment. Can you give me a rundown on which bones I have left to get?"] = "No por el momento. ¿Puedes darme un resumen de qué huesos me quedan por conseguir?",
    ["Sure."] = "Claro.",
    ["You still need to bring me a goblin bone."] = "Aún necesitas traerme un hueso de duende.",
    ["Goblins are relatively common. In fact, I hear there is a house full of them in Lumbridge."] = "Los duendes son relativamente comunes. De hecho, he oído que hay una casa llena de ellos en Lumbridge.",
    ["You still need to bring me a bear bone."] = "Aún necesitas traerme un hueso de oso.",
    ["I heard that there are some bears over by the Legends' Guild, near Ardougne."] = "Escuché que hay algunos osos junto a Legends' Guild, cerca de Ardougne.",
    ["You still need to bring me a big frog bone."] = "Aún necesitas traerme un hueso de rana grande.",
    ["This one might be a little tricky. You'll need to go into the Lumbridge Swamp Dungeon. Don't forget to take a light source! Never forget your light source down there."] = "Esto podría ser un poco complicado. Tendrás que entrar en Lumbridge Swamp Dungeon. ¡No olvides llevar una fuente de luz! Nunca olvides tu fuente de luz ahí abajo.",
    ["You still need to bring me a ram bone."] = "Aún necesitas traerme un hueso de carnero.",
    ["I'm sure you will be able to find a ram wherever there are sheep."] = "Estoy seguro de que podrás encontrar un carnero dondequiera que haya ovejas.",
    ["You still need to bring me a unicorn bone."] = "Aún necesitas traerme un hueso de unicornio.",
    ["I seem to remember seeing some unicorns south of Varrock. I think they might still be there."] = "Creo recordar haber visto algunos unicornios al sur de Varrock. Creo que es posible que todavía estén allí.",
    ["You still need to bring me a monkey bone."] = "Aún necesitas traerme un hueso de mono.",
    ["Monkeys tend to live in jungles, like those on Karamja. I think they are pretty plentiful there, if I remember correctly."] = "Los monos tienden a vivir en selvas, como las de Karamja. Creo que hay bastantes allí, si mal no recuerdo.",
    ["You still need to bring me a giant rat bone."] = "Aún necesitas traerme un hueso de rata gigante.",
    ["If you can't find one in a sewer, then you might want to try looking in some caves."] = "Si no puedes encontrar uno en una alcantarilla, quizás quieras intentar buscar en algunas cuevas.",
    ["You still need to bring me a giant bat bone."] = "Aún necesitas traerme un hueso de murciélago gigante.",
    ["Giant bats tend to live underground, but I have heard there are a few near the coal trucks in Kandarin."] = "Los murciélagos gigantes tienden a vivir bajo tierra, pero he oído que hay algunos cerca de los camiones de carbón en Kandarin.",
    ["Did you get all that?"] = "¿Entendiste todo eso?",
    ["Yes. I'll get right on it."] = "Sí. Me pondré manos a la obra.",
    ["Don't forget to boil them in vinegar first."] = "No olvides hervirlos primero en vinagre.",
    ["Just chuck some logs into the pit, put the bone in the pot of vinegar and drop it onto the pot boiler. Then light the logs and wait for the the vinegar to boil away."] = "Simplemente echa un poco de logs en el hoyo, pon el hueso en la olla de vinagre y déjalo caer en la olla. Luego enciende el logs y espera a que el vinagre se evapore.",
    ["Okay, I'll remember."] = "Está bien, lo recordaré.",
    ["Ask About the Odd Old Man."] = "Pregunte por el Odd Old Man.",
    ["Ask about the crumpled note"] = "Pregunta por la nota arrugada",
    ["What can I do you for?"] = "¿En qué puedo ayudarte?",
    ["The darkness is coming."] = "La oscuridad está llegando.",
    ["Oh? Why is that?"] = "¿Ah? ¿Porqué es eso?",
    ["Because the stars start to dim."] = "Porque las estrellas empiezan a apagarse.",
    ["Ah, so you gave him his coin then. Not sure I would have done the same. Still, I made a promise and, strange as that promise is, I keep my promises."] = "Ah, entonces le diste su moneda. No estoy seguro de que yo hubiera hecho lo mismo. Aún así, hice una promesa y, por extraña que sea esa promesa, la cumplo.",
    ["The Odd Old Man hands you a disgusting looking book."] = "El Odd Old Man te entrega un libro con un aspecto repugnante.",
    ["Because Sliske is up to something?"] = "¿Porque Sliske está tramando algo?",
    ["No. Wait. What?"] = "No. Espera. ¿Qué?",
    ["Err...never mind."] = "Err... no importa.",
    ["*(Returns to the initial options.)*"] = "*(Vuelve a las opciones iniciales.)*",
    ["Because Azzanadra is disappointed?"] = "¿Porque Azzanadra está decepcionado?",
    ["Because the sun is dying."] = "Porque el sol se está muriendo.",
    ["Because of Xau-Tak."] = "Por Xau-Tak.",
    ["The darkness is here."] = "La oscuridad está aquí.",
    ["Huh?"] = "¿Eh?",
    ["The shadows descend."] = "Las sombras descienden.",
    ["I can't remember what I'm meant to say."] = "No recuerdo lo que se supone que debo decir.",
    ["All hail the Ravensworn!"] = "¡Todos saluden a los Cuervos!",
    ["Oh no, not one of you lunatics."] = "Oh, no, ninguno de ustedes, locos.",
    ["Look, I'll tell you what I told the others."] = "Mira, te diré lo que les dije a los demás.",
    ["GET OFF MY LAND, YOU NUTJOBS!"] = "¡SALGAN DE MI TIERRA, LOCOS!",
    ["Honestly, you spot a bunch of corvids and suddenly think you're in some sort of special club."] = "Honestamente, ves un grupo de córvidos y de repente piensas que estás en una especie de club especial.",
    ["Ask about the Odd Old Man."] = "Pregunte por el Odd Old Man.",
    ["Ask about your missing book"] = "Pregunta por tu libro perdido",
    ["Aye, I found your book. Here, keep it."] = "Sí, encontré tu libro. Toma, guárdalo.",
    ["[The Odd Old Man has given you a puzzle box!]"] = "[¡El Odd Old Man te ha regalado una caja de rompecabezas!]",
    ["[The Odd Old Man has given you another clue scroll!]"] = "[¡El Odd Old Man te ha dado otro pergamino de pistas!]",
    ["[You've found a casket!]"] = "[¡Has encontrado un ataúd!]",
    ["You've got all sorts of junk here."] = "Aquí tienes todo tipo de basura.",
    ["Junk... to you. Treasure... to others."] = "Basura... para ti. Tesoro... para los demás.",
    ["Where'd you even find this stuff?"] = "¿Dónde encontraste estas cosas?",
    ["Road... ruin... pocket."] = "Camino... ruina... bolsillo.",
    ["All things... want owner."] = "Todas las cosas... quieren dueño.",
    ["Even this cracked pot?"] = "¿Incluso esta olla rota?",
    ["Pot crack... still hold seed."] = "La olla está rota... todavía contiene semillas.",
    ["Wiser words have never been spoken."] = "Nunca se han dicho palabras más sabias.",
    ["What to buy? What to buy? Oh, hello human."] = "¿Qué comprar? ¿Qué comprar? Hola humano.",
    ["Anything I can help you with?"] = "¿Puedo ayudarte en algo?",
    ["Only if you can help me make a suggestion on what to buy."] = "Sólo si puedes ayudarme a hacer una sugerencia sobre qué comprar.",
    ["I smell a quest!"] = "¡Huelo una misión!",
    ["No, not really. I just need some advice on what to buy, that's all."] = "No, realmente no. Sólo necesito algunos consejos sobre qué comprar, eso es todo.",
    ["Select an option"] = "Seleccione una opción",
    ["New clothes."] = "Ropa nueva.",
    ["You should buy some new clothes. You can't go around town wearing what you're wearing."] = "Deberías comprarte ropa nueva. No puedes andar por la ciudad usando lo que llevas puesto.",
    ["You're right, this is a little drab. I shouldn't really go around Keldagrim-West wearing this, should I?"] = "Tienes razón, esto es un poco monótono. Realmente no debería andar por Keldagrim-West usando esto, ¿verdad?",
    ["Of course I still don't know what colour I should get. I don't want to accidentally offend the wrong company of course."] = "Por supuesto, todavía no sé qué color debería elegir. Por supuesto, no quiero ofender accidentalmente a la empresa equivocada.",
    ["Never mind."] = "No importa.",
    ["A warhammer."] = "Un martillo de guerra.",
    ["You should get yourself a big mighty warhammer."] = "Deberías conseguir un martillo de guerra grande y poderoso.",
    ["I don't think so. The warhammer shop is run by the Red Axe. I'd rather stay out of there."] = "No lo creo. La tienda de Warhammer está dirigida por Red Axe. Prefiero quedarme fuera de ahí.",
    ["You don't like the Red Axe?"] = "¿No te gusta el Hacha Roja?",
    ["They're all a lot of bullies if you ask me."] = "Si me preguntas, todos son unos matones.",
    ["But I thought they left the city?"] = "¿Pero pensé que se habían ido de la ciudad?",
    ["They may have, but I still think that shopkeeper is in league with them, banners or no."] = "Puede que sí, pero sigo pensando que el comerciante está aliado con ellos, con pancartas o sin ellas.",
    ["I don't think so. The warhammer shop used to be run by the Red Axe. I'd rather stay out of there."] = "No lo creo. La tienda de Warhammer solía estar dirigida por Red Axe. Prefiero quedarme fuera de ahí.",
    ["A piece of rope."] = "Un trozo de cuerda.",
    ["Get yourself a long piece of rope."] = "Consíguete un trozo largo de cuerda.",
    ["What would I do with a rope?"] = "¿Qué haría con una cuerda?",
    ["I don't know. I generally find a rope useful while adventuring."] = "No lo sé. Generalmente encuentro útil una cuerda cuando estoy de aventuras.",
    ["I don't do a lot of adventuring to be honest."] = "Para ser honesto, no me aventuro mucho.",
    ["An oversized hat."] = "Un sombrero de gran tamaño.",
    ["An oversized hat. In a ridiculous colour."] = "Un sombrero de gran tamaño. En un color ridículo.",
    ["No one is selling hats here, that's not a very helpful suggestion at all."] = "Nadie vende sombreros aquí, esa no es una sugerencia muy útil en absoluto.",
    ["Nothing."] = "Nada.",
    ["Nothing. You should buy absolutely nothing."] = "Nada. No deberías comprar absolutamente nada.",
    ["Now that's the best idea I've heard all day."] = "Esa es la mejor idea que he escuchado en todo el día.",
    ["I thought so! Now why don't you give me some of the money I saved you?"] = "¡Eso pensé! ¿Por qué no me das algo del dinero que te ahorré?",
    ["No, I don't think so. I think I'd rather buy something with my money after all."] = "No, no lo creo. Después de todo, creo que prefiero comprar algo con mi dinero.",
    ["*If the player is on the tile directly north, east, south, or west of Odovacar:*"] = "*Si el player está en el mosaico directamente al norte, este, sur u oeste de Odovacar:*",
    ["Well met, fellow adventurer! How can I help you?"] = "¡Bien conocido, compañero aventurero! ¿Le puedo ayudar en algo?",
    ["*If the player is not on the tile directly north, east, south, or west of Odovacar:*"] = "*Si el player no está en el mosaico directamente al norte, este, sur u oeste de Odovacar:*",
    ["Good day. How may I help you?"] = "Buenos días. ¿Cómo puedo ayudarte?",
    ["*If the player has items they can collect from the Grand Exchange:*"] = "*Si el player tiene artículos que puede recolectar de Grand Exchange:*",
    ["Before we go any further, I should inform you that you have items ready for collection from the Grand Exchange."] = "Antes de continuar, debo informarle que tiene artículos listos para ser recogidos en Grand Exchange.",
    ["**What would you like to say?**"] = "**¿Qué te gustaría decir?**",
    ["How frightfully rude of me, my dear [chap/lady]. My name is Odovacar and I work for that excellent enterprise, the Bank of Gielinor."] = "Qué terriblemente grosero de mi parte, mi querido [chap/lady]. Mi nombre es Odovacar y trabajo para esa excelente empresa, el Banco de Gielinor.",
    ["If you work for the bank, what are you doing here?"] = "Si trabajas en el banco, ¿qué haces aquí?",
    ["As part of our ongoing service to provide you, the customer, with an absolutely world-class banking experience, we are investigating the option of opening a chain of travelling banks. These will provide you, our esteemed customer, with the convenience of having banking facilities where they will be of optimum use to you. Such as here!"] = "Como parte de nuestro servicio continuo para brindarle a usted, el cliente, una experiencia bancaria absolutamente de clase mundial, estamos investigando la opción de abrir una cadena de bancos ambulantes. Estos le brindarán a usted, nuestro estimado cliente, la conveniencia de contar con instalaciones bancarias que le serán de máxima utilidad. ¡Como aquí!",
    ["I am the first of a new generation of travelling bankers that will wander the perilous areas of the world to provide you, the valued customer, with a bank when you need it most!"] = "Soy el primero de una nueva generación de banqueros viajeros que recorrerán las zonas peligrosas del mundo para brindarle a usted, el valioso cliente, un banco cuando más lo necesita.",
    ["So I can access my bank account simply by talking to you?"] = "¿Entonces puedo acceder a mi cuenta bancaria simplemente hablando contigo?",
    ["Absolutely correct, dear [sir/lady]. I must warn you, however, that due to the significantly increased overheads of an enterprise such as this, there is a small bank charge of 100gp every time you want to access your account."] = "Absolutamente correcto, querido [sir/lady]. Debo advertirle, sin embargo, que debido a los gastos generales significativamente mayores de una empresa como esta, hay un pequeño cargo bancario de 100 po cada vez que desea acceder a su cuenta.",
    ["Sounds fair; here's the money. Can I access my account now?"] = "Suena justo; Aquí está el dinero. ¿Puedo acceder a mi cuenta ahora?",
    ["Let me open my account and then I'll pay you."] = "Déjame abrir mi cuenta y luego te pagaré.",
    ["It's not that I don't trust you, old [chap/girl], but as the old adage goes, 'money comes before friends'."] = "No es que no confíe en ti, viejo [chap/girl], pero como dice el viejo refrán, \"el dinero está antes que los amigos\".",
    ["That's preposterous! I'm not paying to withdraw my own money!"] = "¡Eso es absurdo! ¡No estoy pagando para retirar mi propio dinero!",
    ["I'm sorry to hear that, [sir/madam]. If you should reconsider, because I believe this service offers excellent value for money, do not hesitate to contact me."] = "Lamento oír eso, [sir/madam]. Si debes reconsiderarlo, porque creo que este servicio ofrece una excelente relación calidad-precio, no dudes en contactarme.",
    ["I'd like to access my bank account, please."] = "Me gustaría acceder a mi cuenta bancaria, por favor.",
    ["I'd like to check my PIN settings."] = "Me gustaría verificar la configuración de mi PIN.",
    ["*If the player has at least 100 coins:*"] = "*Si el player tiene al menos 100 coins:*",
    ["*If the player does not have at least 100 coins:*"] = "*Si el player no tiene al menos 100 coins:*",
    ["I'm afraid you don't have the necessary funds with you at this time so I can't allow you to access your account. Please come again, when you have 100 gold to cover the fee."] = "Me temo que no tienes los fondos necesarios contigo en este momento, por lo que no puedo permitirte acceder a tu cuenta. Por favor, vuelve cuando tengas 100 de oro para cubrir la tarifa.",
    ["I'd like to see my collection box."] = "Me gustaría ver mi caja de colección.",
    ["What is this place?"] = "¿Qué es este lugar?",
    ["This is a branch of the Bank of Gielinor. We have branches in many towns."] = "Esta es una sucursal del Banco de Gielinor. Disponemos de sucursales en muchas localidades.",
    ["And what do you do?"] = "¿Y tú qué haces?",
    ["We will look after your items and money for you. Leave your valuables with us if you want to keep them safe."] = "Nos ocuparemos de tus artículos y de tu dinero. Deje sus objetos de valor con nosotros si desea mantenerlos seguros.",
    ["Didn't you used to be called the Bank of Varrock?"] = "¿No te llamaban antes el Banco de Varrock?",
    ["Yes we did, but people kept on coming into our branches outside of Varrock and telling us that our signs were wrong. They acted as if we didn't know what town we were in or something."] = "Sí, lo hicimos, pero la gente seguía entrando a nuestras sucursales fuera de Varrock y diciéndonos que nuestros carteles estaban equivocados. Actuaron como si no supiéramos en qué ciudad estábamos o algo así.",
    ["Meow, meow meow."] = "Miau, miau, miau.",
    ["Oh, hello. Are you here to visit my mother? I'm afraid she's not in right now."] = "Oh, hola. ¿Estás aquí para visitar a mi madre? Me temo que ella no está ahora.",
    ["Dad says you can get a lift to Karamja with us if you want? But you's gives us two chompy first!"] = "Dad dice que puedes llevarte a Karamja con nosotros si quieres. ¡Pero primero nos das dos mordiscos!",
    ["Yes please, I'll get a lift to Karamja with you."] = "Sí, por favor, te llevaré a Karamja.",
    ["You's got no chompies...no boatsie trips!"] = "No tienes mordiscos... ¡ni viajes en barco!",
    ["The barely sea-worthy log arrives at Karamja beach."] = "El tronco apenas apto para navegar llega a la playa de Karamja.",
    ["Dad says you can get a lift back with us if you want? But you's gives us two glug-glugs herbies first!"] = "Dad dice que puedes regresar con nosotros si quieres. ¡Pero primero nos das dos herbies glug-glugs!",
    ["Yes please, I'll get a lift back with you."] = "Sí, por favor, me llevarán de regreso.",
    ["Dad sez yous not bringin' da rummy stuff...das bad stuffsies un we get in big bads."] = "Dad dice que no traerás cosas divertidas... cosas malas hasta que nos metemos en grandes males.",
    ["You's got no glug-glugs herbies...no boatsie trips!"] = "No tienes herbies glug-glugs... ¡ni viajes en barco!",
    ["You hand over two herbs and accept a ride from Fycie and Bugs on the makeshift boat."] = "Entregas dos hierbas y aceptas que Fycie y Bugs te lleven en el barco improvisado.",
    ["The barely sea-worthy log arrives at the Feldip Hills."] = "El tronco apenas apto para navegar llega a Feldip Hills.",
    ["cond=If previously not selected the option:"] = "cond=Si no se seleccionó previamente la opción:",
    ["Glug-glugs herbies! You know! Da thiefy-bag herbie or da snakey-weeed herbie!"] = "¡Glug-glugs herbies! ¡Sabes! ¡El herbie ladrón o el herbie serpiente!",
    ["Wait, you mean rogue's purse or snake weed?"] = "Espera, ¿te refieres al bolso del pícaro o a la hierba de serpiente?",
    ["Yeah! Dem! Now dad says you can get a lift back with use if you want. But you's gives us two dem herbies first!"] = "¡Sí! ¡Demín! Ahora papá dice que puedes regresar con el uso si quieres. ¡Pero primero nos das dos herbies!",
    ["cond=If previously selected the above option:"] = "cond=Si previamente seleccionó la opción anterior:",
    ["Stop, creature! Only ogres and their friends allowed in this city. Show me a sign of companionship, like a lost relic or somefing, and you may pass. Until then, back to whence you came!"] = "¡Detente, criatura! Sólo se permiten ogros y sus amigos en esta ciudad. Muéstrame una señal de compañerismo, como una reliquia perdida o algo así, y podrás pasar. Hasta entonces, ¡vuelve al lugar de donde viniste!",
    ["The guard pushes you back down the hill.}}{{anchor"] = "El guardia te empuja colina abajo.}}{{anchor",
    ["*If the player walks somewhere:*"] = "*Si el player camina hacia algún lugar:*",
    ["Well, what proof of friendship did you bring?"] = "Bueno, ¿qué prueba de amistad trajiste?",
    ["I don't have anything."] = "No tengo nada.",
    ["Why have you returned with no proof of companionship? Back to whence you came!"] = "¿Por qué has regresado sin prueba de compañía? ¡De vuelta a donde viniste!",
    ["**Ogre guard:** Halt! You cannot pass here."] = "**Ogre guard:** ¡Alto! No puedes pasar por aquí.",
    ["I am a friend to ogres."] = "Soy amigo de los ogros.",
    ["You will be my friend only with gold. Bring me a bar of pure gold and I will let you pass. For now - begone!"] = "Serás mi amigo sólo con oro. Tráeme una barra de oro puro y te dejaré pasar. Por ahora, ¡vete!",
    ["Creature, did you bring me the gold?"] = "Criatura, ¿me trajiste el oro?",
    ["*If the player has a gold bar:*"] = "*Si el player tiene una barra de oro:*",
    ["Here it is!"] = "¡Aquí está!",
    ["It's brought it! On your way."] = "¡Lo trajo! En camino.",
    ["*If the player doesn't have a gold bar:*"] = "*Si el player no tiene una barra de oro:*",
    ["No, I don't have it."] = "No, no lo tengo.",
    ["No gold, no passage. Get out of this city!"] = "Sin oro, no hay paso. ¡Fuera de esta ciudad!",
    ["**Ogre guard** I know you, creature; you may pass."] = "**Ogre guard** Te conozco, criatura; puedes pasar.",
    ["It's the small creature; you may pass."] = "Es la pequeña criatura; puedes pasar.",
    ["Oi! Where do you think you are going? You are for the cooking pot!"] = "¡Oye! ¿Adónde crees que vas? ¡Estás por la olla!",
    ["But I am a friend to ogres..."] = "Pero soy amigo de los ogros...",
    ["Prove it to us with a gift. Get us something from the market."] = "Demuéstranoslo con un regalo. Consíguenos algo del mercado.",
    ["Like what?"] = "¿Cómo qué?",
    ["Surprise us..."] = "Sorpréndenos...",
    ["Not if I can help it."] = "No, si puedo evitarlo.",
    ["You can help by being tonight's dinner, or you can go away. Now, which shall it be?"] = "Puedes ayudar siendo la cena de esta noche o puedes irte. Ahora bien, ¿cuál será?",
    ["Okay, okay. I'm going."] = "Está bien, está bien. Voy.",
    ["Back to whence you came!"] = "¡De vuelta al lugar de donde viniste!",
    ["The guard pushes you out of the city."] = "El guardia te empuja fuera de la ciudad.",
    ["I tire of ogres; prepare to die!"] = "Me canso de los ogros; ¡prepárate para morir!",
    ["Grrrrr!"] = "¡Grrrrr!",
    ["Stop, creature! Oh it's you. Well, what have you got for us, then?"] = "¡Detente, criatura! Ah, eres tú. Bueno, ¿qué tienes entonces para nosotros?",
    ["*If the player has a rock cake:*"] = "*Si el player tiene un pastel de rock:*",
    ["How about this?"] = "¿Qué tal esto?",
    ["Well, well, look at this. My favourite: rock cake! Okay, we will let it through."] = "Bueno, bueno, mira esto. Mi favorito: ¡el pastel de roca! Está bien, lo dejaremos pasar.",
    ["*If the player doesn't have a rock cake:*"] = "*Si el player no tiene pastel de rock:*",
    ["I didn't bring anything."] = "No traje nada.",
    ["Didn't bring anything? In that case shove off!"] = "¿No trajiste nada? ¡En ese caso, lárgate!",
    ["It's that creature again. This time we will let it go."] = "Es esa criatura otra vez. Esta vez lo dejaremos pasar.",
    ["Yous needs ta stay away from dis place...yous get da sickies and mebe yous goes to dead if yous da unlucky fing."] = "Necesitas mantenerte alejado de este lugar... te enfermas y tal vez mueras si tienes mala suerte.",
    ["Hey yous tryin' not to get da sickies else yous be da sick- un and mebe get to be a dead-un if yous be da unlucky fing."] = "Oye, estás tratando de no enfermarte, de lo contrario estarás enfermo y quizás llegues a estar muerto si tienes mala suerte.",
    ["Don't worry, I know how to take care of myself."] = "No te preocupes, sé cuidarme.",
    ["Yeah, whats yous wants creatures?"] = "Sí, ¿qué quieres criaturas?",
    ["Yous best not touch dem till yous chat wiv Grish - use look at dem again more when yous do stuff for Grish."] = "Es mejor que no los toques hasta que hables con Grish. Usa mirarlos de nuevo más cuando hagas cosas para Grish.",
    ["Does the little creature want to buy sumfin'?"] = "¿La pequeña criatura quiere comprar algo?",
    ["Yes I do."] = "Sí, lo hago.",
    ["Welcome to Grud's Herblore Stall."] = "Bienvenido al puesto Herblore de Grud.",
    ["No I don't."] = "No, no lo sé.",
    ["Suit yourself."] = "Haz lo que quieras.",
    ["You be careful in pit. It deep and dark and long way down."] = "Ten cuidado en el pozo. Es profundo, oscuro y muy profundo.",
    ["Do you know what's down there?"] = "¿Sabes lo que hay ahí abajo?",
    ["Forge for war. Make weak strong, or make dead. Weak worse than dead."] = "Forja para la guerra. Haz que los débiles sean fuertes o haz que mueran. Débil peor que muerto.",
    ["Bandos say so."] = "Bandos lo dice.",
    ["** Ogre trader: ** What the human be wantin'?"] = "** Ogre trader: ** ¿Qué quiere el ser humano?",
    ["Can I see what you are selling?"] = "¿Puedo ver lo que estás vendiendo?",
    ["** Ogre trader: ** I suppose so."] = "** Ogre trader: ** Supongo que sí.",
    ["I don't need anything."] = "No necesito nada.",
    ["** Ogre trader: ** As you wish."] = "** Ogre trader: ** Como desees.",
    ["Grrr, little animal; I shall destroy you!"] = "Grrr, animalito; ¡Te destruiré!",
    ["Trade with me? Who do you think you are?"] = "¿Comerciar conmigo? ¿Quién crees que eres?",
    ["Arr, small thing wants my food, does it? I'll teach you to deal with ogres!"] = "Arr, cosita quiere mi comida, ¿verdad? ¡Te enseñaré a lidiar con ogros!",
    ["Excuse me, can I get some service here, please?"] = "Disculpe, ¿puedo obtener algún servicio aquí, por favor?",
    ["GRAAAAAH! You go away, human! Me too busy with training to talk to puny thing like you."] = "¡GRAAAAAH! ¡Vete, humano! Estoy demasiado ocupado con el entrenamiento para hablar con un insignificante como tú.",
    ["I do apologise, sir. We're temporarily unable to meet your banking needs. We'll be open just as soon as we realise our customer experience goals and can guarantee the high standards of service that you expect from all branches of the Bank of Gielinor."] = "Le pido disculpas, señor. Temporalmente no podemos satisfacer sus necesidades bancarias. Estaremos abiertos tan pronto como alcancemos nuestros objetivos de experiencia del cliente y podamos garantizar los altos estándares de servicio que espera de todas las sucursales del Banco de Gielinor.",
    ["What did you just say to me?"] = "¿Qué me acabas de decir?",
    ["We're closed until I can teach these wretched creatures some manners."] = "Estamos cerrados hasta que pueda enseñarles algunos modales a estas miserables criaturas.",
    ["Ah, right. Good luck with that."] = "Ah, claro. Buena suerte con eso.",
    ["Hi, human! You want to take or give your things?"] = "¡Hola, humano! ¿Quieres tomar o regalar tus cosas?",
    ["Oooh! First me say you haves items ready for collection from da Grand Exchange."] = "¡Oh! Primero, digo que tiene artículos listos para ser recogidos en da Grand Exchange.",
    ["Dis Oo'glog bank place! We friends with Bank of RuneScape. We no thumpy-thumpy customers for their stuffses."] = "¡Este lugar del banco Oo'glog! Somos amigos del Bank of RuneScape. No somos clientes exigentes para sus productos.",
    ["That's...good to hear."] = "Eso es... bueno escucharlo.",
    ["Outlander, I have work to be getting on with... Please stop bothering me."] = "Outlander, tengo trabajo que hacer... Por favor, deja de molestarme.",
    ["Hello there. So you're a bard?"] = "Hola. ¿Entonces eres un bardo?",
    ["I am afraid I cannot speak to outerlanders. Besides, I am busy composing an epic."] = "Me temo que no puedo hablar con los extranjeros. Además, estoy ocupado componiendo una epopeya.",
    ["Hello again to you, [Fremennik name]. Us bards should stick together, what?"] = "Hola de nuevo, [Fremennik name]. Nosotros, los bardos, deberíamos permanecer unidos, ¿qué?",
    ["I was wondering..."] = "Me preguntaba...",
    ["I was wondering... Can I learn to play my lyre again?"] = "Me preguntaba... ¿Puedo volver a aprender a tocar mi lira?",
    ["Well, that is an interesting question. Let me let you into a little secret. If you make another offering to the Fossegrimen you will learn a secret melody."] = "Bueno, esa es una pregunta interesante. Déjame contarte un pequeño secreto. Si haces otra ofrenda al Fossegrimen aprenderás una melodía secreta.",
    ["What kind of melody?"] = "¿Qué tipo de melodía?",
    ["It is the song of Rellekka. When you play it, it will bring you back to this town wherever you are in this world. We often go adventuring with bards for precisely this reason. No matter where we have ended up we can return safe and sound to home."] = "Es la canción de Rellekka. Cuando lo juegues, te llevará de regreso a esta ciudad, dondequiera que estés en este mundo. A menudo salimos de aventuras con bardos precisamente por esta razón. No importa dónde hayamos terminado, podemos regresar sanos y salvos a casa.",
    ["Thanks, Olaf!"] = "¡Gracias, Olaf!",
    ["I forget now..."] = "Ahora lo olvido...",
    ["Good day, traveller. Don't see many of your kind around here, anything I can help you with?"] = "Buenos días, viajero. No veo muchos de tu tipo por aquí, ¿en qué puedo ayudarte?",
    ["Talk about 'Visions of Havenhythe"] = "Charla sobre 'Visiones de Havenhythe",
    ["Can you tell me more about this place?"] = "¿Puedes contarme más sobre este lugar?",
    ["This is Wendlewick, largest settlement this side of Havenhythe. We're fishermen and craftsmen, mostly."] = "Este es Wendlewick, el asentamiento más grande de este lado de Havenhythe. Somos pescadores y artesanos, en su mayoría.",
    ["It's a nice place, I'd say. Not that I have much to compare it to."] = "Es un lugar agradable, diría yo. No es que tenga mucho con qué compararlo.",
    ["We don't often get visited by outlanders like yourself, but you'll be treated right for so long as you choose to stay."] = "No nos visitan a menudo forasteros como tú, pero te tratarán bien mientras decidas quedarte.",
    ["Goodbye."] = "Adiós.",
    ["Not right now. Take care."] = "No en este momento. Cuidarse.",
    ["Thank you for answering my questions. Take care."] = "Gracias por responder mis preguntas. Cuidarse.",
    ["Hello again!"] = "¡Hola de nuevo!",
    ["Hmph!"] = "¡Hmph!",
    ["Safalaan said I could get more papyrus from you."] = "Safalaan dijo que podría conseguirte más papiro.",
    ["Hmph, hmm. I suppose so. Here you go."] = "Hmph, mmm. Supongo que sí. Aquí tienes.",
    ["Erk...sorry, I don't have enough space in my inventory. I need 3 free slots."] = "Erk... lo siento, no tengo suficiente espacio en mi inventario. Necesito 3 espacios libres.",
    ["Hmph, typical! Come back when you have."] = "¡Hmph, típico! Vuelve cuando lo hayas hecho.",
    ["[Old Man Ral gives you some papyrus.]"] = "[Old Man Ral te regala unos papiros.]",
    ["What do you do here?"] = "¿Qué haces aquí?",
    ["Hmph! Why? What do I know? I'm just an old man; what would anyone want with an old man?"] = "¡Hmph! ¿Por qué? ¿Qué sé yo? Solo soy un old man; ¿Qué querría alguien con un old man?",
    ["I'm lost. Can you help me?"] = "Estoy perdido. ¿Me puedes ayudar?",
    ["I'm lost... Can you help me?"] = "Estoy perdido... ¿Puedes ayudarme?",
    ["Hmph! Who says I'm not lost, eh? Ever think of that, did you? In a rush to find out all the answers, not thinking for a second that someone else might be just as lost, if not more lost, than you! And what do you care about them, huh?"] = "¡Hmph! ¿Quién dice que no estoy perdido, eh? ¿Alguna vez pensaste en eso, verdad? ¡Con prisa por encontrar todas las respuestas, sin pensar ni por un segundo que alguien más podría estar tan perdido, si no más, que tú! ¿Y a ti qué te importan, eh?",
    ["Do you know about the Myreque?"] = "¿Conoces el Myreque?",
    ["Hmph! Why should I know about the Myreque, eh? What use have they ever been to me, huh? I ask you!"] = "¡Hmph! ¿Por qué debería saber del Myreque, eh? ¿De qué me han servido alguna vez, eh? ¡Les pido que!",
    ["Can you help me?"] = "¿Puedes ayudarme?",
    ["Hmph! What makes you think that I can help you, eh? Do I look like a fountain of knowledge, eh? Do I?"] = "¡Hmph! ¿Qué te hace pensar que puedo ayudarte, eh? ¿Parezco una fuente de conocimiento, eh? ¿Yo?",
    ["Well, you've helped me before! You said something about symbols? To find the Myreque."] = "Bueno, ¡me has ayudado antes! ¿Dijiste algo sobre símbolos? Para encontrar el Myreque.",
    ["Hmph! Yes of course, that's how to get to them. Follow the symbols."] = "¡Hmph! Sí, por supuesto, así es como llegar a ellos. Sigue los símbolos.",
    ["Which symbols?"] = "¿Qué símbolos?",
    ["The symbol of the Myreque - the silver sickle!"] = "El símbolo del Myreque: ¡la hoz de plata!",
    ["Oh, and where would that be then?"] = "Ah, ¿y dónde sería eso entonces?",
    ["Around and about; it should be an aid."] = "Vueltas y vueltas; debería ser una ayuda.",
    ["More..."] = "Más...",
    ["Previous..."] = "Anterior...",
    ["About the Task System..."] = "Acerca del sistema de tareas...",
    ["I've completed all of the Elite tasks in the Morytania set."] = "He completado todas las tareas Elite del conjunto Morytania.",
    ["So you have. I have a special pair of leggings kept aside for you."] = "Así que sí. Tengo un par de mallas especiales reservadas para ti.",
    ["[Old Man Ral hands you a pair of leggings and a few lamps.]"] = "[Old Man Ral te entrega un par de mallas y algunas lámparas.]",
    ["There you go. They're a bit slimy, but they should help you out in the Columbarium when making those blood runes of yours. Oh, and you might find yourself more skilled at making prayer renewal potions."] = "Ahí lo tienes. Son un poco viscosos, pero deberían ayudarte en el Columbario a la hora de hacer esas runas de sangre tuyas. Ah, y es posible que adquieras más habilidades para preparar pociones renovadoras de oración.",
    ["Thanks! What else do they do?"] = "¡Gracias! ¿Qué más hacen?",
    ["Well, from what I've heard, Lyra is getting so good with mushrooms that you'll get double from that patch, and you should be more prosperous in the Slayer Tower too."] = "Bueno, por lo que he oído, Lyra se está volviendo tan bueno con los hongos que obtendrás el doble con ese parche, y también deberías ser más próspero en la Torre Slayer.",
    ["Ah, the leggings-wearer! How are you finding them?"] = "¡Ah, el que usa calzas! ¿Cómo los estás encontrando?",
    ["I lost them."] = "Los perdí.",
    ["Oh, no!"] = "¡Oh, no!",
    ["Never mind, I have another pair. Here..."] = "No importa, tengo otro par. Aquí...",
    ["[Old Man Ral hands you some leggings.]"] = "[Old Man Ral te entrega unos leggings.]",
    ["Choose an option:"] = "Elige una opción:",
    ["Tell me about the Achievement System."] = "Háblame del Sistema de Logros.",
    ["Very well: the Achievement System is a collection of deeds you may wish to complete while adventuring around the world."] = "Muy bien: el Sistema de Logros es una colección de hazañas que quizás desees completar mientras viajas por el mundo.",
    ["You can earn special rewards for completing certain achievements; at the very least, each is worth a cash bounty from Explorer Jack in Lumbridge."] = "Puedes ganar recompensas especiales por completar ciertos logros; como mínimo, cada uno vale una recompensa en efectivo de Explorer Jack en Lumbridge.",
    ["Some also give items that will help complete other achievements, and many count as progress towards the set for the area they're in."] = "Algunos también ofrecen elementos que ayudarán a completar otros logros y muchos cuentan como progreso hacia el conjunto del área en la que se encuentran.",
    ["Tell me about the set reward for this locality."] = "Cuéntame sobre la recompensa establecida para esta localidad.",
    ["Tell me about the set reward for this area."] = "Cuéntame sobre la recompensa establecida para esta área.",
    ["For completing the Morytania set, you are presented with some leggings."] = "Para completar el conjunto Morytania, se te presentan unos leggings.",
    ["These leggings will become increasingly useful as you complete greater difficulties of task sets."] = "Estos leggings serán cada vez más útiles a medida que completes conjuntos de tareas de mayor dificultad.",
    ["When you are presented with your rewards, you will be told of their uses."] = "Cuando se le presenten sus recompensas, se le informará sobre sus usos.",
    ["You may also see what rewards a set item provides by hovering over the Rewards icon for its Exploration Achievement set in the Achievements interface."] = "También puedes ver qué recompensas proporciona un elemento determinado al pasar el cursor sobre el ícono de Recompensas de su Logro de exploración establecido en la interfaz de Logros.",
    ["How do I claim these rewards?"] = "¿Cómo reclamo estas recompensas?",
    ["How do I claim the rewards?"] = "¿Cómo reclamo las recompensas?",
    ["You need to complete all Tasks within a particular difficulty set, then you can claim your reward."] = "Debes completar todas las tareas dentro de un conjunto de dificultad particular y luego podrás reclamar tu recompensa.",
    ["Some of the Morytania set's Tasks are simple, some require certain skill levels, and others require quests to be started or completed."] = "Algunas de las tareas del conjunto Morytania son simples, algunas requieren cierto skill levels y otras requieren que se inicien o completen misiones.",
    ["To claim your Morytania set rewards, speak to Hiylik Myna just east of Paterdomus, Robin in Port Phasmatys, the Strange Old Man at the Barrows or myself."] = "Para reclamar las recompensas del conjunto Morytania, habla con Hiylik Myna justo al este de Paterdomus, con Robin en Port Phasmatys, con Strange Old Man en Barrows o conmigo mismo.",
    ["Sorry, I was just leaving."] = "Lo siento, me estaba yendo.",
    ["Could I buy a spare of the reward?"] = "¿Puedo comprar un repuesto de la recompensa?",
    ["Morytania legs 1"] = "Morytania piernas 1",
    ["Morytania legs 1? Yes, but I'm afraid it would cost you 1,500 coins."] = "Morytania piernas 1? Sí, pero me temo que te costaría 1.500 coins.",
    ["Purchase another for 1,500 coins?"] = "¿Comprar otro por 1.500 coins?",
    ["Yes"] = "si",
    ["[You're handed another Morytania legs 1.]"] = "[Te entregan otras piernas Morytania 1.]",
    ["Morytania legs 2"] = "Morytania piernas 2",
    ["Morytania legs 2? Yes, but I'm afraid it would cost you 2,500 coins."] = "Morytania piernas 2? Sí, pero me temo que te costaría 2500 coins.",
    ["Purchase another for 2,500 coins?"] = "¿Comprar otro por 2500 coins?",
    ["[You're handed another Morytania legs 2.]"] = "[Te entregan otras piernas Morytania 2.]",
    ["Morytania legs 3"] = "Morytania piernas 3",
    ["Morytania legs 3? Yes, but I'm afraid it would cost you 7,500 coins."] = "Morytania piernas 3? Sí, pero me temo que te costaría 7.500 coins.",
    ["Purchase another for 7,500 coins?"] = "¿Comprar otro por 7.500 coins?",
    ["[You're handed another Morytania legs 3.]"] = "[Te entregan otras piernas Morytania 3.]",
    ["Morytania legs 4"] = "Morytania piernas 4",
    ["Morytania legs 4? Yes, but I'm afraid it would cost you 15,000 coins."] = "Morytania patas 4? Sí, pero me temo que te costaría 15.000 coins.",
    ["Purchase another for 15,000 coins?"] = "¿Comprar otro por 15.000 coins?",
    ["[You're handed another Morytania legs 4.]"] = "[Te entregan otras patas Morytania 4.]",
    ["Okay, thanks."] = "Está bien, gracias.",
    ["What are you doing on this shipwreck?"] = "¿Qué haces en este naufragio?",
    ["Shipwreck?!? Not shipwreck, surely not! Just in port, that's all!"] = "¿¡¿Naufragio?!? ¡Naufragio no, seguro que no! ¡Sólo en el puerto, eso es todo!",
    ["Don't be silly - half the ship's missing!"] = "No seas tonto: ¡falta la mitad del barco!",
    ["No no no - the captain's just waiting for the wind to change, then we're off!"] = "No, no, no. El capitán solo está esperando a que cambie el viento y ¡nos vamos!",
    ["You mean the skeleton sitting here in this chair?"] = "¿Te refieres al esqueleto sentado aquí en esta silla?",
    ["You must show more respect to the Captain."] = "Debes mostrarle más respeto al Capitán.",
    ["How is it going?"] = "¿Cómo te va?",
    ["Wonderful, wonderful! Mother's coming to get me!"] = "¡Maravilloso, maravilloso! ¡Mamá viene a buscarme!",
    ["I have some bad news for you..."] = "Tengo malas noticias para ti...",
    ["Oh? Has she been held up?"] = "¿Ah? ¿La han retenido?",
    ["I'm sorry to say that your mother recently passed away."] = "Lamento decirte que tu madre falleció recientemente.",
    ["Oh, mother. My dear old mother."] = "Oh, madre. Mi querida madre.",
    ["A long time may have passed since we have seen each other, but the love was still here. I missed her dearly."] = "Puede que haya pasado mucho tiempo desde que nos vimos, pero el amor seguía aquí. La extrañé muchísimo.",
    ["Her house is empty, if you wanted to move there. It's a bit nicer than this shipwreck."] = "Su casa está vacía, si quisieras mudarte allí. Es un poco mejor que este naufragio.",
    ["I will take you up on your suggestion. The least I can do is take care of her pride and joy, now that she's gone. Thank you, Player!"] = "Aceptaré tu sugerencia. Lo menos que puedo hacer es cuidar de su orgullo y alegría ahora que ya no está. ¡Gracias, Player!",
    ["Congratulations! You have compelted: 'Legal Entitlement' - Inform the Old man about the fate of his mother after 'Vessel of the Harbinger'."] = "¡Felicitaciones! Has obligado: 'Derecho legal' - Informar al Old man sobre el destino de su madre después de 'Vessel of the Harbinger'.",
    ["How are you?"] = "¿Cómo estás?",
    ["This house is much cosier than the shipwreck. It even has a skeleton I can talk to!"] = "Esta casa es mucho más acogedora que el naufragio. ¡Incluso tiene un esqueleto con el que puedo hablar!",
    ["Oh, you seem well versed in inventing things. We should share information!"] = "Oh, pareces muy versado en inventar cosas. ¡Deberíamos compartir información!",
    ["Talk to Oldak about the Invention skill?"] = "¿Hablar con Oldak sobre la habilidad Invention?",
    ["Yes - talk about Invention."] = "Sí, habla de Invention.",
    ["I've heard word from other inventors that you are making great strides yourself, applying divine energy to making new technology."] = "He oído decir a otros inventores que tú mismo estás logrando grandes avances, aplicando energía divina para crear nueva tecnología.",
    ["And I was hoping that you might teach me something about it. In return, I could teach you the secrets of cave goblin electricity."] = "Y esperaba que pudieras enseñarme algo al respecto. A cambio, podría enseñarte los secretos de la electricidad de los duendes de las cavernas.",
    ["I'm certain it will open up more avenues of discovery for you to work on."] = "Estoy seguro de que te abrirá más caminos de descubrimiento en los que trabajar.",
    ["In fact, I can teach you right now if you'd like?"] = "De hecho, ¿puedo enseñarte ahora mismo si quieres?",
    ["What sorts of devices can I build with cave goblin electricity?"] = "¿Qué tipo de dispositivos puedo construir con la electricidad de los duendes de las cavernas?",
    ["Well, you've seen how we use it in Dorgesh-Kaan, but it does have applications beyond mere illumination."] = "Bueno, ya has visto cómo lo usamos en Dorgesh-Kaan, pero tiene aplicaciones más allá de la mera iluminación.",
    ["It has attractive and repulsive applications too - think traps, collectors, and measuring and mapping tools"] = "También tiene aplicaciones atractivas y repulsivas: trampas de pensamiento, recolectores y herramientas de medición y mapeo.",
    ["It has some limited use for combat application too, but it's a technology that will mostly aid you with other skills."] = "También tiene un uso limitado para aplicaciones de combate, pero es una tecnología que te ayudará principalmente con otras habilidades.",
    ["I hope you are making good use of cave goblin electricity in your inventions."] = "Espero que estés haciendo un buen uso de la electricidad de los duendes de las cavernas en tus inventos.",
    ["I'm certainly getting a lot out of using divine energy - very exciting stuff!"] = "Ciertamente estoy aprovechando mucho el uso de la energía divina: ¡algo muy emocionante!",
    ["No - talk about quest or other things."] = "No, habla de misiones u otras cosas.",
    ["Oh, hello! I was just trying to discover the properties of these magical stones you call 'runes', and trying to make some devices to harness their power."] = "¡Oh, hola! Sólo estaba tratando de descubrir las propiedades de estas piedras mágicas que ustedes llaman \"runas\", y tratando de hacer algunos dispositivos para aprovechar su poder.",
    ["What have you discovered?"] = "¿Qué has descubierto?",
    ["Oh, it's terribly exciting! Let me explain..."] = "¡Oh, es terriblemente emocionante! Déjame explicarte...",
    ["[Oldak lectures you on the construction of runes and you find yourself thinking about Runecrafting with greater clarity.]"] = "[Oldak te da una conferencia sobre la construcción de runas y te encuentras pensando en Runecrafting con mayor claridad.]",
    ["Oh, I see!"] = "¡Oh, ya veo!",
    ["[Oldak lectures you on the magical energies stored within runes and you find yourself thinking about Magic with greater clarity.]"] = "[Oldak te sermonea sobre las energías mágicas almacenadas en las runas y te encuentras pensando en Magic con mayor claridad.]",
    ["[Oldak lapses into technical jargon and you don't understand a word.]"] = "[Oldak cae en la jerga técnica y no entiendes una palabra.]",
    ["Oh... How interesting."] = "Oh... Qué interesante.",
    ["[Oldak lectures you on the contruction of runes, but you find yourself greatly confused about Runecrafting.]"] = "[Oldak te da una conferencia sobre la construcción de runas, pero te sientes muy confundido acerca de Runecrafting.]",
    ["[Oldak lectures you on the magical energies stored within runes, but you find yourself greatly confused about Magic.]"] = "[Oldak te sermonea sobre las energías mágicas almacenadas en las runas, pero te sientes muy confundido acerca de Magic.]",
    ["What have you made?"] = "¿Qué has hecho?",
    ["The only thing I've been able to make so far is this. I call it the moving-over-distance sphere."] = "Lo único que he podido hacer hasta ahora es esto. Yo lo llamo la esfera que se mueve a distancia.",
    ["Well, I was experimenting with these blue runes, the ones you call 'law' runes. They have a strange property of being able to move instantly from one place to another."] = "Bueno, estaba experimentando con estas runas azules, las que ustedes llaman runas de 'ley'. Tienen la extraña propiedad de poder trasladarse instantáneamente de un lugar a otro.",
    ["I know; I couldn't believe it either!"] = "Lo sé; ¡Yo tampoco lo podía creer!",
    ["I found that whenever I prepared powdered law runes in a certain way and then threw them on the ground, I would appear somewhere else in the city."] = "Descubrí que cada vez que preparaba runas de ley en polvo de cierta manera y luego las arrojaba al suelo, aparecía en otro lugar de la ciudad.",
    ["[So, I made this sphere. It's a glass ball coated with powdered law runes, prepared in a special way.]"] = "[Entonces, hice esta esfera. Es una bola de cristal recubierta con runas de la ley en polvo, preparada de una manera especial.]",
    ["I asked Zanik to test it, and she said that wherever she was in the caves, even if she went to the surface, whenever she smashed the sphere on the ground she would appear back in the city!"] = "Le pedí a Zanik que lo probara, y ella dijo que dondequiera que estuviera en las cuevas, incluso si iba a la superficie, cada vez que rompía la esfera en el suelo, ¡aparecería de regreso en la ciudad!",
    ["I can see how it might be useful, but I wish I knew more about how it worked..."] = "Puedo ver que podría ser útil, pero desearía saber más sobre cómo funciona...",
    ["Can I buy one?"] = "¿Puedo comprar uno?",
    ["Goodbye!"] = "¡Adiós!",
    ["Oh, er, goodbye. Now, where was I..."] = "Oh, ejem, adiós. Ahora, ¿dónde estaba yo...?",
    ["How can I get back to the throne room?"] = "¿Cómo puedo volver a la sala del trono?",
    ["I've been studying the notes I made on the portal, and the ones I made when you and Zanik opened that box in Yu'biusk. I think I understand the energy signature. I could even replicate it."] = "He estado estudiando las notas que tomé en el portal y las que tomé cuando tú y Zanik abrieron esa caja en Yu'biusk. Creo que entiendo la firma energética. Incluso podría replicarlo.",
    ["What I mean is, if you're interested, I could make a moving-over-distance sphere to take you back to Bandos throne room."] = "Lo que quiero decir es que, si estás interesado, podría hacer una esfera que se mueva a distancia para llevarte de regreso a la sala del trono de Bandos.",
    ["Why would I want to go back there?"] = "¿Por qué querría volver allí?",
    ["Well, I don't know. To explore, I suppose. It was just an idea."] = "Bueno, no lo sé. Para explorar, supongo. Fue sólo una idea.",
    ["Is Bandos really dead?"] = "¿Bandos está realmente muerto?",
    ["Could Yu'biusk be restored?"] = "¿Se podría restaurar Yu'biusk?",
    ["No, I'm afraid not. It was totally dead and poisoned. No plants could grow there again. Maybe it'll recover eventually, after thousands and thousands of years, but it's of no use to us."] = "No, me temo que no. Estaba totalmente muerto y envenenado. Ninguna planta podría volver a crecer allí. Tal vez se recupere eventualmente, después de miles y miles de años, pero no nos sirve de nada.",
    ["I want to buy a moving-over-distance sphere."] = "Quiero comprar una esfera móvil a distancia.",
    ["Is Bandos really dead this time?"] = "¿Bandos está realmente muerto esta vez?",
    ["Almost certainly! I can see no scenario in which he could have survived Armadyl's divine-energy cannon."] = "¡Casi seguro! No veo ningún escenario en el que pudiera haber sobrevivido al cañón de energía divina de Armadyl.",
    ["It's possible that a mortal general will try to fill his boots someday, but they would have a hard time becoming as powerful as he was."] = "Es posible que un general mortal intente llenar sus botas algún día, pero les resultaría difícil volverse tan poderoso como él.",
    ["I'm working on new defences based on the knowledge we gained from your encounters with Bandos, and I'm confident that we can see off any new war god who might emerge."] = "Estoy trabajando en nuevas defensas basadas en el conocimiento que obtuvimos de tus encuentros con Bandos, y estoy seguro de que podremos deshacernos de cualquier nuevo dios de la guerra que pueda surgir.",
    ["I want to talk about the Kyzaj Tournament."] = "Quiero hablar sobre el Torneo Kyzaj.",
    ["Yes! I'm glad to see that our city was once again not destroyed."] = "¡Sí! Me alegra ver que nuestra ciudad una vez más no fue destruida.",
    ["How's it going?"] = "¿Cómo te va?",
    ["All is well indeed. I've recently had the opportunity to work with dwarven technology and I can see real benefits to our people in ten, maybe twenty years."] = "Todo está bien. Recientemente tuve la oportunidad de trabajar con tecnología enana y puedo ver beneficios reales para nuestra gente dentro de diez, tal vez veinte años.",
    ["What do you think about Zanik?"] = "¿Qué opinas de Zanik?",
    ["I fear young Zanik has let her optimism get the best of her. There is no way she can survive on Yu'biusk. She, and her followers, are likely already dead."] = "Me temo que la joven Zanik ha dejado que su optimismo se apodere de ella. No hay manera de que pueda sobrevivir en Yu'biusk. Es probable que ella y sus seguidores ya estén muertos.",
    ["Good bye."] = "Adiós.",
    ["You'll need to give me two law runes and a piece of molten glass."] = "Tendrás que darme dos runas de ley y un trozo de vidrio fundido.",
    ["Oldak makes you [number] moving-over-distance sphere[s]."] = "Oldak te convierte en una esfera móvil [número] a distancia [s].",
    ["Where do you want a sphere to?"] = "¿A dónde quieres que vaya una esfera?",
    ["Goblin Village."] = "Pueblo de duendes.",
    ["Would you like to exchange knowledge?"] = "¿Te gustaría intercambiar conocimientos?",
    ["Commit to learning Goblin Electricity?"] = "¿Te comprometes a aprender Goblin Electricity?",
    ["Right then, the secrets of cave goblin electricity are..."] = "En ese momento, los secretos de la electricidad de los duendes de las cavernas son...",
    ["...and make sure not to lick it, as tempting as it might be. Electrocution is not fun."] = "...y asegúrate de no lamerlo, por muy tentador que sea. La electrocución no es divertida.",
    ["What would you like to do?"] = "¿Qué te gustaría hacer?",
    ["View Technology"] = "Ver tecnología",
    ["Leave"] = "salir",
    ["What a pity. I hope you change your mind."] = "Qué lástima. Espero que cambies de opinión.",
    ["*When speaking to Olivia at the Ports District docks in Menaphos.*"] = "*Al hablar con Olivia en los muelles del Distrito Portuario en Menaphos.*",
    ["I've been havin' a gander at the local wildlife, but them guards won't let me back in."] = "He estado echando un vistazo a la vida salvaje local, pero los guardias no me dejan volver a entrar.",
    ["Fancy meetin' you 'ere. Are you busy? I need a bit of 'elp."] = "Me alegro de encontrarte aquí. ¿Estás ocupado? Necesito un poco de ayuda.",
    ["Would you like to help?"] = "¿Quieres ayudar?",
    ["Cheers, love!"] = "¡Salud, amor!",
    ["Not right now."] = "No ahora mismo.",
    ["Oh, well, maybe someone else will pop along."] = "Oh, bueno, tal vez aparezca alguien más.",
    ["The magnificent Crondis has been angered by [monster]. She requires a blood sacrifice and a tribute."] = "El magnífico Crondis se ha enfadado con [monster]. Requiere un sacrificio de sangre y un tributo.",
    ["First, go and kill [number] [monster]."] = "Primero, ve y mata a [número] [monster].",
    ["What have the [monster] done to anger the almighty Crondis?"] = "¿Qué han hecho los [monster] para enojar al todopoderoso Crondis?",
    ["You don't need to know. Will you go to kill them?"] = "No necesitas saberlo. ¿Irás a matarlos?",
    ["Would you like to abandon this city quest?"] = "¿Te gustaría abandonar esta búsqueda de la ciudad?",
    ["Are you sure you wish to abandon this city quest?"] = "¿Estás seguro de que deseas abandonar esta búsqueda de la ciudad?",
    ["A new Menaphos city quest is now available."] = "Ya está disponible una nueva misión de ciudad Menaphos.",
    ["Talk about your current task."] = "Hable sobre su tarea actual.",
    ["Have you vanquished the [number] [monster] for Lady Crondis? ([number] remaining)"] = "¿Has vencido al [número] [monster] para Lady Crondis? ([número] restantes)",
    ["Abandon this city quest."] = "Abandona esta búsqueda de la ciudad.",
    ["Yes, I have slaughtered the [monster]."] = "Sí, he masacrado al [monster].",
    ["Praise be to Crondis!"] = "¡Alabado sea Crondis!",
    ["Now the pitiful wretches have paid for their transgressions, we require a burnt offering."] = "Ahora que los miserables han pagado por sus transgresiones, requerimos un holocausto.",
    ["The next things I need are [item]."] = "Lo siguiente que necesito es [item].",
    ["Right. Why [item]?"] = "Correcto. ¿Por qué [item]?",
    ["The first step towards appeasing Crondis is traditionally a burnt offering of [item]."] = "El primer paso para apaciguar a Crondis es tradicionalmente una ofrenda quemada de [item].",
    ["So please go and get [number] [item]."] = "Así que ve y consigue [número] [item].",
    ["Sure thing."] = "Claro.",
    ["No, sorry."] = "No, lo siento.",
    ["Do you have the tribute for Crondis? She grows impatient. I need [number] [item]. ([number] remaining)"] = "¿Tienes el tributo a Crondis? Ella se impacienta. Necesito [número] [item]. ([número] restantes)",
    ["Number of [item] given to Olivia ([number]/[number])"] = "Número de [item] dado a Olivia ([número]/[número])",
    ["Just one for now. Take it. I'll be back."] = "Sólo uno por ahora. Tómalo. Vuelvo enseguida.",
    ["I have some. Take them. I'll be back."] = "Tengo algunos. Tómelos. Vuelvo enseguida.",
    ["Great. Thank you."] = "Genial. Gracias.",
    ["Yes, I have the [item]."] = "Sí, tengo el [item].",
    ["May the great crocodile smile upon you!"] = "¡Que el gran cocodrilo te sonría!",
    ["Finally, as per tradition, Crondis requires a liquid offering to be poured into the Elid."] = "Finalmente, según la tradición, Crondis requiere que se vierta una ofrenda líquida en el Elid.",
    ["A liquid offering?"] = "¿Una oferta líquida?",
    ["Yes, gather [number] [item] for me and I will have workers liquidise them."] = "Sí, reúne [número] [item] para mí y haré que los trabajadores los liquiden.",
    ["Nope."] = "No.",
    ["Have you gathered the [number] [item]? We need to appease Crondis as soon as possible! ([number] remaining)"] = "¿Has reunido el [número] [item]? ¡Necesitamos apaciguar a Crondis lo antes posible! ([número] restantes)",
    ["Aren't you industrious! Good job."] = "¿No eres trabajador? Buen trabajo.",
    ["Thank you so much for helping me!"] = "¡Muchas gracias por ayudarme!",
    ["I'm ready for a change in career."] = "Estoy listo para un cambio de carrera.",
    ["Oh, really? How can I help?"] = "Oh, ¿en serio? ¿Cómo puedo ayudar?",
    ["Well, I really want to be a Slayer master, though I could do with some practice."] = "Bueno, realmente quiero ser un Slayer master, aunque me vendría bien un poco de práctica.",
    ["Alright, give it your best shot."] = "Muy bien, haz tu mejor esfuerzo.",
    ["Greetings, adventurer! It is I, the Slayer master!"] = "¡Saludos, aventurero! ¡Soy yo, el Slayer master!",
    ["How was that?"] = "¿Cómo estuvo eso?",
    ["Yeah, that was great, but you have to tell me what you want me to slay."] = "Sí, eso estuvo genial, pero tienes que decirme qué quieres que mate.",
    ["Oh, right!"] = "¡Ah, claro!",
    ["Adventurer! I need you to slay...uh..."] = "¡Aventurero! Necesito que mates... uh...",
    ["I need you to slay...[number]...[monster]?"] = "Necesito que mates...[número]...[monster]?",
    ["I can do that."] = "Puedo hacer eso.",
    ["Where could I find [monster]?"] = "¿Dónde puedo encontrar [monster]?",
    ["**Olivia:** There's a large bandit camp north of here, past the quarry, I think."] = "**Olivia:** Creo que hay un gran campamento de bandidos al norte de aquí, más allá de la cantera.",
    ["Did you slay the [number] [monster]? ([number] remaining)"] = "¿Mataste al [número] [monster]? ([número] restantes)",
    ["Not yet. Where could I find [monster] again?"] = "Todavía no. ¿Dónde podría encontrar [monster] nuevamente?",
    ["Did you slay the [number] [monster]? (0 remaining)"] = "¿Mataste al [número] [monster]? (0 restante)",
    ["Yeah, the [monster] have been slain!"] = "¡Sí, los [monster] han sido asesinados!",
    ["Great job, adventurer!"] = "¡Buen trabajo, aventurero!",
    ["So what do I do now?"] = "Entonces, ¿qué hago ahora?",
    ["Tell me what I need to slay next."] = "Dime qué necesito acabar a continuación.",
    ["Again? Okay!"] = "¿Otra vez? ¡Bueno!",
    ["Adventurer! I need to you slay more things for me!"] = "¡Aventurero! ¡Necesito que mates más cosas por mí!",
    ["What must I slay for you, Slayer master?"] = "¿Qué debo matar por ti, Slayer master?",
    ["I have decided that you must slay [number] [monster]."] = "He decidido que debes matar a [número] [monster].",
    ["**Olivia:** They're found inside Kalphite hives under the desert sands. At least that's where I was told..."] = "**Olivia:** Se encuentran dentro de colmenas calfitas bajo las arenas del desierto. Al menos ahí me dijeron...",
    ["I've been tasked to procure supplies for the war effort."] = "Me han encomendado la tarea de conseguir suministros para el esfuerzo bélico.",
    ["Who are we- Who are YOU at war with?"] = "¿Quiénes somos? ¿Con quién estás en guerra TÚ?",
    ["All will be revealed. First up I need [number] [items]. Can I rely on you?"] = "Todo será revelado. Primero necesito [número] [items]. ¿Puedo confiar en ti?",
    ["Affirmative."] = "Afirmativo.",
    ["Negative."] = "Negativo.",
    ["Do you have the [number] [item] at hand, soldier? ([number] remaining)"] = "¿Tienes el [número] [item] a mano, soldado? ([número] restantes)",
    ["Good work, soldier!"] = "¡Buen trabajo, soldado!",
    ["Now that's done, we need the next block of supplies."] = "Ahora que está hecho, necesitamos el siguiente bloque de suministros.",
    ["The next supplies I require are a load of [item]."] = "Los siguientes suministros que necesito son una carga de [item].",
    ["Have you ever tried to fight a war without [item]? I didn't think so."] = "¿Alguna vez has intentado pelear una guerra sin [item]? No lo creo.",
    ["The war effort requires [number] [item]. I assume I can trust you to obtain the [item]?"] = "El esfuerzo de guerra requiere [número] [item]. ¿Asumo que puedo confiar en usted para obtener el [item]?",
    ["You sure can."] = "Seguro que puedes.",
    ["Do you have the supplies, soldier? This war won't fund itself! We need [number] [item]! ([number] remaining)"] = "¿Tienes los suministros, soldado? ¡Esta guerra no se financiará sola! ¡Necesitamos [número] [item]! ([número] restantes)",
    ["Great! Now we are ready to drive the offensive home!"] = "¡Genial! ¡Ahora estamos listos para llevar la ofensiva a casa!",
    ["Can I ask why you're talking like this?"] = "¿Puedo preguntar por qué hablas así?",
    ["Whatever do you mean, soldier?"] = "¿Qué quieres decir, soldado?",
    ["You're talking like an imperial general. It's a bit off-putting."] = "Estás hablando como un general imperial. Es un poco desagradable.",
    ["The guards are always watching. I have to keep up appearances."] = "Los guardias siempre están mirando. Tengo que guardar las apariencias.",
    ["Right...fair enough. What else do...we...need for the war effort?"] = "Cierto... bastante justo. ¿Qué más... nosotros... necesitamos para el esfuerzo bélico?",
    ["Now is the time you have been waiting for, soldier! The killing!"] = "¡Ahora es el momento que estabas esperando, soldado! ¡La matanza!",
    ["We will finally vanquish our dreaded enemy, the [monster]!"] = "¡Finalmente venceremos a nuestro temido enemigo, el [monster]!",
    ["Yes, kill [number] [monster] in the name of the Pharaoh himself!"] = "¡Sí, mata a [número] [monster] en nombre del propio Faraón!",
    ["Okay."] = "Está bien.",
    ["Have you killed [number] kalphites? They're found inside Kalphite hives under the desert sands. We might win this war yet! ([number] remaining)"] = "¿Has matado a los calfitos de [número]? Se encuentran dentro de colmenas calfitas bajo las arenas del desierto. ¡Podríamos ganar esta guerra todavía! ([número] restante)",
    ["Have you killed [number] plague frogs? They're usually sliming around Sophanem. We might win this war yet! ([number] remaining)"] = "¿Has matado las ranas plaga [número]? Por lo general, están adelgazando alrededor de Sophanem. ¡Podríamos ganar esta guerra todavía! ([número] restante)",
    ["Have you killed [number] plague frogs? They're usually sliming around Sophanem. We might win this war yet! (0 remaining)"] = "¿Has matado las ranas plaga [número]? Por lo general, están adelgazando alrededor de Sophanem. ¡Podríamos ganar esta guerra todavía! (0 restante)",
    ["Yes, I have killed the [monster]."] = "Sí, he matado al [monster].",
    ["Have you danced, as they say, in the blood of your enemies? Have you sent the souls of [number] [monster] to the Underworld?"] = "¿Has bailado, como dicen, en la sangre de tus enemigos? ¿Has enviado las almas de [número] [monster] al Inframundo?",
    ["Not that those [monster] have souls, I believe they are truly beyond help."] = "No es que esos [monster] tengan alma, creo que realmente no pueden recibir ayuda.",
    ["I fear you still need a lot more help."] = "Me temo que todavía necesitas mucha más ayuda.",
    ["Sorry, what?"] = "Lo siento, ¿qué?",
    ["Nothing. It was my pleasure."] = "Nada. Fue un placer.",
    ["*Olivia will occasionally produce overhead dialogue.*"] = "*Olivia ocasionalmente producirá diálogos generales.*",
    ["Pirates? Inside the temple?"] = "¿Piratas? ¿Dentro del templo?",
    ["Well we can't have that..."] = "Bueno, no podemos permitir eso...",
    ["We have been warned about your type."] = "Nos han advertido sobre tu tipo.",
    ["No one is permitted inside the sanctum!"] = "¡No se permite a nadie dentro del santuario!",
    ["What would you like to say?"] = "¿Qué te gustaría decir?",
    ["Would you like to trade?"] = "¿Le gustaría negociar?",
    ["Certainly."] = "Por supuesto.",
    ["Where do I get higher-level seeds?"] = "¿Dónde consigo semillas de nivel superior?",
    ["Master farmers usually carry a few higher-level seeds around with them, although I don't know if they'd want to part with them for any price, to be honest."] = "Los grandes agricultores suelen llevar consigo algunas semillas de nivel superior, aunque, para ser honesto, no sé si querrían desprenderse de ellas por algún precio.",
    ["About the recent bank robbery..."] = "Sobre el reciente robo al banco...",
    ["About the recent bank robbery... The robber attacked you, didn't he?"] = "Sobre el reciente robo al banco... El ladrón te atacó, ¿no?",
    ["Something like that, yes. I was just minding my own business, trying to keep these pesky thieves off my stalls, when I heard a strange noise and a scream."] = "Algo así, sí. Estaba ocupándome de mis propios asuntos, tratando de mantener a estos molestos ladrones fuera de mis puestos, cuando escuché un ruido extraño y un grito.",
    ["I went across to see what was going on, but there was a bright purple flash and everything went black. Before I knew what had happened, I was standing in Falador!"] = "Fui a ver qué estaba pasando, pero hubo un destello violeta brillante y todo se volvió negro. Antes de darme cuenta de lo que había sucedido, ¡estaba parada en Falador!",
    ["It took me ages to get back, and when I arrived I saw there was a huge hole in the bank wall and some of the bankers had been killed!"] = "Me tomó mucho tiempo regresar, y cuando llegué vi que había un enorme agujero en la pared del banco y ¡algunos de los banqueros habían sido asesinados!",
    ["Did you see who teleported you to Falador?"] = "¿Viste quién te teletransportó a Falador?",
    ["No, they were standing behind that old man's door."] = "No, estaban parados detrás de la puerta de ese old man.",
    ["He really shouldn't leave his door open all day, especially in this neighbourhood - there are thousands of thieves around, and anyone could wander in!"] = "Realmente no debería dejar la puerta abierta todo el día, especialmente en este vecindario: ¡hay miles de ladrones por ahí y cualquiera podría entrar!",
    ["Okay, thanks for your time."] = "Bien, gracias por tu tiempo.",
    ["You're welcome. Would you like to see my fine selection of seeds?"] = "De nada. ¿Te gustaría ver mi excelente selección de semillas?",
    ["Would you like to see Olivia's stock?"] = "¿Quieres ver las acciones de Olivia?",
    ["Yes please."] = "Sí por favor.",
    ["No, thanks."] = "No, gracias.",
    ["What Would You Like To Do"] = "¿Qué te gustaría hacer?",
    ["Ask the camel about its dung."] = "Pregúntale al camello por su estiércol.",
    ["I'm sorry to bother you, but could you spare me a little dung?"] = "Lamento molestarte, pero ¿podrías ahorrarme un poco de estiércol?",
    ["Are you serious?"] = "¿Hablas en serio?",
    ["Oh yes. If you'd be so kind..."] = "Ah, sí. Si fueras tan amable...",
    ["Well, just you close your eyes first. I'm not doing it while you're watching me!"] = "Bueno, primero cierra los ojos. ¡No lo haré mientras me miras!",
    ["I hope that's what you wanted!"] = "¡Espero que eso sea lo que querías!",
    ["Ohhh yes. Lovely."] = "Ohhh, sí. Hermoso.",
    ["Say something unpleasant."] = "Di algo desagradable.",
    ["*The player says one of the following at random:*"] = "*el player dice uno de los siguientes al azar:*",
    ["*Dialogue 1:*"] = "*Diálogo 1:*",
    ["If I go near that camel, it'll probably bite my hand off."] = "Si me acerco a ese camello, probablemente me arrancará la mano de un mordisco.",
    ["What did you say?"] = "¿Qué dijiste?",
    ["Er, nothing important."] = "Er, nada importante.",
    ["Ah, a human. Do you know anything about flying?"] = "Ah, un humano. ¿Sabes algo sobre volar?",
    ["Flying?"] = "¿Volando?",
    ["Yes, flying. It's a wonderful thing. I've seen this glider fly, and it's so elegant and fast. If I could fly, I wouldn't want to do anything else. I'd just fly around all day, swooping and soaring."] = "Sí, volando. Es algo maravilloso. He visto volar este planeador y es muy elegante y rápido. Si pudiera volar, no querría hacer nada más. Simplemente volaría todo el día, descendiendo y elevándose.",
    ["*Dialogue 2:*"] = "*Diálogo 2:*",
    ["Mmm... Looks like that camel would make a nice kebab."] = "Mmm... Parece que ese camello sería un buen kebab.",
    ["*(Same as above)*"] = "*(Igual que arriba)*",
    ["*Dialogue 3:*"] = "*Diálogo 3:*",
    ["I wonder if that camel has fleas..."] = "Me pregunto si ese camello tendrá pulgas...",
    ["Neither - I'm a polite person."] = "Ninguno de los dos, soy una persona educada.",
    ["*You decide not to be rude.*"] = "*Decides no ser grosero.*",
    ["Hello there."] = "Hola.",
    ["Hello."] = "Hola.",
    ["Fine thanks."] = "Bien, gracias.",
    ["Hello Omart."] = "Hola Omart.",
    ["Hello Adventurer. I'm afraid it's too risky to use the ladder again, but I believe that Edmond's working on another tunnel."] = "Hola aventurero. Me temo que es demasiado arriesgado volver a usar la escalera, pero creo que Edmond está trabajando en otro túnel.",
    ["Looks like you won't be needing the rope ladder any more, adventurer. I heard it was you who started the revolution and freed West Ardougne!"] = "Parece que ya no necesitarás la escalera de cuerda, aventurero. ¡Escuché que fuiste tú quien inició la revolución y liberó a West Ardougne!",
    ["So that's why they call you One-Eyed Willy."] = "Por eso te llaman One-Eyed Willy.",
    ["What, just because I'm a cyclops?"] = "¿Qué? ¿Solo porque soy un cíclope?",
    ["How incredibly rude of you to assume that. I've never been so insulted."] = "Qué increíblemente grosero de tu parte asumir eso. Nunca me había sentido tan insultado.",
    ["So, you're not One-Eyed Willy? If that's true, who is?"] = "Entonces, ¿no eres One-Eyed Willy? Si eso es verdad, ¿quién lo es?",
    ["The parrot."] = "El loro.",
    ["You named your parrot One-Eyed Willy? Okay..."] = "¿Le pusiste a tu loro el nombre One-Eyed Willy? Está bien...",
    ["I didn't name him - that's his name! And he's not MY parrot; I'm HIS cyclops! His seeing-eye cyclops!"] = "No le puse el nombre, ¡ese es su nombre! Y él no es MI loro; ¡Soy SU cíclope! ¡Su cíclope que ve!",
    ["But you're wearing an eyepatch, and the parrot isn't. I don't..."] = "Pero tú llevas un parche en el ojo y el loro no. Yo no...",
    ["The parrot seems to whisper-squawk something in the cyclops's ear."] = "El loro parece susurrar algo al oído del cíclope.",
    ["I know, right. Tourists!"] = "Lo sé, cierto. ¡Turistas!",
    ["The parrot seems to whisper-squawk something foreboding in the cyclops's ear."] = "El loro parece susurrar algo siniestro al oído del cíclope.",
    ["No, I don't think we should tell them about The Harbinger."] = "No, no creo que debamos contarles sobre The Harbinger.",
    ["The parrot seems to whisper-squawk something rude into the cyclops's ear."] = "El loro parece susurrar algo grosero al oído del cíclope.",
    ["He says you should probably go. He doesn't like you."] = "Dice que probablemente deberías irte. No le gustas.",
    ["I'm sorry, I'll try not to rescue castaways in the future."] = "Lo siento, intentaré no rescatar náufragos en el futuro.",
    ["I don't like you either."] = "A mí tampoco me gustas.",
    ["Why hello there."] = "Hola.",
    ["Where am I?"] = "¿Dónde estoy?",
    ["Lunar Isle - why don't you go have a look around town."] = "Lunar Isle - ¿Por qué no vas a echar un vistazo a la ciudad?",
    ["The state of the island"] = "El estado de la isla.",
    ["Hi, how are things going?"] = "Hola, ¿cómo van las cosas?",
    ["Well, hopefully a lot better now that you've initiated the calm between the Moon Clan and the Fremenniks."] = "Bueno, espero que mucho mejor ahora que has iniciado la calma entre el Clan Luna y los Fremenniks.",
    ["Remember, if you want to use our Lunar Spells at any time, pray at the altar beside me and you can modify your knowledge!"] = "Recuerda, si quieres usar nuestros Hechizos Lunares en cualquier momento, ¡reza en el altar a mi lado y podrás modificar tus conocimientos!",
    ["*(If the player owns the full set of Lunar equipment)*"] = "*(Si el player posee el conjunto completo de equipo Lunar)*",
    ["How about giving me some Lunar Robes?"] = "¿Qué tal si me regalas algunas túnicas lunares?",
    ["I would gladly say yes... if you didn't already have some in the costume room of your house!"] = "Con mucho gusto diría que sí... ¡si aún no tienes algunos en el salón de disfraces de tu casa!",
    ["Foiled again!"] = "¡Frustrado de nuevo!",
    ["*(If the player is missing any piece of the Lunar equipment)*"] = "*(Si a el player le falta alguna pieza del equipo Lunar)*",
    ["I've lost my [Lunar item]."] = "He perdido mi [Lunar item].",
    ["I know. Good job, I knew you would drop it!"] = "Lo sé. ¡Buen trabajo, sabía que lo dejarías!",
    ["But it's going to cost you. It will be [amount] coins!"] = "Pero te va a costar. ¡Será [amount] coins!",
    ["Yeah, I'll pay that!"] = "¡Sí, lo pagaré!",
    ["The war against the daggermouths"] = "La guerra contra los bocadagas",
    ["Hello again. Seen Cyrisus recently?"] = "Hola de nuevo. ¿Has visto Cyrisus recientemente?",
    ["As you mention it, yes. He wanted to create more astral runes."] = "Como lo mencionas, sí. Quería crear más runas astrales.",
    ["Interesting."] = "Interesante.",
    ["He said something about fighting kalphites, whatever they are."] = "Dijo algo sobre luchar contra los calfitos, sean lo que sean.",
    ["Sounds like his fear of combat really is a problem of the past!"] = "¡Parece que su miedo al combate realmente es un problema del pasado!",
    ["You've done well. Very well."] = "Lo has hecho bien. Muy bien.",
    ["Hi."] = "Hola.",
    ["Hello. Still fighting evil with Cyrisus?"] = "Hola. ¿Sigues luchando contra el mal con Cyrisus?",
    ["Oh. You've not heard: he's no longer with us. He passed away."] = "Oh. No lo has oído: ya no está con nosotros. Él falleció.",
    ["What? Oh no."] = "¿Qué? Oh, no.",
    ["But he died fighting for a good cause. He'll be remembered as a great hero."] = "Pero murió luchando por una buena causa. Será recordado como un gran héroe.",
    ["I suppose the good do die young."] = "Supongo que los buenos mueren jóvenes.",
    ["The attack steals some of your health. <!-- filtered -->"] = "El ataque roba parte de tu salud. <!-- filtered -->",
    ["Category:Non-spoken transcripts"] = "Categoría: Transcripciones no habladas",
    ["Meow!"] = "¡Miau!",
    ["Meow."] = "Miau.",
    ["Meow..."] = "Miau...",
    ["Meow?"] = "¿Miau?",
    ["Meowwwwww."] = "Miauwwwwww.",
    ["Defeat the evil, Ben the Wise!"] = "¡Derrota al mal, Ben el Sabio!",
    ["Humphrey catches any crows that land on the farm, and I get to eat them. It's a wonderful deal we have going on."] = "Humphrey atrapa los cuervos que aterrizan en la granja y yo puedo comérmelos. Es un trato maravilloso el que tenemos en marcha.",
    ["I conjure... UNDEAD MOUSE! That'll teach you."] = "Yo conjuro... ¡RATÓN NO MUERTO! Eso te enseñará.",
    ["I cast... WATER WAVE! Take that, mouse!"] = "Lancé... ¡OLA DE AGUA! ¡Toma eso, ratón!",
    ["I'm Ben's familiar, Onyx the Black! I scare away danger and seek out treasure!"] = "¡Soy el familiar de Ben, Onyx the Black! ¡Ahuyento el peligro y busco tesoros!",
    ["My legal name is just Onyx, though. And I'm actually just a cat."] = "Sin embargo, mi nombre legal es simplemente Onyx. Y en realidad soy sólo un gato.",
    ["Ben tried to cast tele-other on me the other day. It... didn't go so well."] = "Ben intentó enviarme tele-other el otro día. No... no salió tan bien.",
    ["What happened?"] = "¿Qué pasó?",
    ["Let's just say I'm not welcome back at the tannery anymore. I'm still licking dye out of my fur."] = "Digamos que ya no soy bienvenido a la curtiduría. Todavía estoy lamiendo dye de mi pelaje.",
    ["Thank you for teaching Ben some real spells! It gets a bit tiring having to play pretend each day."] = "¡Gracias por enseñarle a Ben algunos hechizos reales! Se vuelve un poco agotador tener que fingir todos los días.",
    ["It was no problem. It's nice that he has someone to practice with."] = "No hubo problema. Es bueno que tenga alguien con quien practicar.",
    ["Hello there. What can I do for you today?"] = "Hola. ¿Qué puedo hacer por ti hoy?",
    ["I'd like to ask about the Gielinor Games."] = "Me gustaría preguntar sobre los juegos Gielinor.",
    ["What would you like to know?"] = "¿Qué te gustaría saber?",
    ["What are the games?"] = "¿Cuáles son los juegos?",
    ["[missing]"] = "[desaparecido]",
    ["What events are running?"] = "¿Qué eventos se están ejecutando?",
    ["We have a number of events running. Which would you like to know more about?"] = "Tenemos varios eventos en marcha. ¿Sobre cuál te gustaría saber más?",
    ["Head-to-Head."] = "Cara a cara.",
    ["Cheese Wheel Rolling."] = "Rueda de queso rodante.",
    ["*(Same as below)*"] = "*(Igual que a continuación)*",
    ["Resource Race."] = "Carrera de recursos.",
    ["Marathon."] = "Maratón.",
    ["I'd like to talk about something else."] = "Me gustaría hablar de otra cosa.",
    ["*(Returns to initial options)*"] = "*(Vuelve a las opciones iniciales)*",
    ["Oh, this event is one of my personal favourites. The athlete rolls a wheel of cheese down a hill and then chases after it."] = "Oh, este evento es uno de mis favoritos personales. El atleta hace rodar una rueda de queso colina abajo y luego la persigue.",
    ["Why?"] = "¿Por qué?",
    ["Erm... Do you know, I've never asked. It's a lot of fun, though. Manic, naturally, and it's really hard to navigate when you're running downhill at, like, a billion miles an hour."] = "Erm... ¿Sabes? Nunca te lo he preguntado. Aunque es muy divertido. Maníaco, naturalmente, y es muy difícil navegar cuando corres cuesta abajo a mil millones de millas por hora.",
    ["What rewards can I get?"] = "¿Qué recompensas puedo obtener?",
    ["Actually I'm good for now."] = "En realidad estoy bien por ahora.",
    ["Let me see the reward shop."] = "Déjame ver la tienda de recompensas.",
    ["*(Welcome to the Gielinor Games Rewards Shop opens)*"] = "*(Se abre la tienda de recompensas de juegos Gielinor)*",
    ["I'd like to trade in my previous rewards for points."] = "Me gustaría canjear mis recompensas anteriores por puntos.",
    ["I'd just like to chat."] = "Sólo me gustaría charlar.",
    ["*When speaking to Ophelia in the Clan Threatre.*"] = "*Al hablar con Ophelia en Clan Threatre.*",
    ["Welcome to the theatre, sir."] = "Bienvenido al teatro, señor.",
    ["What would you like to know about?"] = "¿Qué te gustaría saber sobre?",
    ["It's a theatre, isn't it? Great big stage, curtains, rows of seats."] = "Es un teatro, ¿no? Gran escenario, telones, filas de asientos.",
    ["What can I do here?"] = "¿Qué puedo hacer aquí?",
    ["Tell me about the stage."] = "Cuéntame sobre el escenario.",
    ["Theatre technicians can restrict who has access to the stage, building a list of up to 15 people who are allowed onstage. Guests to the citadel can be added to the list, allowing them to join in the fun too. What you do with the stage is up to you. Try not to get stage-fright, though!"] = "Los técnicos de teatro pueden restringir quién tiene acceso al escenario, creando una lista de hasta 15 personas a las que se les permite subir al escenario. Los invitados a la ciudadela se pueden agregar a la lista, lo que les permitirá unirse a la diversión también. Lo que hagas con el escenario depende de ti. ¡Pero intenta no tener miedo escénico!",
    ["Tell me about sound and spotlights."] = "Cuéntame sobre el sonido y los focos.",
    ["You'll find machines for controlling spotlights and sound effects backstage. If your clan has given you permission to be a theatre technician, then you can use these machines. There are four spotlights that can be targeted at people on the stage, and you can change their colour to suit the scene. With the sound effects machine, you're able to build a list of suitable sounds, ready for easy playback in front of an audience."] = "Encontrarás máquinas para controlar focos y efectos de sonido detrás del escenario. Si tu clan te ha dado permiso para ser técnico de teatro, entonces podrás utilizar estas máquinas. Hay cuatro focos que pueden apuntar a las personas en el escenario y puedes cambiar su color para adaptarlo a la escena. Con la máquina de efectos de sonido, puedes crear una lista de sonidos adecuados, listos para reproducirlos fácilmente frente a una audiencia.",
    ["Tell me about backdrops and props."] = "Cuéntame sobre fondos y accesorios.",
    ["Tell me about the backdrop and scenery props."] = "Cuéntame sobre el telón de fondo y los accesorios del escenario.",
    ["The backdrop is chosen by theatre technicians, and can be changed to other backdrops as needed. Technicians can also add scenery props to the stage to add decoration, such as rocks and clouds. Technicians can draw the stage curtains while adjusting the set."] = "El telón de fondo lo eligen los técnicos del teatro y se puede cambiar a otros fondos según sea necesario. Los técnicos también pueden agregar accesorios de escenografía al escenario para agregar decoración, como rocas y nubes. Los técnicos pueden correr las cortinas del escenario mientras ajustan el decorado.",
    ["Let's talk about something else."] = "Hablemos de otra cosa.",
    ["What's that you're selling?"] = "¿Qué es eso que estás vendiendo?",
    ["Oh, these aren't for sale. They're free. Would you like an Orb of Oculus? It should help you get a good view of the stage."] = "Oh, estos no están a la venta. Son gratis. ¿Quieres un orbe de Oculus? Debería ayudarte a tener una buena vista del escenario.",
    ["Yes, give me an Orb of Oculus."] = "Sí, dame un Orbe de Oculus.",
    ["Here you go."] = "Aquí tienes.",
    ["Ophelia hands you an Orb of Oculus."] = "Ophelia te entrega un Orbe de Oculus.",
    ["What is an Orb of Oculus?"] = "¿Qué es un orbe de Oculus?",
    ["It's an outstanding piece of kit, allowing you to get a great view of the world around you, so it should be handy while watching the stage. Wield it, operate it, and you'll be able to adjust your perspective on the world."] = "Es un excelente kit que te permite obtener una excelente vista del mundo que te rodea, por lo que debería ser útil mientras miras el escenario. Manéjalo, utilízalo y podrás ajustar tu perspectiva del mundo.",
    ["It looked like you were selling sweets."] = "Parecía que estabas vendiendo dulces.",
    ["Well, please don't eat the orbs, they've got glass, metal and magic But, yes, I can see how you'd think they look tasty."] = "Bueno, por favor no te comas los orbes, tienen vidrio, metal y magia. Pero sí, puedo ver cómo pensarías que se ven sabrosos.",
    ["No, thank you."] = "No, gracias.",
    ["Can you impart your wise knowledge to me, Oracle?"] = "¿Puedes impartirme tus sabios conocimientos, Oracle?",
    ["A bird in the hand can make a tasty snack."] = "Un pájaro en la mano puede ser un delicioso refrigerio.",
    ["An answer is unimportant; it is the question that matters."] = "Una respuesta no es importante; es la pregunta lo que importa.",
    ["A woodchuck does not chuck wood."] = "Una marmota no tira madera.",
    ["Beauty is in the eyes of the beholders."] = "La belleza está en los ojos de quien la mira.",
    ["Beware the cabbage: it is both green AND leafy."] = "Cuidado con el repollo: es verde Y frondoso.",
    ["Capes are always in fashion!"] = "¡Las capas siempre están de moda!",
    ["The chicken came before the egg."] = "La gallina vino antes que el huevo.",
    ["The decrepit man is in your head; his prison in his own."] = "El hombre decrépito está en tu cabeza; su prisión en la suya propia.",
    ["Do not fear the dragons...fear their kin."] = "No temas a los dragones... teme a sus parientes.",
    ["Don't judge a book by its cover - judge it by its' grammar and, punctuation."] = "No juzgues un libro por su portada, júzgalo por su gramática y puntuación.",
    ["Everyone you know will one day be dead."] = "Todos los que conoces algún día estarán muertos.",
    ["The final dream will reach its full potential."] = "El sueño final alcanzará su máximo potencial.",
    ["The goblins will never make up their minds on their own."] = "Los duendes nunca tomarán una decisión por sí solos.",
    ["The God Wars are over...as long as the thing they were fighting over remains hidden."] = "Las Guerras de Dios han terminado... siempre y cuando aquello por lo que estaban peleando permanezca oculto.",
    ["The great snake of Guthix guards more than she knows."] = "La gran serpiente de Guthix guarda más de lo que ella sabe.",
    ["Help wanted? Enquire within."] = "¿Necesita ayuda? Consulta por dentro.",
    ["He who uses the power of custard mixes it with his tears."] = "El que usa el poder de las natillas lo mezcla con sus lágrimas.",
    ["If a tree falls in the forest and no one is around, then nobody gets Woodcutting xp."] = "Si un árbol cae en el bosque y no hay nadie alrededor, nadie obtendrá Woodcutting xp.",
    ["If a tree falls in the forest and no one is around, who gets the experience?"] = "Si un árbol cae en el bosque y no hay nadie cerca, ¿quién se queda con la experiencia?",
    ["Imagine you look like a goblin."] = "Imagina que pareces un duende.",
    ["Is it time to wake up? I am not sure..."] = "¿Es hora de despertar? No estoy seguro...",
    ["It's not you; it's me."] = "No eres tú; soy yo.",
    ["Jas left a stone behind."] = "Jas dejó una piedra detrás.",
    ["The last shall become the first."] = "El último se convertirá en el primero.",
    ["The light at the end of the tunnel is the demon-infested lava pit."] = "La luz al final del túnel es el pozo de lava infestado de demonios.",
    ["Many secrets are buried under this land."] = "Muchos secretos están enterrados bajo esta tierra.",
    ["Nothing like a tasty fish."] = "Nada como un rico pescado.",
    ["Pies...they're great, aren't they?"] = "Las tartas... son geniales, ¿no?",
    ["She who was chosen may be chosen again"] = "La que fue elegida podrá ser elegida nuevamente.",
    ["Sometimes you get lucky, sometimes you don't."] = "A veces tienes suerte y otras no.",
    ["The sun will shine before the daughter."] = "El sol brillará ante la hija.",
    ["Templates are a source of great sorrow."] = "Las plantillas son una fuente de gran tristeza.",
    ["There are no crisps at the party."] = "No hay patatas fritas en la fiesta.",
    ["There's going to be a montage."] = "Habrá un montaje.",
    ["They say that ham does not mix well with other kinds of meat."] = "Dicen que el jamón no combina bien con otro tipo de carnes.",
    ["Too many cooks spoil the anchovy pizza."] = "Demasiados cocineros estropean la pizza de anchoas.",
    ["When in Asgarnia, do as the Asgarnians do."] = "Cuando estés en Asgarnia, haz lo que hacen los asgarnianos.",
    ["Who guards the guardsmen?"] = "¿Quién protege a los guardias?",
    ["Your chins will have many more uses."] = "Tus barbijos tendrán muchos más usos.",
    ["Yes, I can. But I'm not going to."] = "Sí, puedo. Pero no voy a hacerlo.",
    ["No. I'm not in the mood."] = "No. No estoy de humor.",
    ["Wen the cold wind blows."] = "Cuando sopla el viento frío.",
    ["Don't you mean 'when'?"] = "¿No te refieres a \"cuándo\"?",
    ["Who?"] = "¿Quién?",
    ["No, when."] = "No, cuándo.",
    ["At the end of things."] = "Al final de las cosas.",
    ["What? I'm lost."] = "¿Qué? Estoy perdido.",
    ["As are we all."] = "Como todos nosotros.",
    ["You know, I preferred your older prophecies."] = "Sabes, prefería tus profecías más antiguas.",
    ["Would you like to hear one?"] = "¿Te gustaría escuchar uno?",
    ["Hear an older prophecy?"] = "¿Escuchas una profecía más antigua?",
    ["No, I'm not in the mood."] = "No, no estoy de humor.",
    ["I've got a little challenge for you."] = "Tengo un pequeño desafío para ti.",
    ["Okay..."] = "Está bien...",
    ["Can you answer this for me, please?"] = "¿Puedes responderme a esto, por favor?",
    ["[The Oracle has given you a challenge scroll!]"] = "[¡El Oracle te ha dado un pergamino de desafío!]",
    ["Please enter the answer to the question."] = "Ingrese la respuesta a la pregunta.",
    ["Enter amount: [Input field]"] = "Ingrese la cantidad: [Input field]",
    ["That's wrong, I'm afraid."] = "Me temo que eso está mal.",
    ["[The Oracle has given you another clue scroll!]"] = "[¡El Oracle te ha dado otro pergamino de pistas!]",
    ["That's right, well done!"] = "Así es, ¡bien hecho!",
    ["Oh, a human, I don't have time for you."] = "Oh, humano, no tengo tiempo para ti.",
    ["I just want to know a little bit more about your company. You're new here, aren't you?"] = "Sólo quiero saber un poco más sobre su empresa. Eres nuevo aquí, ¿no?",
    ["That is none of your concern! Get out before I have the Black Guard throw you out!"] = "¡Eso no es de tu incumbencia! ¡Sal antes de que haga que el Black Guard te eche!",
    ["That's odd, isn't this the office of the Red Axe?"] = "Eso es extraño, ¿no es esta la oficina del Hacha Roja?",
    ["No, quite clearly this is not. Can't you see the banner?"] = "No, claramente no lo es. ¿No ves el cartel?",
    ["Hmm... it looks like some kind of orange flame."] = "Hmm... parece una especie de llama naranja.",
    ["Very clever, yes. That's us, that is. The Orange Flame."] = "Muy inteligente, sí. Esos somos nosotros, eso es. La Llama Naranja.",
    ["But what are you doing here?"] = "¿Pero qué haces aquí?",
    ["The Red Axe has committed treason. They have departed the city. We have clawed our way up from the rabble of the minor companies. We're now wealthy enough to trade on the Trade Octagon."] = "El Hacha Roja ha cometido traición. Han abandonado la ciudad. Nos hemos abierto camino entre la chusma de las empresas menores. Ahora somos lo suficientemente ricos como para comerciar en el octágono comercial.",
    ["Need any help with that at all?"] = "¿Necesitas ayuda con eso?",
    ["That is a scandalous suggestion! Get out of here!"] = "¡Esa es una sugerencia escandalosa! ¡Fuera de aquí!",
    ["I hear you finally defeated the Red Axe in their secret base! That's what a company gets for committing treason and leaving the city. The Orange Flame will make no such mistake!"] = "¡He oído que finalmente derrotaste al Hacha Roja en su base secreta! Eso es lo que obtiene una empresa por cometer traición y abandonar la ciudad. ¡La Llama Naranja no cometerá tal error!",
    ["*When talking to Ordan at the Blast Furnace in Keldagrim.*"] = "*Al hablar con Ordan en el Alto Horno en Keldagrim.*",
    ["Can you un-note any of my items?"] = "¿Puedes eliminar la nota de alguno de mis artículos?",
    ["I can un-note tin, copper, iron, coal, mithril, adamantite, luminite and rune ores."] = "Puedo eliminar los minerales de estaño, cobre, hierro, carbón, mithril, adamantita, luminita y runas.",
    ["*Occasionally a dwarven miner will bring ores to Ordan, which will result in overhead dialogue.*"] = "*Ocasionalmente, un dwarven miner traerá minerales a Ordan, lo que resultará en un diálogo general.*",
    ["*The Dwarven Miner will always engage the dialogue by acknowledging amount and type of ores brought, to which Ordan will always reply with the same dialogue.*"] = "*El Dwarven Miner siempre iniciará el diálogo reconociendo la cantidad y el tipo de minerales traídos, a lo que Ordan siempre responderá con el mismo diálogo.*",
    ["Ah. I wondered when you might interfere."] = "Ah. Me preguntaba cuándo podrías interferir.",
    ["You crash blindly through in a desperate attempt to stop a plan you don't even understand."] = "Chocas a ciegas en un intento desesperado de detener un plan que ni siquiera entiendes.",
    ["Do you even know what's at stake?"] = "¿Sabes lo que está en juego?",
    ["No, you simply see a monster and want to stop it."] = "No, simplemente ves un monstruo y quieres detenerlo.",
    ["So blinkered is your vision that you fail to see the real monsters."] = "Tu visión es tan estrecha que no logras ver a los verdaderos monstruos.",
    ["To think you call yourself a hero. As if that means anything."] = "Pensar que te consideras un héroe. Como si eso significara algo.",
    ["You'll learn your mistake soon enough."] = "Pronto descubrirás tu error.",
    ["Kill me now, it changes nothing."] = "Mátame ahora, no cambia nada.",
    ["Death is but a doorway, time is but a window."] = "La muerte no es más que una puerta, el tiempo no es más que una ventana.",
    ["I'll be back."] = "Volveré.",
    ["Me Orge. You Jayne?"] = "Yo Orge. ¿Eres Jayne?",
    ["**ME ORGE. YOU JAYNE?**"] = "**ME ORGO. ¿TÚ JAYNE?**",
    ["Orge the ogre?"] = "Orge el ogro?",
    ["Mistakes happen. Orge tragic birth accident. Orge not like talk about it."] = "Los errores ocurren. Orge trágico accidente de nacimiento. A Orge no le gusta hablar de eso.",
    ["I could be Jayne. Why?"] = "Podría ser Jayne. ¿Por qué?",
    ["Could be Jayne'? You is Jayne? Or you not is?"] = "¿Podría ser Jayne'? ¿Tú eres Jayne? ¿O no lo es?",
    ["How you be both? Why you hurt Orge?"] = "¿Cómo seréis ambos? ¿Por qué lastimaste a Orge?",
    ["Talking doesn't hurt, Orge. We're just having a conversation."] = "Hablar no hace daño, Orge. Sólo estamos teniendo una conversación.",
    ["You hurt Orge. In head. Orge head hurt. And it your fault. Converge station hurt Orge."] = "Lastimaste a Orge. En cabeza. A Orge le duele la cabeza. Y es tu culpa. La estación convergente dañó a Orge.",
    ["Orge try again. You Jayne? Or you Jayne not? There be no 'could'."] = "Orge inténtalo de nuevo. ¿Eres Jayne? ¿O tú, Jayne, no? No hay ningún \"podría\".",
    ["STOP HURTING ORGE!"] = "¡DEJA DE HERIR A ORGE!",
    ["No, I'm Player."] = "No, soy Player.",
    ["Player dumb name. But it not your fault."] = "Player nombre tonto. Pero no es tu culpa.",
    ["If Player see Jayne, Player tell Orge."] = "Si Player ve a Jayne, Player se lo dice a Orge.",
    ["Did Jayne hug you and squeeze you and call you Orge?"] = "¿Jayne te abrazó, te apretó y te llamó Orge?",
    ["Yeah! How you know?"] = "¡Sí! ¿Cómo lo sabes?",
    ["My Divination level is: 99."] = "Mi nivel Divination es: 99.",
    ["Weird flex, but okay."] = "Flexión extraña, pero está bien.",
    ["Lucky guess."] = "Suposición afortunada.",
    ["Orge look for Jayne. Orge miss hugs."] = "Orge busca a Jayne. Orge señorita abrazos.",
    ["Farewell."] = "Adiós.",
    ["color=yellow"] = "color=amarillo",
    ["Wow, what is that you are wearing?"] = "Vaya, ¿qué es lo que llevas puesto?",
    ["I'm wearing the fully upgraded orikalkum armour. You will be able to smith it yourself in the upcoming Mining and Smithing rework."] = "Llevo puesta la armadura de orikalkum totalmente mejorada. Podrás crearlo tú mismo en las próximas modificaciones de Mining y Smithing.",
    ["To smith it, first you'll need to mine some orichalcite ore, which requires 60 Mining and an appropriate pickaxe."] = "Para forjarlo, primero necesitarás extraer algo de mineral de orichalcita, lo que requiere 60 Mining y un pico apropiado.",
    ["Then with 60 Smithing, you'll be able to smelt the ores into orikalkum bars, and smith orikalkum armour and weapons."] = "Luego, con 60 Smithing, podrás fundir los minerales en barras de orikalkum y forjar armaduras y armas de orikalkum.",
    ["Oh wow! Do you have more information about the rework?"] = "¡Oh, vaya! ¿Tienes más información sobre el retrabajo?",
    ["*(If you have at least one inventory space:)*"] = "*(Si tienes al menos un espacio de inventario:)*",
    ["You're handed a flyer"] = "Te entregaron un folleto",
    ["*(If your inventory is full:)*"] = "*(Si tu inventario está lleno:)*",
    ["If you've got a free space, I can give you a flyer"] = "Si tienes un espacio libre, puedo darte un folleto",
    ["I'm wearing orikalkum armour. You will be able to smith it yourself in the upcoming Mining and Smithing rework. To smith it, first you'll need to mine some orichalcite ore, which requires 60 Mining and an appropriate pickaxe. Then with 60 Smithing, you'll be able to smelt the ores into orikalkum bars, and smith orikalkum armour and weapons."] = "Llevo una armadura de orikalkum. Podrás crearlo tú mismo en las próximas modificaciones de Mining y Smithing. Para forjarlo, primero necesitarás extraer algo de mineral de orichalcita, lo que requiere 60 Mining y un pico apropiado. Luego, con 60 Smithing, podrás fundir los minerales en barras de orikalkum y forjar armaduras y armas de orikalkum.",
    ["What's going on here?"] = "¿Qué está pasando aquí?",
    ["So glad you asked! I'm Orla Fairweather, and these are my colleagues. We're pioneers, researching the art of divination!"] = "¡Me alegra que hayas preguntado! Soy Orla Fairweather y estos son mis colegas. ¡Somos pioneros en investigar el arte de la adivinación!",
    ["Divination? You mean like reading tea leaves, casting bones, that sort of thing?"] = "¿Divination? ¿Te refieres a leer hojas de té, fundir huesos y ese tipo de cosas?",
    ["Oh no, this is much larger! Here, we are dealing with the energy of the world! The fate of Gielinor may be determined by our actions!"] = "¡Oh, no, esto es mucho más grande! ¡Aquí estamos tratando con la energía del mundo! ¡El destino de Gielinor puede estar determinado por nuestras acciones!",
    ["Wow - that does sound interesting."] = "Vaya, eso suena interesante.",
    ["Oh yes. It's early days, but we've had exciting results already."] = "Ah, sí. Aún es temprano, pero ya hemos obtenido resultados interesantes.",
    ["Can I start training divination myself?"] = "¿Puedo empezar a entrenar adivinación yo mismo?",
    ["Can you help me improve my skill in divination?"] = "¿Puedes ayudarme a mejorar mi habilidad en adivinación?",
    ["Of course! We could use all the help we can get!"] = "¡Por supuesto! ¡Nos vendría bien toda la ayuda que podamos conseguir!",
    ["Are you ready to get started?"] = "¿Estás listo para empezar?",
    ["Yes, show me how to train divination."] = "Sí, muéstrame cómo entrenar la adivinación.",
    ["**Orla Fairweather:** The first step is to gather a memory. The wisps to the south will do - see how you get on and come back to me if you need help."] = "**Orla Fairweather:** El primer paso es recopilar un recuerdo. Los fuegos fatuos del sur servirán: mira cómo te va y vuelve a verme si necesitas ayuda.",
    ["Not at the moment, thanks."] = "Por el momento no, gracias.",
    ["I think you're ready for the next step! Do you want to continue learning the ways of divination?"] = "¡Creo que estás listo para el siguiente paso! ¿Quieres seguir aprendiendo los métodos de adivinación?",
    ["Yes!"] = "¡Sí!",
    ["**Orla Fairweather:** You've got some memories, but they're no use to you like that! You need to feed them back to the earth. Give it a go!"] = "**Orla Fairweather:** ¡Tienes algunos recuerdos, pero no te sirven de nada así! Necesitas devolverlos a la tierra. ¡Pruébalo!",
    ["At this rate, you'll surpass my knowledge in no time! Are you ready to continue learning?"] = "¡A este paso, superarás mis conocimientos en poco tiempo! ¿Estás listo para seguir aprendiendo?",
    ["Yes, please."] = "Sí, por favor.",
    ["**Orla Fairweather:** As you've seen, memories can be converted into experience, but that's not all they can be used for. If you focus your mind, you can also receive divine energy - a useful material. Why don't you try it?"] = "**Orla Fairweather:** Como has visto, los recuerdos se pueden convertir en experiencia, pero eso no es todo para lo que se pueden utilizar. Si concentras tu mente, también podrás recibir energía divina, un material útil. ¿Por qué no lo intentas?",
    ["No time to waste! Are you ready to continue?"] = "¡No hay tiempo que perder! ¿Estás listo para continuar?",
    ["**Orla Fairweather:** If you've spare divine energy you can use it to your advantage. Just focus your mind on enhanced experience and you'll get more return from your memories."] = "**Orla Fairweather:** Si te sobra energía divina, puedes usarla a tu favor. Simplemente concentre su mente en una experiencia mejorada y obtendrá más beneficios de sus recuerdos.",
    ["**Orla Fairweather:** You seem to be up to date with my discoveries. However, Faizan is making breakthroughs with divine energy - you should speak to him."] = "**Orla Fairweather:** Parece que estás al día de mis descubrimientos. Sin embargo, Faizan está logrando avances con energía divina; deberías hablar con él.",
    ["Okay, I'll speak to Faizan."] = "Bien, hablaré con Faizan.",
    ["How can I collect memories?"] = "¿Cómo puedo coleccionar recuerdos?",
    ["First, you need to locate a wisp. The ideal wisps for you are right here, just south of the camp. As you become more skilled in divination, you should move on to more complex wisps."] = "Primero, necesitas localizar una mecha. Los mechones ideales para ti están aquí, justo al sur del campamento. A medida que te vuelvas más hábil en la adivinación, deberás pasar a mechones más complejos.",
    ["First, you need to locate a wisp. You already have some skill in divination, so it'd be best for you to find a more complex colony than the one we have here."] = "Primero, necesitas localizar una mecha. Ya tienes cierta habilidad en adivinación, por lo que sería mejor que encontraras una colonia más compleja que la que tenemos aquí.",
    ["**Orla Fairweather:** You can use the map next to me to find out where the most suitable wisps for you are located."] = "**Orla Fairweather:** Puedes usar el mapa a mi lado para saber dónde se encuentran los mechones más adecuados para ti.",
    ["Interact with a wisp to transform it into a spring and harvest memories from it!"] = "¡Interactúa con una brizna para transformarla en un manantial y cosechar recuerdos de ella!",
    ["You'll also get a small amount of divine energy. Hang on to that - it can be used later!"] = "También obtendrás una pequeña cantidad de energía divina. ¡Aférrate a eso, se puede usar más tarde!",
    ["How can I convert memories?"] = "¿Cómo puedo convertir recuerdos?",
    ["What are enriched memories?"] = "¿Qué son los recuerdos enriquecidos?",
    ["Enriched memories are particularly strong memories, charged with power."] = "Los recuerdos enriquecidos son recuerdos particularmente fuertes, cargados de poder.",
    ["If you convert an enriched memory at a crater, you will receive additional experience or energy compared to a normal memory."] = "Si conviertes un recuerdo enriquecido en un cráter, recibirás experiencia o energía adicional en comparación con un recuerdo normal.",
    ["Sounds great! Where can I get them?"] = "¡Suena genial! ¿Dónde puedo conseguirlos?",
    ["You may receive enriched memories just from harvesting normal wisps, if you're lucky!"] = "¡Puedes recibir recuerdos enriquecidos simplemente por recolectar mechones normales, si tienes suerte!",
    ["Alternatively, if you keep an eye out, you may spot an enriched wisp floating around a colony. These always give enriched memories when harvested."] = "Alternativamente, si estás atento, puedes ver una brizna enriquecida flotando alrededor de una colonia. Estos siempre brindan recuerdos enriquecidos cuando se cosechan.",
    ["They are unstable, however. If you want one to stick around you'll need to feed it a memory you've harvested previously. Get your friends to do it too - the more people who feed it, the longer it will stay around!"] = "Sin embargo, son inestables. Si quieres que uno se quede, tendrás que darle un recuerdo que hayas cosechado anteriormente. Haz que tus amigos también lo hagan: ¡cuantas más personas lo alimenten, más tiempo permanecerá ahí!",
    ["Finally, bear in mind you'll need to visit the wisps further away from camp. We've never seen any enriched memories from the wisps to the south, or any enriched wisps floating around down there."] = "Finalmente, ten en cuenta que tendrás que visitar los fuegos fatuos más alejados del campamento. Nunca hemos visto ningún recuerdo enriquecido de los fuegos fatuos del sur, ni ningún fuego enriquecido flotando por ahí abajo.",
    ["That's all, thanks."] = "Eso es todo, gracias.",
    ["That's all I needed to know, thanks."] = "Eso es todo lo que necesitaba saber, gracias.",
    ["Well, you'll need some memories! You remember how to get those, don't you?"] = "Bueno, ¡necesitarás algunos recuerdos! Recuerdas cómo conseguirlos, ¿no?",
    ["No, please go over that again."] = "No, por favor repasa eso otra vez.",
    ["Yes, I remember."] = "Sí, lo recuerdo.",
    ["Well, you've got some memories with you, which is the first step!"] = "Bueno, tienes algunos recuerdos contigo, ¡que es el primer paso!",
    ["**Orla Fairweather:** You need to take one or more memories to a crater. These can be found near any of the wisp colonies."] = "**Orla Fairweather:** Necesitas llevar uno o más recuerdos a un cráter. Estos se pueden encontrar cerca de cualquiera de las colonias de wisp.",
    ["Deposit memories into the crater to receive either additional divination knowledge, or divine energy - something that can be used to create items later on!"] = "Deposita recuerdos en el cráter para recibir conocimiento de adivinación adicional o energía divina, ¡algo que puede usarse para crear objetos más adelante!",
    ["Alternatively, if you have any spare divine energy you can combine that with the memories for additional divination knowledge. We call this 'enhanced' experience."] = "Alternativamente, si tienes energía divina extra, puedes combinarla con los recuerdos para obtener conocimientos adicionales de adivinación. A esto lo llamamos experiencia \"mejorada\".",
    ["To do this, you'll need to throw both a memory and some divine energy into the crater."] = "Para hacer esto, necesitarás arrojar un recuerdo y algo de energía divina al cráter.",
    ["For normal memories, you'll need 5 energy of the same tier as your memory and for enriched memories you'll need 10 lots of energy for the same tier."] = "Para recuerdos normales, necesitarás 5 energías del mismo nivel que tu memoria y para recuerdos enriquecidos necesitarás 10 lotes de energía para el mismo nivel.",
    ["A new discovery has been made! Would you like me to show you?"] = "¡Se ha hecho un nuevo descubrimiento! ¿Quieres que te lo muestre?",
    ["My latest discovery is rather exciting, although unfortunately we haven't been able to observe it in the wisps here."] = "Mi último descubrimiento es bastante emocionante, aunque desafortunadamente no hemos podido observarlo en los mechones de aquí.",
    ["In the other colonies, you will occasionally see an enriched wisp, or be particularly successful when harvesting a normal wisp, resulting in you gathering an enriched memory."] = "En las otras colonias, ocasionalmente verás una mecha enriquecida, o tendrás especial éxito al recolectar una mecha normal, lo que te permitirá recolectar un recuerdo enriquecido.",
    ["Why don't you see if you can find one!"] = "¿Por qué no intentas encontrar uno?",
    ["You've covered everything I know. Faizan has discovered something new, though. You should catch up with him."] = "Has cubierto todo lo que sé. Sin embargo, Faizan ha descubierto algo nuevo. Deberías alcanzarlo.",
    ["First, I'd like to give you a reward for learning the basics of divination. You've shown real dedication!"] = "Primero, me gustaría darte una recompensa por aprender los conceptos básicos de la adivinación. ¡Has demostrado verdadera dedicación!",
    ["You receive 500 pieces of flickering energy!"] = "¡Recibes 500 piezas de energía parpadeante!",
    ["Use them wisely."] = "Úsalos sabiamente.",
    ["What can I aid you with today?"] = "¿En qué puedo ayudarte hoy?",
    ["I'd like to ask about divination."] = "Me gustaría preguntar sobre la adivinación.",
    ["Can you tell me about that cape?"] = "¿Puedes hablarme de esa capa?",
    ["Beautiful, isn't it? We're reserving it for true masters of divination, who may wear it as a sign of their accomplishment."] = "Precioso, ¿no? Lo reservamos para verdaderos maestros de la adivinación, quienes podrán usarlo como señal de su logro.",
    ["Can you help me with the divination outfits?"] = "¿Puedes ayudarme con los trajes de adivinación?",
    ["At level 70 you can start to collect fragments to make elite skilling outfits. When you get to that level you will automatically start collecting fragments. Then you can use them with a blueprint to make yourself any remaining elite outfit pieces for this skill."] = "En el nivel 70 puedes comenzar a recolectar fragmentos para crear trajes de habilidades de élite. Cuando llegues a ese nivel, automáticamente comenzarás a recolectar fragmentos. Luego puedes usarlos con un plano para hacerte las piezas restantes del atuendo de élite para esta habilidad.",
    ["You are set up to receive fragments. When you get to level 80 you will be able to create outfit pieces."] = "Estás configurado para recibir fragmentos. Cuando llegues al nivel 80 podrás crear prendas de vestir.",
    ["You are set up to receive fragments. When you have 3600 fragments you can use them to create an elite outfit piece. Simply go to an Invention workbench to create the pieces."] = "Estás configurado para recibir fragmentos. Cuando tengas 3600 fragmentos, podrás usarlos para crear una pieza de atuendo de élite. Simplemente acude a un banco de trabajo Invention para crear las piezas.",
    ["You have already created all of the possible outfit pieces. I will make sure you do not receive any further fragments."] = "Ya has creado todas las prendas posibles. Me aseguraré de que no reciba más fragmentos.",
    ["Remember you can combine the base outfit pieces to make the high tier versions, to get the additional benefits."] = "Recuerda que puedes combinar las piezas del atuendo básico para crear las versiones de nivel alto y obtener beneficios adicionales.",
    ["Can you sell me a Divination skillcape?"] = "¿Puedes venderme un Divination skillcape?",
    ["I don't do this for anyone, but I've got a special offer today! Normally I require 99,000 coins for this prestigious item, but for you it's half price. Only 92,000 coins!"] = "No hago esto por nadie, ¡pero hoy tengo una oferta especial! Normalmente necesito 99.000 coins por este prestigioso artículo, pero para ti es la mitad de precio. ¡Solo 92.000 coins!",
    ["92,000 coins? That's much too expensive."] = "¿92.000 coins? Eso es demasiado caro.",
    ["I know where to find you if I change my mind."] = "Sé dónde encontrarte si cambio de opinión.",
    ["I think I have the money right here, actually."] = "De hecho, creo que tengo el dinero aquí.",
    ["Unfortunately all skillcapes are only available with a free hood, it's part of a skill promotion deal; buy one get one free, you know. So, you'll need to free up some backpack space before I can sell you one."] = "Lamentablemente, todos los skillcapes solo están disponibles con una capucha gratuita, es parte de un acuerdo de promoción de habilidades; Compra uno y llévate otro gratis, ya sabes. Por lo tanto, necesitarás liberar algo de espacio en backpack antes de que pueda venderte uno.",
    ["But unfortunately, I was mistaken."] = "Pero desafortunadamente me equivoqué.",
    ["Well, come back and see me when you do."] = "Bueno, vuelve a verme cuando lo hagas.",
    ["Excellent! Wear that cape with pride my friend."] = "¡Excelente! Lleva esa capa con orgullo, amigo mío.",
    ["I've mastered this skill. Is there anything else?"] = "He dominado esta habilidad. ¿Hay algo más?",
    ["There is something...though I have kept it a secret for a very long time. It is something that can only be worn by a true master."] = "Hay algo... aunque lo he mantenido en secreto durante mucho tiempo. Es algo que sólo puede ser usado por un verdadero maestro.",
    ["Not even I can wear it - that's how hard it is to achieve."] = "Ni siquiera yo puedo usarlo, así de difícil es lograrlo.",
    ["You say you're a master. Stand straight, let me take a look at you..."] = "Dices que eres un maestro. Ponte derecho, déjame echarte un vistazo...",
    ["You...really have mastered it. What an honour! It would be my pleasure to sell you a Divination master cape."] = "Tú... realmente lo dominas. ¡Qué honor! Sería un placer venderle un Divination master cape.",
    ["Buy Divination master cape for 120,000 coins?"] = "¿Comprar Divination master cape por 120.000 coins?",
    ["You do not have enough room in your backpack. Please come back when you have some more."] = "No tienes suficiente espacio en tu backpack. Por favor regresa cuando tengas más.",
    ["You do not have enough money to purchase this cape."] = "No tienes suficiente dinero para comprar esta capa.",
    ["Of course. It is a very prestigious item, however, so it does come with a hefty price tag. The skillcape costs 99,000 gold."] = "Por supuesto. Sin embargo, es un artículo muy prestigioso, por lo que tiene un precio elevado. El skillcape cuesta 99.000 de oro.",
    ["99,000 coins? That's much too expensive."] = "¿99.000 coins? Eso es demasiado caro.",
    ["I've noticed there are a couple of versions of each skillcape."] = "He notado que hay un par de versiones de cada skillcape.",
    ["Yes! We, the skill masters, have crafted new versions of all skillcapes! We felt like it was time for a change."] = "¡Sí! ¡Nosotros, los maestros de habilidades, hemos creado nuevas versiones de todos los skillcapes! Sentimos que era hora de un cambio.",
    ["It looks like you're currently using the old model for your Divination skillcape. Would you like to change to the newer one?"] = "Parece que actualmente estás usando el modelo anterior para tu Divination skillcape. ¿Quieres cambiar a uno más nuevo?",
    ["You can still choose to wear the old model skillcape if you want. Would you like to change which model you are currently using?"] = "Aún puedes elegir usar el modelo antiguo skillcape si lo deseas. ¿Le gustaría cambiar el modelo que está utilizando actualmente?",
    ["Yes, I would like to wear the [new/old] version of the skillcape."] = "Sí, me gustaría usar la versión [new/old] del skillcape.",
    ["Would you like to wear the [old/newer] model for just this cape, or for the Quest Cape and all of the skillcapes you own?"] = "¿Te gustaría usar el modelo [old/newer] solo para esta capa, o para el Quest Cape y todos los skillcapes que tienes?",
    ["I would just like to change the Divination skillcape."] = "Solo me gustaría cambiar el Divination skillcape.",
    ["No problem, you will now use the [older/newer] model for your Divination skillcape."] = "No hay problema, ahora utilizarás el modelo [older/newer] para tu Divination skillcape.",
    ["I would like to change all my skillcapes."] = "Me gustaría cambiar todos mis skillcapes.",
    ["No problem, you will now use the [older/newer] model for all of your skillcapes!"] = "¡No hay problema, ahora usarás el modelo [older/newer] para todos tus skillcapes!",
    ["I've changed my mind!"] = "¡He cambiado de opinión!",
    ["Great! I'm glad you're still enjoying the [old/new] version!"] = "¡Genial! ¡Me alegra que sigas disfrutando de la versión [old/new]!",
    ["If you want, I can make it so you use the old model for all of the skillcapes you own."] = "Si quieres, puedo hacerlo para que uses el modelo antiguo para todos los skillcapes que tengas.",
    ["Ok, I'd like to wear the old version for all my skillcapes."] = "Ok, me gustaría usar la versión antigua para todos mis skillcapes.",
    ["Great, you will now use the old model for all of your skillcapes!"] = "¡Genial, ahora usarás el modelo antiguo para todos tus skillcapes!",
    ["This is a fragment of a chronicle. You should speak to May about these."] = "Este es un fragmento de una crónica. Deberías hablar con May sobre esto.",
    ["This is divine energy. It can be used to produce useful objects and effects."] = "Esta es energía divina. Se puede utilizar para producir objetos y efectos útiles.",
    ["Ah, that's a memory. You should take it to a crater and convert it into either experience or energy."] = "Ah, eso es un recuerdo. Deberías llevarlo a un cráter y convertirlo en experiencia o energía.",
    ["Ah, the memories..."] = "Ah, los recuerdos...",
    ["And the energies, chronicles and wisps..."] = "Y las energías, crónicas y briznas...",
    ["Very droll."] = "Muy gracioso.",
    ["But you are right, we should not dwell on the past so much."] = "Pero tienes razón, no deberíamos insistir tanto en el pasado.",
    ["Perhaps you are here for me to divine your future..."] = "Quizás estés aquí para que yo adivine tu futuro...",
    ["Well, seeing as I'm here."] = "Bueno, ya que estoy aquí.",
    ["Hmm, let me see... You will stand tall and fight back against powerful gods, yet end up triumphant!"] = "Hmm, déjame ver... ¡Te mantendrás erguido y lucharás contra dioses poderosos, pero terminarás triunfante!",
    ["Um, all of that is in the past."] = "Um, todo eso quedó en el pasado.",
    ["Hmm, let me see... You will complete a series of seemingly random, nostalgic tasks in exchange for a shiny reward!"] = "Hmm, déjame ver... ¡Completarás una serie de tareas nostálgicas y aparentemente aleatorias a cambio de una brillante recompensa!",
    ["Sorry, no, that's the present."] = "Lo siento, no, ese es el presente.",
    ["Hmm, let me see... You will get an elbow in the ribs from an irate diviner."] = "Hmm, déjame ver... Recibirás un codazo en las costillas de un adivino furioso.",
    ["By Guthix, to Orla!"] = "¡Por Guthix, por Orla!",
    ["Show Orla Fairweather a Divination memory."] = "Mostrar Orla Fairweather una memoria Divination.",
    ["Ah, no! Please, spare me from my terrible fate!"] = "¡Ah, no! ¡Por favor, líbrame de mi terrible destino!",
    ["Looks like I've completed everything. I'd better go and see Hans about that reward!"] = "Parece que he completado todo. ¡Será mejor que vaya a ver a Hans sobre esa recompensa!",
    ["Can you remember now too? I had forgotten. We had all forgotten. Now I know we have to go! The Memorial to Guthix has been waiting for us to remember. Shall we go together?"] = "¿Puedes recordarlo ahora también? Lo había olvidado. Todos lo habíamos olvidado. ¡Ahora sé que tenemos que irnos! El Memorial a Guthix nos estaba esperando para recordarlo. ¿Vamos juntos?",
    ["Teleport to the Memorial to Guthix?"] = "¿Teletransportarse al Memorial a Guthix?",
    ["It's been here for years, my dear. I knew of it, I've read of it, but we could never see it. It was kept hidden from view for reasons I know not."] = "Ha estado aquí durante años, querida. Lo sabía, lo he leído, pero nunca pudimos verlo. Se mantuvo oculto a la vista por razones que desconozco.",
    ["Ever since Guthix left this world, I've been gaining an ever-increasing sense of this place's existence."] = "Desde que Guthix dejó este mundo, he ido adquiriendo una sensación cada vez mayor de la existencia de este lugar.",
    ["Tiny strands of Guthixian memories have started appearing near Divination craters."] = "Pequeñas hebras de recuerdos Guthixianos han comenzado a aparecer cerca de los cráteres Divination.",
    ["It seems like they were hidden from view until now."] = "Parece que estuvieron ocultos a la vista hasta ahora.",
    ["I'll try to explain what I've been researching since I've been here. It's all coming back to me slowly."] = "Intentaré explicar lo que he estado investigando desde que estoy aquí. Todo está regresando a mí lentamente.",
    ["It all starts with engrams. Engrams are permanent markers left on the timeline."] = "Todo comienza con engramas. Los engramas son marcadores permanentes que se dejan en la línea de tiempo.",
    ["They're caused by the significant activities of living things and can only be spotted by those who have an adept understanding of Divination."] = "Son causados por actividades importantes de los seres vivos y solo pueden ser detectados por aquellos que tienen un conocimiento experto de Divination.",
    ["It is possible to charge these engrams by infusing them with divine energy and memory strands."] = "Es posible cargar estos engramas infundiéndoles energía divina y hebras de memoria.",
    ["What does that do to them?"] = "¿Qué les hace eso?",
    ["Oh, it's a theatre of light and magic, my dear. The engrams hold an echo of history."] = "Oh, es un teatro de luz y magia, querida. Los engramas contienen un eco de la historia.",
    ["These 'echoes' all belong to Guthix, right? Engrams, memory strands, divine energy...they're all part of Guthix's residual life-force."] = "Todos estos 'ecos' pertenecen a Guthix, ¿verdad? Engramas, hilos de memoria, energía divina... todos son parte de la fuerza vital residual de Guthix.",
    ["How very astute. I suppose I should expect nothing less from you."] = "Qué astuto. Supongo que no debería esperar menos de ti.",
    ["I have only ever charged a couple of weak engrams, but they were both from the viewpoints of Guthix himself. We can assume that the rest are almost certainly related to Guthix as well."] = "Solo he cargado un par de engramas débiles, pero ambos eran desde el punto de vista del propio Guthix. Podemos suponer que es casi seguro que el resto también esté relacionado con Guthix.",
    ["There could be so much valuable information stored in these engrams. How do we find them?"] = "Podría haber mucha información valiosa almacenada en estos engramas. ¿Cómo los encontramos?",
    ["In the centre of this concourse behind me, you'll see a pool brimming with energy. You'll probably sense it before you see it. It gives off such a glorious aura."] = "En el centro de este vestíbulo, detrás de mí, verás una piscina rebosante de energía. Probablemente lo sientas antes de verlo. Emite un aura tan gloriosa.",
    ["All of the plinths inside the building are somehow connected to this pool."] = "Todos los zócalos dentro del edificio están conectados de alguna manera a esta piscina.",
    ["Once charged, I could display the echoes found inside the engrams there, just like statues of raw life; animated echoes of reality."] = "Una vez cargado, pude mostrar los ecos que se encuentran dentro de los engramas allí, como estatuas de vida cruda; ecos animados de la realidad.",
    ["If you tinker with the plinths, you may be able to discover a vague idea of locations of other engrams. I can't promise that they will be easy to detect, though."] = "Si juegas con los pedestales, es posible que puedas descubrir una vaga idea de la ubicación de otros engramas. Sin embargo, no puedo prometer que serán fáciles de detectar.",
    ["So once I've found an engram, I can charge it by filling it with divine energy and these memory strands?"] = "Entonces, una vez que encuentro un engrama, ¿puedo cargarlo llenándolo con energía divina y estos hilos de memoria?",
    ["Yes, and then bring it to me. I can get the pool of energy to absorb any charged engrams that you bring here. After that, you should be free to interact with the echoes as you see fit."] = "Sí, y luego tráemelo. Puedo hacer que la reserva de energía absorba cualquier engrama cargado que traigas aquí. Después de eso, deberías poder interactuar con los ecos como mejor te parezca.",
    ["This seems simple enough, but let me quickly recap."] = "Esto parece bastante simple, pero permítanme resumirlo rápidamente.",
    ["I need to use the plinths to get hints about where to find the engrams, then charge these engrams with memory strands and divine energy, and then give them to you to add to the pool here?"] = "¿Necesito usar los pedestales para obtener pistas sobre dónde encontrar los engramas, luego cargar estos engramas con hilos de memoria y energía divina, y luego dártelos para que los agregues al grupo aquí?",
    ["Yep, it seems that you've got it."] = "Sí, parece que lo tienes.",
    ["Oh, one more thing!"] = "¡Oh, una cosa más!",
    ["Hmm?"] = "¿Mmm?",
    ["The pool of energy. Once I had charged some engrams, I noticed that I felt a stronger connection to this place."] = "El charco de energía. Una vez que cargué algunos engramas, noté que sentía una conexión más fuerte con este lugar.",
    ["Perhaps we can focus the energy in this place to help you with your Divination skill? Just a hunch, of course."] = "¿Quizás podamos concentrar la energía en este lugar para ayudarte con tu habilidad Divination? Sólo una corazonada, por supuesto.",
    ["Sounds interesting. I'll investigate."] = "Suena interesante. Voy a investigar.",
    ["Fantastic. Please take one of the engrams that I found, to get yourself started and to gain a feel for them."] = "Fantástico. Por favor, tome uno de los engramas que encontré para comenzar y familiarizarse con ellos.",
    ["Tutorial stage 1/6 complete."] = "Etapa tutorial 1/6 completa.",
    ["It appears you are too burdened to carry the engram and memory strands. Come back when you have more space."] = "Parece que estás demasiado agobiado para llevar los hilos del engrama y la memoria. Vuelve cuando tengas más espacio.",
    ["Try not to lose it!"] = "¡Intenta no perderlo!",
    ["See if you can attune the engram that I gave you. It needs to be jump started with some divine energy."] = "Mira si puedes sintonizar el engrama que te di. Es necesario ponerlo en marcha con algo de energía divina.",
    ["[Orla can only do that for you once you have prestiged at least once.]"] = "[Orla sólo puede hacer eso por ti una vez que hayas obtenido prestigio al menos una vez.]",
    ["Oh dear, have you lost touch with the engram I gave you?"] = "Dios mío, ¿has perdido contacto con el engrama que te di?",
    ["Here, let's try again. Take this engram."] = "Vamos, intentémoslo de nuevo. Toma este engrama.",
    ["There's a strange energy emanating from that pool. I've tried to enter the pool but nothing happens for myself."] = "Hay una energía extraña que emana de esa piscina. Intenté entrar a la piscina pero no me pasa nada.",
    ["You need Divination level 70 to enter the Hall of Memories."] = "Necesitas el nivel 70 de Divination para ingresar al Salón de los Recuerdos.",
    ["I've charged this engram with divine energy and some memory strands. Could you please take a look at it?"] = "He cargado este engrama con energía divina y algunos hilos de memoria. ¿Podrías echarle un vistazo?",
    ["This is perfect! I can feel the energies of the past radiating from this engram."] = "¡Esto es perfecto! Puedo sentir las energías del pasado irradiando desde este engrama.",
    ["Tutorial stage 2/6 complete."] = "Etapa tutorial 2/6 completa.",
    ["I will add the echo to the pool and harness its power for you. For free, of course, though I wouldn't mind a pat on the back every now and then."] = "Agregaré el eco a la piscina y aprovecharé su poder para ti. Gratis, por supuesto, aunque no me importaría una palmadita en la espalda de vez en cuando.",
    ["I've added the charged engram you gave me to the pool of energy. You should assign that echo to one of the plinths surrounding the pool."] = "Agregué el engrama cargado que me diste al conjunto de energía. Debes asignar ese eco a uno de los zócalos que rodean la piscina.",
    ["Tutorial stage 3/6 complete."] = "Etapa tutorial 3/6 completa.",
    ["That echo, my dear: is that a naragi?"] = "Ese eco, querida: ¿es un naragi?",
    ["I've only read descriptions, but it makes sense. I wonder what we can learn from it?"] = "Solo he leído descripciones, pero tiene sentido. Me pregunto qué podemos aprender de ello.",
    ["Talk to the echo."] = "Habla con el eco.",
    ["The nature of things is a perfect cycle, from one state to another, and a return to prior existence."] = "La naturaleza de las cosas es un ciclo perfecto, de un estado a otro, y un retorno a la existencia anterior.",
    ["Things that once existed, yet now are lost, may yet return and in improved form."] = "Las cosas que alguna vez existieron, pero que ahora están perdidas, aún pueden regresar y en forma mejorada.",
    ["That which is no more shall return again, renewed with more vigour and power than before."] = "Lo que ya no existe volverá de nuevo, renovado con más vigor y poder que antes.",
    ["Those who remember the past will see the truth in my words."] = "Aquellos que recuerden el pasado verán la verdad en mis palabras.",
    ["Of future events, I see most clear, yet things that must be, must be."] = "De los eventos futuros, los veo más claros, sin embargo, las cosas que deben ser, deben ser.",
    ["I could change them if I so desired, but I do not, for all things must happen as they run their course."] = "Podría cambiarlos si así lo deseara, pero no lo hago, ya que todas las cosas deben suceder a medida que siguen su curso.",
    ["Tutorial stage 4/6 complete."] = "Etapa tutorial 4/6 completa.",
    ["Recolour this echo."] = "Vuelve a colorear este eco.",
    ["Clear this plinth."] = "Limpia este pedestal.",
    ["Knowledge is power. That metaphor has an almost tangible weight in times like these. We exist merrily beside beings capable of smiting us with an utterance."] = "El conocimiento es poder. Esa metáfora tiene un peso casi tangible en tiempos como estos. Existimos alegremente al lado de seres capaces de golpearnos con una palabra.",
    ["Some days I stand and bask in the serenity of this world, yet on others I feel like a helpless observer in a world where tyrannical children run amok."] = "Algunos días me quedo y disfruto de la serenidad de este mundo, pero otros me siento como un observador indefenso en un mundo donde los niños tiránicos se vuelven locos.",
    ["The chance for even a miniscule rebalance is not to be scoffed at, should the opportunity present itself, my dear. Let us tinker with the powers here and see what arises."] = "No hay que desdeñar la posibilidad de que se produzca incluso un reequilibrio minúsculo, si se presenta la oportunidad, querida. Juguemos con los poderes aquí y veamos qué surge.",
    ["What is it that you're asking me to do?"] = "¿Qué es lo que me estás pidiendo que haga?",
    ["Sorry, I sometimes go off on a tangent."] = "Lo siento, a veces me salgo por la tangente.",
    ["The butterfly statue at the edge of the energy pool controls the flow of energy here. You should be able to power up your Divination skill by tinkering with it. Let me know if it works."] = "La estatua de la mariposa en el borde del estanque de energía controla el flujo de energía aquí. Deberías poder potenciar tu habilidad Divination jugando con ella. Déjame saber si funciona.",
    ["Tutorial stage 5/6 complete."] = "Etapa tutorial 5/6 completa.",
    ["Did you manage to power up your Divination abilities in any way?"] = "¿Conseguiste potenciar tus habilidades Divination de alguna manera?",
    ["I picked an effect and locked the energy to it. It seems like there are more options for me there, but I couldn't quite access them."] = "Elegí un efecto y le fijé la energía. Parece que hay más opciones para mí allí, pero no pude acceder a ellas.",
    ["Oh, I knew you could do it! I couldn't manage it myself, but I knew there was something to that statue as soon as I found this place."] = "¡Oh, sabía que podías hacerlo! No pude lograrlo yo mismo, pero supe que había algo en esa estatua tan pronto como encontré este lugar.",
    ["For allowing me to learn from you, I will allow you to learn from me in return!"] = "¡Por permitirme aprender de ti, te permitiré a ti aprender de mí a cambio!",
    ["There's now almost no limit to the number of chronicles you can carry, and they should also be a bit easier to find."] = "Ahora casi no hay límite para la cantidad de crónicas que puedes llevar, y también deberían ser un poco más fáciles de encontrar.",
    ["Tutorial stage 6/6 complete."] = "Etapa tutorial 6/6 completa.",
    ["That's very kind of you. Thanks!"] = "Muy amable de tu parte. ¡Gracias!",
    ["Talk to Orla"] = "hablar con orla",
    ["Have you got anything else for me?"] = "¿Tienes algo más para mí?",
    ["*(With not enough engrams:)*"] = "*(Sin suficientes engramas :)*",
    ["You haven't attuned enough engrams for your reward!"] = "¡No has sintonizado suficientes engramas para tu recompensa!",
    ["*(With enough engrams:)*"] = "*(Con suficientes engramas :)*",
    ["*(Without having claimed the strands:)*"] = "*(Sin haber reclamado las hebras:)*",
    ["Take my collection of memory strands. You succeeded, my dear, while I couldn't quite crack it, so it makes sense."] = "Toma mi colección de recuerdos. Lo lograste, querida, aunque yo no pude descifrarlo del todo, así que tiene sentido.",
    ["Orla has given you [amount] memory strands."] = "Orla te ha dado hilos de memoria [amount].",
    ["When I added that charged engram to the pool of energy, everything felt... finished? Is that the right word? I get the sense that there are a set of echoes and we seem to have collected them all."] = "Cuando agregué ese engrama cargado al conjunto de energía, todo se sintió... ¿terminado? ¿Es esa la palabra correcta? Tengo la sensación de que hay una serie de ecos y parece que los hemos recogido todos.",
    ["*(Having claimed the strands:)*"] = "*(Habiendo reclamado los hilos:)*",
    ["Nothing right now - you can get a feel for the locations of engrams by interacting with the plinths."] = "Nada en este momento: puedes tener una idea de la ubicación de los engramas interactuando con los pedestales.",
    ["Can you tell me about these butterflies?"] = "¿Puedes hablarme de estas mariposas?",
    ["They seem to be made of dispersed magical energy - from Guthix himself."] = "Parecen estar hechos de energía mágica dispersa, del propio Guthix.",
    ["It seems safe to collect them. In keeping with Guthix's teachings of balance, it will be in one of the areas of knowledge or skill where you are most inexperienced."] = "Parece seguro recogerlos. Siguiendo las enseñanzas del equilibrio de Guthix, será en una de las áreas de conocimiento o habilidad en las que tengas más inexperiencia.",
    ["What if I don't want to receive experience for catching butterflies?"] = "¿Qué pasa si no quiero recibir experiencia por atrapar mariposas?",
    ["Well, I... I suppose I could help you. Do you really want to stop gaining experience for catching butterflies?"] = "Bueno, yo... Supongo que podría ayudarte. ¿De verdad quieres dejar de adquirir experiencia cazando mariposas?",
    ["Block XP from butterflies"] = "Bloquea XP de las mariposas",
    ["You will no longer gain any more experience from catching Guthixian butterflies. Ask me about butterflies again if you change your mind!"] = "Ya no obtendrás más experiencia atrapando mariposas Guthixianas. ¡Pregúntame sobre mariposas otra vez si cambias de opinión!",
    ["Gain XP from butterflies"] = "Gana XP de las mariposas",
    ["You will now get experience from catching Guthixian butterflies. Ask me about butterflies again if you change your mind!"] = "Ahora obtendrás experiencia capturando mariposas Guthixianas. ¡Pregúntame sobre mariposas otra vez si cambias de opinión!",
    ["Nevermind."] = "No importa.",
    ["You can get a feel for the locations of engrams by interacting with the plinths."] = "Puedes tener una idea de la ubicación de los engramas interactuando con los pedestales.",
    ["That wasn't the only charged engram I have."] = "Ese no fue el único engrama cargado que tengo.",
    ["Oh? Someone has been busy. Your reputation for getting things done is clearly not unfounded. I'll take any more you have and add them to the pool."] = "¿Ah? Alguien ha estado ocupado. Está claro que su reputación de hacer las cosas no es infundada. Tomaré las que tenga más y las agregaré al grupo.",
    ["Hang on a minute!"] = "¡Espera un momento!",
    ["Alright, mate? Exciting stuff, let me tell you!"] = "¿Está bien, amigo? ¡Cosas emocionantes, déjame decirte!",
    ["Well, actually, I can't tell you. Not yet, anyway."] = "Bueno, en realidad, no te lo puedo decir. Al menos todavía no.",
    ["Why not?"] = "¿Por qué no?",
    ["Gotta be sure first, mate! Can't go making wild statements about world-changing discoveries without any basis."] = "¡Primero debes estar seguro, amigo! No podemos hacer declaraciones descabelladas sobre descubrimientos que cambiarán el mundo sin ningún fundamento.",
    ["Can't you even give me a hint?"] = "¿Ni siquiera puedes darme una pista?",
    ["Hmm... Well, alright - but only because I'm so excited about it m'self."] = "Hmm... Bueno, está bien, pero sólo porque yo también estoy muy emocionado.",
    ["I believe, this could be...the ancient, original dwelling of Guthix. Where he used to actually live!"] = "Creo que esta podría ser... la antigua y original morada de Guthix. ¡Donde solía vivir!",
    ["Course, I can't be sure until I get in there and 'have a look."] = "Por supuesto, no puedo estar seguro hasta que entre y eche un vistazo.",
    ["Can I help at all?"] = "¿Puedo ayudar en algo?",
    ["Tell ya what: come back in a while and I'm sure I could use an 'and."] = "Te diré una cosa: vuelve dentro de un rato y estoy seguro de que me vendría bien un 'y'.",
    ["I look forward to it!"] = "¡Lo espero con ansias!",
    ["Who's Guthix?"] = "¿Quién es Guthix?",
    ["Guthix is one of the gods! Some say the most powerful god of them all."] = "¡Guthix es uno de los dioses! Algunos dicen que es el dios más poderoso de todos.",
    ["It's believed 'e was the first god to come to Gielinor, shapin' it in 'is vision. He brought us humans in, among others."] = "Se cree que fue el primer dios que vino a Gielinor y le dio forma en su visión. Él nos trajo a los humanos, entre otros.",
    ["Belief 'as it that Guthix lives off balance; he thrives from us livin' in harmony. So, back in the Third Age, when the other gods came along and started fightin'...well...Guthix just up and banished 'em all!"] = "Creencia de que Guthix vive desequilibrado; Él prospera gracias a que vivimos en armonía. Entonces, allá en la Tercera Edad, cuando los otros dioses aparecieron y comenzaron a pelear... bueno... ¡Guthix simplemente se levantó y los desterró a todos!",
    ["Course, it could all be legend, but it's fascinating stuff for a historian."] = "Por supuesto, todo podría ser una leyenda, pero es algo fascinante para un historiador.",
    ["That sounds exciting! Can I help at all?"] = "¡Eso suena emocionante! ¿Puedo ayudar en algo?",
    ["Thanks for all your help, mate. Hope you enjoy the museum!"] = "Gracias por toda tu ayuda, amigo. ¡Espero que disfrutes del museo!",
    ["Hello, can I help?"] = "Hola, ¿puedo ayudar?",
    ["Yes please. What are you selling?"] = "Sí por favor. ¿Qué estás vendiendo?",
    ["Hello there. Could I ask you about the-"] = "Hola. ¿Puedo preguntarte sobre-?",
    ["Not at the moment, [dude/dudette]! It's not nearly safe enough to talk right now."] = "¡Por el momento no, [dude/dudette]! No es lo suficientemente seguro hablar ahora.",
    ["But you don't even know what I was going to ask!"] = "¡Pero ni siquiera sabes lo que iba a preguntar!",
    ["Oh, I have enough of an idea to know that it's not safe enough to talk about it on a free world."] = "Oh, tengo una idea suficiente para saber que no es lo suficientemente seguro hablar de ello en un mundo libre.",
    ["Hi there! What are you up to today?"] = "¡Hola! ¿Qué estás haciendo hoy?",
    ["Man, I'd just be chillin', takin' it easy, like, but there's so much to do."] = "Hombre, simplemente me relajaría y me lo tomaría con calma, pero hay mucho que hacer.",
    ["Oh? Like what?"] = "¿Ah? ¿Cómo qué?",
    ["Sorry, [dude/dudette], I know it's a total bummer, but I've got to focus right now. Catch ya later, yeah?"] = "Lo siento, [dude/dudette], sé que es un fastidio total, pero tengo que concentrarme ahora mismo. Nos vemos luego, ¿sí?",
    ["Oh, sure. Good luck with everything."] = "Oh, claro. Buena suerte con todo.",
    ["Hi, there. I was wondering if you could help me ou-"] = "Hola. Me preguntaba si podrías ayudarme.",
    ["Like, I can't possibly tune in to your wavelength right now, man! I'm way too angstin'."] = "¡No puedo sintonizar tu longitud de onda ahora mismo, hombre! Estoy demasiado angustiado.",
    ["It's my friend, , in the Jolly Boar, like. He's really ailin', and I'm stuck watchin' this beacon so I can't help out."] = "Es mi amigo, en el Jolly Boar, como. Está realmente enfermo y yo estoy atrapado mirando esta baliza, así que no puedo ayudarlo.",
    ["I'm sorry to hear that. If it hel-"] = "Lamento oír eso. Si ayuda-",
    ["Look, just don't even talk to me, okay? I need some head space, like. 's my best friend, man."] = "Mira, ni siquiera me hables, ¿vale? Necesito algo de espacio para la cabeza, como. Es mi mejor amigo, hombre.",
    ["[Family Crest] quest.}}"] = "Misión [Family Crest].}}",
    ["Hey, [dude/dudette]. What's up?"] = "Hola, [dude/dudette]. ¿Qué pasa?",
    ["Could you look after this beacon for me?"] = "¿Podrías cuidar esta baliza por mí?",
    ["Of course. Once the beacon is lit, just leave 5 logs with me and I'll take care of the fire for as long as I can."] = "Por supuesto. Una vez que la baliza esté encendida, déjame 5 logs y yo me ocuparé del fuego todo el tiempo que pueda.",
    ["Well, I could, but since you're here, you might as well do it yourself."] = "Bueno, podría, pero ya que estás aquí, es mejor que lo hagas tú mismo.",
    ["You must give the fire tender five of the same type of log for the beacon."] = "Debes darle al bombero cinco troncos del mismo tipo para la baliza.",
    ["Fraid you don't have enough of the right type of log for me to use."] = "Me temo que no tienes suficiente registro del tipo correcto para que yo lo use.",
    ["[Dude/dudette], I'll need, like, five logs to tend the fire for you. Is that cool?"] = "[Dude/dudette], necesitaré como cinco logs para cuidar el fuego por ti. ¿Eso es genial?",
    ["Do you want to give five logs to the fire tender?"] = "¿Quieres darle cinco logs al fuego?",
    ["Here are five logs for you."] = "Aquí tienes cinco logs para ti.",
    ["Ace! I'll use these five logs to keep the beacon burning while you're away."] = "¡As! Usaré estos cinco logs para mantener encendida la baliza mientras estás fuera.",
    ["I think I'll keep hold of my logs for now."] = "Creo que conservaré mi logs por ahora.",
    ["Well, you know where I am if you change your mind, yeah?"] = "Bueno, sabes dónde estoy si cambias de opinión, ¿no?",
    ["Yes. Please don't ask me for confirmation in future."] = "Sí. Por favor, no me pidas confirmación en el futuro.",
    ["Of course [dude/dudette]; no worries. I'll use the logs you've already left with me."] = "Por supuesto [dude/dudette]; no hay problema. Usaré el logs que ya me dejaste.",
    ["Can you tell me about other beacons?"] = "¿Puedes hablarme de otras balizas?",
    ["Sure thing, [dude/dudette]! Just point your peepers at this awesome map of mine."] = "¡Claro, [dude/dudette]! Simplemente apunten sus mirones a este increíble mapa mío.",
    ["Is it possible to get information about beacons that are further away?"] = "¿Es posible obtener información sobre balizas que están más alejadas?",
    ["My eyes are pretty awesome - I can tell you all about the beacons in either direction, like, as long as the fires are lit."] = "Mis ojos son impresionantes. Puedo contarte todo sobre las balizas en cualquier dirección, siempre y cuando los fuegos estén encendidos.",
    ["To tell you about the other ones, I'd need the help of a macaw, like."] = "Para contarte sobre los otros, necesitaría la ayuda de una guacamaya, como.",
    ["A macaw?"] = "¿Una guacamaya?",
    ["Yeah. Macaws can fly high into the air and see things that are much further away, like."] = "Sí. Las guacamayas pueden volar muy alto en el aire y ver cosas que están mucho más lejos, como.",
    ["They are also highly intelligent and can be trained up to, like, to return with the exact information I'd need to tell you everything about the beacon network."] = "También son muy inteligentes y se les puede entrenar para que regresen con la información exacta que necesitaría para contarles todo sobre la red de balizas.",
    ["Come to think of it, the macaw you've got there in your pack would be perfect, like."] = "Ahora que lo pienso, la guacamaya que tienes en tu mochila sería perfecta.",
    ["Man, I'd just be chillin', takin' it easy, like, but there's so much to do!"] = "Hombre, me relajaría y me lo tomaría con calma, ¡pero hay mucho que hacer!",
    ["Well, there's these beacons, man. They need lookin' after."] = "Bueno, están estas balizas, hombre. Necesitan que los cuiden.",
    ["Isn't it exhausting, constantly keeping your eyes peeled like that?"] = "¿No es agotador tener los ojos bien abiertos constantemente?",
    ["Well, actually, staring intently at anything for too long can be a strain on one's eyes."] = "Bueno, en realidad, mirar fijamente algo durante demasiado tiempo puede resultar agotador para la vista.",
    ["And when I'm not doin' that, I need to keep the peepers glued to the horizon, constantly watching for signs of trouble."] = "Y cuando no estoy haciendo eso, necesito mantener a los mirones pegados al horizonte, atentos constantemente a señales de problemas.",
    ["That does sound like a lot of work!"] = "¡Eso parece mucho trabajo!",
    ["Totally, like. Can't wait to meet up with Jonathan later at the Jolly Boar - I'm *parched*!"] = "Totalmente, como. No puedo esperar para encontrarme con Jonathan más tarde en el Jolly Boar. ¡Estoy *seco*!",
    ["I'm done talking to you, now!"] = "¡Ya terminé de hablar contigo!",
    ["Harsh, [dude/dudette]!"] = "¡Duro, [dude/dudette]!",
    ["Do you want to give the fire tender your macaw?"] = "¿Quieres darle al fuego tierno tu guacamayo?",
    ["Thank you very much. This macaw will help me give you more detailed information about the beacon network."] = "Muchas gracias. Esta guacamaya me ayudará a brindarles información más detallada sobre la red de balizas.",
    ["I think I'll keep my macaw for now."] = "Creo que me quedaré con mi guacamaya por ahora.",
    ["I've already given him a macaw; he doesn't need another."] = "Ya le regalé una guacamaya; él no necesita otro.",
    ["There's no fire here for the fire tender to tend."] = "Aquí no hay fuego para que lo atienda el bombero.",
    ["Since I'm here and the beacon's fire is dying down, I might as well tend the fire myself."] = "Ya que estoy aquí y el fuego de la baliza se está apagando, también podría cuidarlo yo mismo.",
    ["The fire tender needs five of the same type of log to maintain this fire."] = "El bombero necesita cinco troncos del mismo tipo para mantener este fuego.",
    ["You give the fire tender 5 [type] logs."] = "Le das al fuego tierno 5 [type] logs.",
    ["I think I'll hang on to my logs after all."] = "Creo que, después de todo, me quedaré con mi logs.",
    ["Yes. Please don't ask me for confirmation again."] = "Sí. Por favor, no vuelvas a pedirme confirmación.",
    ["You've already left logs with this fire tender."] = "Ya saliste de logs con este ténder de fuego.",
    ["Oi! Get away from that! Until you've proven yourself a true ally of Varrock, you can't use that!"] = "¡Oye! ¡Aléjate de eso! Hasta que no hayas demostrado que eres un verdadero aliado de Varrock, ¡no podrás usar eso!",
    ["You need to claim the reward for the elite set Tasks in Varrock to use this chest."] = "Debes reclamar la recompensa por las tareas del conjunto de élite en Varrock para usar este cofre.",
    ["I'd like to talk about Sq'irks"] = "Me gustaría hablar sobre Sq'irks.",
    ["Where do I get sq'irks?"] = "¿Dónde consigo sq'irks?",
    ["There is a sorceress near the south-eastern edge of Al Kharid who grows them. She used to be friends with Osman, but they fell out."] = "Hay una hechicera cerca del borde sureste de Al Kharid que los cultiva. Solía ​​ser amiga de Osman, pero se pelearon.",
    ["I don't know. It's impossible to get any information out of Osman. Anyway, now she won't give us any more fruit."] = "No lo sé. Es imposible obtener información de Osman. De todos modos, ahora ya no nos dará más frutos.",
    ["So all I have to do is ask her for some fruit for you?"] = "¿Entonces todo lo que tengo que hacer es pedirle algo de fruta?",
    ["I doubt it will be that easy. She is not renowned for her generosity and is very secretive about her garden's location."] = "Dudo que sea tan fácil. No es conocida por su generosidad y es muy reservada sobre la ubicación de su jardín.",
    ["Oh come on it, it should be easy enough to find."] = "Vamos, debería ser bastante fácil de encontrar.",
    ["Her garden has remained hidden from even Osman - the chief spy of Al Kharid. I believe her garden must be hidden by magical means."] = "Su jardín ha permanecido oculto incluso de Osman, el espía principal de Al Kharid. Creo que su jardín debe estar escondido por medios mágicos.",
    ["This should be an interesting task. How many sq'irks do you want?"] = "Esta debería ser una tarea interesante. ¿Cuántos cuadrados quieres?",
    ["I'll reward you for as many as you can get your hands on, but could you please squeeze the fruit into a grass first?"] = "Te recompensaré por todas las que puedas conseguir, pero ¿podrías exprimir la fruta en la hierba primero?",
    ["Why can't you get the sq'irks yourself?"] = "¿Por qué no puedes conseguir los sq'irks tú mismo?",
    ["Osman and the Sorceress had a falling out. Now she won't give any of us spies fruit from her garden."] = "Osman y Sorceress tuvieron una pelea. Ahora no nos dará frutos de su jardín a ninguno de nosotros, los espías.",
    ["How should I squeeze the fruit?"] = "¿Cómo debo exprimir la fruta?",
    ["Use a pestle and mortar to squeeze the sq'irks. Make sure you have an empty glass with you to collect the juice."] = "Usa un mortero y un mortero para exprimir los sq'irks. Asegúrate de tener un vaso vacío contigo para recoger el jugo.",
    ["Is there a reward for getting these sq'irks?"] = "¿Hay alguna recompensa por conseguir estos sq'irks?",
    ["Of course there is. I am a generous man. I'll teach you the art of Thieving for your troubles."] = "Por supuesto que sí. Soy un hombre generoso. Te enseñaré el arte de Thieving para tus problemas.",
    ["How much training will you give?"] = "¿Cuánta formación darás?",
    ["That depends on the quantity and ripeness of the sq'irks you put into the juice."] = "Eso depende de la cantidad y madurez de los sq'irks que pongas en el jugo.",
    ["That sounds fair enough."] = "Eso suena bastante justo.",
    ["What's so good about sq'irk juice then?"] = "Entonces, ¿qué tiene de bueno el jugo sq'irk?",
    ["Ah it's sweet, sweet nectar for a thief or spy, it makes light fingers lighter, fleet feet flightier and comes in four different colours for those who are easily amused."] = "Ah, es un néctar dulce, dulce para un ladrón o un espía, hace que los dedos ligeros sean más ligeros y los pies ligeros más voladores y viene en cuatro colores diferentes para aquellos que se divierten fácilmente.",
    ["The man who is not Osman starts salivating at the thought of sq'irk juice."] = "El hombre que no es Osman comienza a salivar al pensar en el jugo de sq'irk.",
    ["It wouldn't have addictive properties, would it?"] = "No tendría propiedades adictivas, ¿verdad?",
    ["It only holds power over those with poor self-control, something which I have an abundance of."] = "Sólo tiene poder sobre aquellos con poco autocontrol, algo de lo que tengo en abundancia.",
    ["I see."] = "Ya veo.",
    ["I want to talk to you about Sophanem."] = "Quiero hablarte de Sophanem.",
    ["I've no idea what is going on there. It's all on a need-to-know basis, so I'm not going to be asking you for information either."] = "No tengo idea de lo que está pasando allí. Todo se basa en la necesidad de saberlo, por lo que tampoco le pediré información.",
    ["Who are you? Osman can't possibly be here!"] = "¿Quién eres? ¡Osman no puede estar aquí!",
    ["You can call me Osman, even though I am the man who is not Osman."] = "Puedes llamarme Osman, aunque soy el hombre que no es Osman.",
    ["So...you are one of his agents, but you look just like him?"] = "Entonces... ¿eres uno de sus agentes, pero te pareces a él?",
    ["Of course I look like him, I'm in disguise. What sort of spy would look like a spy?"] = "Por supuesto que me parezco a él, estoy disfrazado. ¿Qué tipo de espía parecería un espía?",
    ["Well, I seem to remember some business with really bad wigs."] = "Bueno, creo recordar un negocio con pelucas realmente malas.",
    ["Let's change the subject to something Osman might talk about. I don't want to blow my cover."] = "Cambiemos el tema a algo de lo que Osman podría hablar. No quiero revelar mi tapadera.",
    ["I believe I have a plan to save Prince Ali, but I can't talk to you about it here..."] = "Creo que tengo un plan para salvar al Príncipe Ali, pero no puedo hablar contigo sobre eso aquí...",
    ["You need to log into a members' world to begin the Diamond in the Rough quest."] = "Debes iniciar sesión en el mundo de un miembro para comenzar la misión Diamante en bruto.",
    ["Well done. A great rescue. I will remember you if I have anything dangerous to do."] = "Bien hecho. Un gran rescate. Te recordaré si tengo algo peligroso que hacer.",
    ["One other thing... Ozan gave me something to give to you."] = "Otra cosa... Ozan me dio algo para darte.",
    ["Would you like to claim your reward lamps?"] = "¿Quieres reclamar tus lámparas de recompensa?",
    ["You will need at least [1/2/3/4/5/6] inventory spaces to receive all of your lamps from Osman."] = "Necesitará al menos [1/2/3/4/5/6] espacios de inventario para recibir todas sus lámparas de Osman.",
    ["[Osman hands you [1/2/3/4/5/6] reward lamps for your help in rescuing Prince Ali.]"] = "[Osman te entrega lámparas de recompensa [1/2/3/4/5/6] por tu ayuda para rescatar al Príncipe Ali.]",
    ["Is there anything with which I can help you?"] = "¿Hay algo en lo que pueda ayudarte?",
    ["Actually, there is one thing you could do for me."] = "En realidad, hay una cosa que podrías hacer por mí.",
    ["And what would that be?"] = "¿Y cuál sería?",
    ["You could get me some sq'irk juice."] = "Podrías traerme un poco de jugo de sq'irk.",
    ["I'd like to talk to you about sq'irks."] = "Me gustaría hablarte sobre los sq'irks.",
    ["I have some sq'irk juice for you."] = "Tengo un poco de jugo de sq'irk para ti.",
    ["You receive some Thieving advice ([number] Thieving experience points) as a reward for the sq'irk juice."] = "Recibirás algunos consejos Thieving (puntos de experiencia [número] Thieving) como recompensa por el jugo sq'irk.",
    ["Thank you very much Player. If you get some more sq'irks be sure to come back."] = "Muchas gracias Player. Si consigues más preguntas, asegúrate de volver.",
    ["I will. It's been a pleasure doing business with you."] = "Lo haré. Ha sido un placer hacer negocios con usted.",
    ["Where am I meant to find sq'irks?"] = "¿Dónde debo encontrar sq'irks?",
    ["There is a sorceress near the south-eastern edge of Al Kharid who grows them. She used to be a friend to Al Kharid, but there was a falling out."] = "Hay una hechicera cerca del borde sureste de Al Kharid que los cultiva. Solía ​​ser amiga de Al Kharid, pero hubo una pelea.",
    ["That is a story for another time. However, now she won't give me any more fruit."] = "Esa es una historia para otro momento. Sin embargo, ahora ya no me da más frutos.",
    ["Oh, come on, it should be easy enough to find."] = "Oh, vamos, debería ser bastante fácil de encontrar.",
    ["Her garden is well hidden. I believe her garden must be hidden by magical means."] = "Su jardín está bien escondido. Creo que su jardín debe estar escondido por medios mágicos.",
    ["I'll reward you for as many as you can get your hands on, but could you please squeeze the fruit into a glass first?"] = "Te recompensaré por todas las que puedas conseguir, pero ¿podrías exprimir la fruta en un vaso primero?",
    ["I've another question about sq'irks."] = "Tengo otra pregunta sobre los sq'irks.",
    ["Thanks for the information."] = "Gracias por la información.",
    ["There was an incident between her and the city. Now she won't give us fruit from her garden."] = "Hubo un incidente entre ella y la ciudad. Ahora no nos dará frutos de su jardín.",
    ["Ah it's sweet, sweet nectar; it makes light fingers lighter, fleet feet flightier and comes in four different colours for those who are easily amused."] = "Ah, es dulce, dulce néctar; hace que los dedos ligeros sean más ligeros y los pies ligeros más voladores y viene en cuatro colores diferentes para quienes se divierten fácilmente.",
    ["He starts salivating at the thought of sq'irk juice."] = "Empieza a salivar al pensar en el jugo de sq'irk.",
    ["Hi, Osman! How are you doing?"] = "¡Hola, Osman! ¿Cómo estás?",
    ["My wounds are healing slowly but I think I'll make a full recovery."] = "Mis heridas se están curando lentamente pero creo que me recuperaré por completo.",
    ["How is Maisa? Is she back in Al Kharid?"] = "¿Cómo es Maisa? ¿Está de vuelta en Al Kharid?",
    ["Maisa is fine. Where she is or what she's doing, I couldn't possibly tell you."] = "Maisa está bien. Dónde está o qué está haciendo, no podría decírtelo.",
    ["One piece of espionage gossip I can tell you is that I won't be returning to Sophanem or Menaphos any time soon."] = "Un chisme de espionaje que puedo contarles es que no volveré a Sophanem o Menaphos en el corto plazo.",
    ["Did you know Maisa is in Sophanem, giving out quests?"] = "¿Sabías que Maisa está en Sophanem y ofrece misiones?",
    ["It's my job to know everything. Just don't believe everything you hear about me. I'm going to surprise them all one day... Pleasantly, that is."] = "Mi trabajo es saberlo todo. Simplemente no creas todo lo que oyes sobre mí. Algún día los sorprenderé a todos... Gratamente, eso es.",
    ["Is there anything else with which I can help you?"] = "¿Hay algo más en lo que pueda ayudarte?",
    ["Do you know anything about Keris, the dagger I recovered in the course of my last mission?"] = "¿Sabes algo sobre Keris, la dagger que recuperé durante mi última misión?",
    ["We discovered a stash of them in some of our investigations. As far as we have been able to determine, it was created by worshippers of Elidinis in order to smite the followers of Scabaras."] = "Descubrimos un alijo de ellos en algunas de nuestras investigaciones. Hasta donde hemos podido determinar, fue creado por adoradores de Elidinis para herir a los seguidores de Scabaras.",
    ["So what is so good about them?"] = "Entonces, ¿qué tienen de bueno?",
    ["They are specially enchanted against both scarab creatures and kalphites...which is odd, since we thought the two races to be entirely different. Any more details you'll have to discover yourself by using it in the field."] = "Están especialmente encantados contra criaturas escarabajos y kalfitas... lo cual es extraño, ya que pensábamos que las dos razas eran completamente diferentes. Cualquier detalle más tendrás que descubrirlo tú mismo usándolo en el campo.",
    ["Thanks."] = "Gracias.",
    ["Shhh! I'm waiting for the show!"] = "¡Shhh! ¡Estoy esperando el espectáculo!",
    ["What's on the bill?"] = "¿Qué hay en la factura?",
    ["Nothing an outerlander would enjoy!"] = "¡Nada que un extranjero disfrutaría!",
    ["There's a performance of an epic from olden times tonight! The epic of Bukalla!"] = "¡Esta noche hay una presentación de una epopeya de tiempos antiguos! ¡The epic of Bukalla!",
    ["Bukalla?"] = "¿Bukalla?",
    ["He was a famed slayer of daggermouths in olden times. It's a very inspirational song."] = "Era un famoso cazador de bocas de daga en la antigüedad. Es una canción muy inspiradora.",
    ["Sounds interesting! Maybe I'll stick around."] = "¡Suena interesante! Quizás me quede por aquí.",
    ["The Epic of Bukalla is a live recorded poem, roughly five minutes in length. We suggest that you turn your sound on in order to get the most out of it."] = "The Epic of Bukalla es un poema grabado en vivo, de aproximadamente cinco minutos de duración. Le sugerimos que active el sonido para aprovecharlo al máximo.",
    ["I'm ready to hear it!"] = "¡Estoy listo para escucharlo!",
    ["Wait a second!"] = "¡Espera un segundo!",
    ["Sounds boring"] = "Suena aburrido",
    ["Sounds boring."] = "Suena aburrido.",
    ["Well, you're missing out on a glorious piece of history."] = "Bueno, te estás perdiendo una gloriosa parte de la historia.",
    ["Welcome to the Miscellania food store. We've only opened recently."] = "Bienvenido a la tienda de alimentos Miscellania. Abrimos recientemente.",
    ["Would you like to buy anything, your Royal Highness?"] = "¿Le gustaría comprar algo, Alteza Real?",
    ["Could you show me what you have for sale?"] = "¿Podrías mostrarme lo que tienes a la venta?",
    ["No thank you, I don't need food just now."] = "No, gracias, no necesito comida en este momento.",
    ["What's it like living down here?"] = "¿Cómo es vivir aquí abajo?",
    ["The town's thriving. I'm sure it'll soon be as busy as Rellekka!"] = "La ciudad está prosperando. ¡Estoy seguro de que pronto estará tan ocupado como Rellekka!",
    ["**Otavea** Hello Player, Lovely weather we're having today."] = "**Otavea** Hola Player, Hoy tenemos un clima maravilloso.",
    ["Greetings Player, what brings you here?"] = "Saludos Player, ¿qué te trae por aquí?",
    ["Hello Otavea. I've been sent to make sure you and your people are doing okay, under the circumstances."] = "Hola Otavea. Me han enviado para asegurarme de que usted y su gente estén bien, dadas las circunstancias.",
    ["That's much appreciated Player. There has been some trying times recently. But there is hope on the horizon for our people, with new land for us and new generations in the future."] = "Eso se lo agradece mucho Player. Ha habido algunos momentos difíciles recientemente. Pero hay esperanza en el horizonte para nuestro pueblo, con nuevas tierras para nosotros y nuevas generaciones en el futuro.",
    ["Speaking of. I'm in the process of running supplies from the mainland to the island you refer to as Anachronia."] = "Hablando de eso. Estoy en el proceso de llevar suministros desde el continente a la isla a la que te refieres como Anacronia.",
    ["Some of my ilujanka have began integrating into life on the island. Apparently rearing some mighty creatures, and 'pruning' some of the local fungi!"] = "Algunos de mis ilujanka han comenzado a integrarse a la vida en la isla. ¡Aparentemente criando algunas criaturas poderosas y \"podando\" algunos de los hongos locales!",
    ["I have Luke the Gurh here with me. Could you put together a nice dish for him to eat? He's been working hard and needs to keep his energy up."] = "Tengo a Luke the Gurh aquí conmigo. ¿Podrías prepararle un rico plato para comer? Ha estado trabajando duro y necesita mantener su energía.",
    ["Just mix this redcane together with some fresh vegetables, that should perk him up!"] = "Simplemente mezcla este caña roja con algunas verduras frescas, ¡eso debería animarlo!",
    ["On it!"] = "¡Adelante!",
    ["Thank you kindly Player. Here is some redcane!"] = "Gracias amablemente Player. ¡Aquí hay algo de caña roja!",
    ["Hello Player. Have you had any success with my gurh?"] = "Hola Player. ¿Has tenido algún éxito con mi gurh?",
    ["I'm still working on it."] = "Todavía estoy trabajando en ello.",
    ["You'll be needing some redcane to make a nice medley. I'll give you some redcane once you have some space in your backpack."] = "Necesitarás un poco de caña roja para hacer un buen popurrí. Te daré un poco de caña roja una vez que tengas algo de espacio en tu backpack.",
    ["You'll be needing some redcane to make a nice medley. Here you go!"] = "Necesitarás un poco de caña roja para hacer un buen popurrí. ¡Aquí tienes!",
    ["Not to worry. Don't forget to use that redcane to create a tasty treat!"] = "No te preocupes. ¡No olvides usar ese bastón rojo para crear un delicioso manjar!",
    ["**Otavea** Thanks for the assistance Player. Luke the Gurh seems much happier now."] = "**Otavea** Gracias por la ayuda Player. Luke the Gurh parece mucho más feliz ahora.",
    ["**Otavea** I'll get these supplies shipped off shortly. Do pay a visit to my friends on the island if you get a chance. I hear they're creating some items of interest with a nice young lady."] = "**Otavea** Enviaré estos suministros en breve. Visita a mis amigos en la isla si tienes la oportunidad. He oído que están creando algunos artículos de interés con una simpática joven.",
    ["*When speaking to Otto Godblessed without items related to Barbarian training; Barbarian skills will always be given before My notes.*"] = "*Al hablar con Otto Godblessed sin elementos relacionados con el entrenamiento bárbaro; Las habilidades bárbaras siempre se darán antes de Mis notas.*",
    ["*If the player has a free inventory slot and no copy of Barbarian skills in their bank or inventory:*"] = "*Si el player tiene un espacio de inventario libre y no tiene ninguna copia de las habilidades de Bárbaro en su banco o inventario:*",
    ["I see you have free space and no record of the tasks I have set you. Please take this book as a record of your progress - between the spirits and your diligence, I expect it will always be up to date."] = "Veo que tienes espacio libre y no tienes registro de las tareas que te he asignado. Por favor, tome este libro como un registro de su progreso; entre el espíritu y su diligencia, espero que siempre esté actualizado.",
    ["*If the player has a free inventory slot and no copy of My notes in their bank or inventory:*"] = "*Si el player tiene un espacio de inventario libre y no tiene ninguna copia de Mis notas en su banco o inventario:*",
    ["I see you have free space and no way to record any information you may recover from the caverns. Please take this book as a record of your researches - between the spirits and your diligence I expect it will always be up to date."] = "Veo que tienes espacio libre y no hay forma de registrar la información que puedas recuperar de las cavernas. Por favor, tome este libro como un registro de sus investigaciones; entre el espíritu y su diligencia espero que siempre esté actualizado.",
    ["Why might I need such a thing? I already have a book of notes."] = "¿Por qué podría necesitar algo así? Ya tengo un libro de notas.",
    ["Those who have previously entered the cavern have not all returned, some of them seemed intent upon research and discovery as much as loot and daring deeds. It would be a shame if you were to recover any of their notes and be unable to record them handily. I hope the new book will give you space for such discoveries."] = "No todos los que entraron previamente a la caverna han regresado, algunos de ellos parecían decididos a investigar y descubrir tanto como a saquear y realizar hazañas audaces. Sería una pena que recuperaras alguna de sus notas y no pudieras registrarlas cómodamente. Espero que el nuevo libro le dé espacio para tales descubrimientos.",
    ["*When speaking to Otto Godblessed at Otto's Grotto, after having completed all of Barbarian training.*"] = "*Al hablar con Otto Godblessed en Otto's Grotto, después de haber completado todo el entrenamiento bárbaro.*",
    ["Welcome back oh friend of the spirits, I am humbled in your presence."] = "Bienvenido de nuevo, oh amigo de los espíritus, me siento honrado en tu presencia.",
    ["That's very kind, but I was wondering whether you have any more information for me?"] = "Es muy amable, pero me preguntaba si tienes más información para mí.",
    ["You are no longer the apprentice, but the master. Seek to inspire us with your daring deeds and legendary feats. Aspire to join the spirits when your time comes."] = "Ya no eres el aprendiz, sino el maestro. Busca inspirarnos con tus audaces hazañas y hazañas legendarias. Aspira a unirte a los espíritus cuando llegue tu momento.",
    ["Could you tell me more of these spirits you continually refer to?"] = "¿Podrías contarme más sobre estos espíritus a los que te refieres continuamente?",
    ["Certainly, though it is quite simple - they are the barbarians of the past, who have died in the passing of the years. There are three categories which learned sages claim may describe all spirits encountered. The majority are at peace, having died with their ambitions sated, even if this ambition was as simple as a glorious death. They can contact those in our world in order to spur us on to glory. Of course, they cannot or will not contact all inhabitants of these lands. All are not worthy."] = "Ciertamente, aunque es bastante simple: son los bárbaros del pasado, que han muerto con el paso de los años. Hay tres categorías que, según los sabios eruditos, pueden describir todos los espíritus encontrados. La mayoría está en paz, habiendo muerto con sus ambiciones saciadas, aunque esta ambición fuera tan simple como una muerte gloriosa. Pueden contactar a aquellos en nuestro mundo para impulsarnos a la gloria. Por supuesto, no pueden o no quieren contactar a todos los habitantes de estas tierras. No todos son dignos.",
    ["So those are the spirits who give us guidance. What of the other sorts?"] = "Entonces esos son los espíritus que nos guían. ¿Qué pasa con los otros tipos?",
    ["A second category of spirit is made up of those who are not yet at peace. However, all that is needed is for their mortal remains to be laid to rest and they will join the peaceful majority."] = "Una segunda categoría de espíritu está formada por aquellos que aún no están en paz. Sin embargo, todo lo que se necesita es que sus restos mortales sean enterrados y se unan a la mayoría pacífica.",
    ["I can see the pyres serve this purpose. The final category is also restless?"] = "Veo que las piras sirven para este propósito. ¿La categoría final también está inquieta?",
    ["Alas, there is a small minority who will never be at rest. These have been slain in moments of insanity by their brothers or by adventurers. They are not at rest and will attack those they blame for their tortured state. They are not known, however, for being able to determine this blame with any great accuracy, so may be considered as dangerous to all."] = "Lamentablemente, hay una pequeña minoría que nunca descansará. Estos han sido asesinados en momentos de locura por sus hermanos o por aventureros. No están tranquilos y atacarán a quienes culpan de su estado de tortura. Sin embargo, no son conocidos por ser capaces de determinar esta culpa con gran precisión, por lo que pueden considerarse peligrosos para todos.",
    ["I thank you Otto, it makes a bit more sense now."] = "Te agradezco Otto, ahora tiene un poco más de sentido.",
    ["I wish to change my fishing style"] = "Deseo cambiar mi estilo de pesca",
    ["I wish to change how I fish."] = "Deseo cambiar mi forma de pescar.",
    ["So be it."] = "Que así sea.",
    ["You revert to default fishing techniques."] = "Vuelve a las técnicas de pesca predeterminadas.",
    ["You revert to barbarian fishing techniques."] = "Vuelves a las técnicas de pesca bárbaras.",
    ["I have no more questions at this time."] = "No tengo más preguntas en este momento.",
    ["In that case, farewell."] = "En ese caso, adiós.",
    ["This looks like a good spot for a command centre."] = "Este parece un buen lugar para un centro de mando.",
    ["Welcome to the command centre."] = "Bienvenido al centro de mando.",
    ["What does a command centre do?"] = "¿Qué hace un centro de mando?",
    ["With a functioning command centre you will have remote access to all your global operations."] = "Con un centro de comando en funcionamiento, tendrá acceso remoto a todas sus operaciones globales.",
    ["Global operations?"] = "¿Operaciones globales?",
    ["Surely a great person like you must have more going on beyond these walls. You can manage all of it from here."] = "Seguramente una gran persona como tú debe tener más cosas que hacer más allá de estos muros. Puedes gestionarlo todo desde aquí.",
    ["Surely a [Title] like you must have more going on beyond these walls. You can manage all of it from here."] = "Seguramente un [Title] como tú debe tener más cosas que hacer más allá de estas paredes. Puedes gestionarlo todo desde aquí.",
    ["Ask about Miscellania."] = "Pregunta por Miscellania.",
    ["Do you have any holdings in Miscellania?"] = "¿Tiene alguna participación en Miscellania?",
    ["Not as such, no."] = "No como tal, no.",
    ["Complete the Throne of Miscellania quest to unlock Managing Miscellania."] = "Completa la misión del Trono de Miscellania para desbloquear la Gestión de Miscellania.",
    ["I have a whole Kingdom in Miscellania, actually."] = "De hecho, tengo todo un reino en Miscellania.",
    ["You're [Fremennik name]? I had no idea."] = "¿Eres [Fremennik name]? No tenía ni idea.",
    ["I imagine you're finding it hard to keep your subjects happy?"] = "Me imagino que te resultará difícil mantener contentos a tus súbditos.",
    ["It can be a bit of a chore."] = "Puede ser un poco complicado.",
    ["Through the command we could organise a care package system, if we have the resources and you can fund it."] = "A través del comando podríamos organizar un sistema de paquetes de atención, si tenemos los recursos y puedes financiarlo.",
    ["You can pay gold to improve subject approval. This requires a tier 3 command centre."] = "Puedes pagar oro para mejorar la aprobación de los sujetos. Esto requiere un centro de mando de nivel 3.",
    ["Ask about Anachronia."] = "Pregunta sobre Anacronía.",
    ["Anachronia? Have you been there?"] = "¿Anacronía? ¿Has estado allí?",
    ["Travel to Anachronia aboard the Stormbreaker, docked at the Archaeology Guild, to unlock the Base Camp."] = "Viaja a Anacronia a bordo del Stormbreaker, atracado en el gremio Archaeology, para desbloquear el campamento base.",
    ["I manage the base camp on Anachronia."] = "Administro el campamento base en Anacronia.",
    ["Always in need of more labour, I assume. I'm sure we can organise something."] = "Supongo que siempre necesito más mano de obra. Estoy seguro de que podemos organizar algo.",
    ["Couldn't hurt."] = "No podría hacer daño.",
    ["Building tier 2 and 3 of the command centre each add 5 workers to your Base Camp."] = "Los niveles de construcción 2 y 3 del centro de comando agregan cada uno 5 trabajadores a su campamento base.",
    ["Ask about Archaeology."] = "Pregunta por Archaeology.",
    ["Archaeology? Is that a specialisation of yours?"] = "¿Archaeology? ¿Es esa una especialización tuya?",
    ["Not really."] = "En realidad, no.",
    ["Reach level 40 Archaeology and attain the Assistant qualification to unlock Research."] = "Alcanza el nivel 40 Archaeology y obtén la calificación de Asistente para desbloquear la Investigación.",
    ["My team of crack researchers are always busy at the Archaeology Guild."] = "Mi equipo de investigadores de crack siempre está ocupado en el Gremio Archaeology.",
    ["We are in the Wilderness. I'm sure we can dig up something interesting to send them."] = "Estamos en el Wilderness. Estoy seguro de que podemos encontrar algo interesante para enviarles.",
    ["A tier 2 command centre reduces research costs by 3%. A tier 3 command centre increases research speed by 3%."] = "Un centro de mando de nivel 2 reduce los costos de investigación en un 3%. Un centro de mando de nivel 3 aumenta la velocidad de investigación en un 3%.",
    ["Ask about Player-owned Ports."] = "Pregunte acerca de los puertos propiedad de Player.",
    ["Do you spend much of your time hanging around in ports?"] = "¿Pasas gran parte de tu tiempo merodeando por los puertos?",
    ["Reach level 90 Agility, Construction, Cooking, Divination, Dungeoneering, Fishing, Herblore-"] = "Alcanza el nivel 90 Agility, Construction, Cooking, Divination, Dungeoneering, Fishing, Herblore-",
    ["*gasp*"] = "*jadeo*",
    ["-Hunter, Prayer, Runecrafting, Slayer or Thieving to unlock Player-owned Ports."] = "-Hunter, Prayer, Runecrafting, Slayer o Thieving para desbloquear puertos propiedad de Player.",
    ["I do like to send the occasional voyage out to the Eastern Lands from my merchant venture."] = "Me gusta enviar algún viaje ocasional a las Tierras del Este desde mi empresa comercial.",
    ["Well that's no problem. We Fremennik are the world's greatest merchant sailors."] = "Bueno, eso no es problema. Nosotros, los Fremennik, somos los mejores marinos mercantes del mundo.",
    ["With enough resources, I'm sure we can make some efficiency savings."] = "Con suficientes recursos, estoy seguro de que podemos lograr algunos ahorros de eficiencia.",
    ["Ports missions gain a 3%, 6% and 10% boost to success chance at tier 1, 2 and 3 of the command centre respectively."] = "Las misiones de los puertos obtienen un aumento del 3%, 6% y 10% en las posibilidades de éxito en los niveles 1, 2 y 3 del centro de comando, respectivamente.",
    ["*When speaking to Overseer at the Sawmill*"] = "*Al hablar con Overseer en el Aserradero*",
    ["Yes? What do you want? I'm very busy!"] = "¿Sí? ¿Qué deseas? ¡Estoy muy ocupado!",
    ["This is the sawmill training area, where we take the more qualified woodcutters on work experience."] = "Esta es el área de capacitación del aserradero, donde llevamos a los leñadores más calificados en experiencia laboral.",
    ["Work experience?"] = "¿Experiencia laboral?",
    ["Yeah. You work, you gain experience. You DO NOT gain planks, as I have to tell everyone."] = "Sí. Trabajas, ganas experiencia. NO ganas planks, como tengo que decirles a todos.",
    ["Not even a few..."] = "Ni siquiera unos pocos...",
    ["NO PLANKS!"] = "¡NO PLANKS!",
    ["Okay, okay."] = "Está bien, está bien.",
    ["The name's Jill. I'm the sawmill overseer."] = "El nombre es Jill. Soy el supervisor del aserradero.",
    ["Pleased to meet y-"] = "Encantado de conocerte-",
    ["I'm in charge of this place, so no fooling around!"] = "Estoy a cargo de este lugar, ¡así que no pierdas el tiempo!",
    ["What should I be doing?"] = "¿Qué debería estar haciendo?",
    ["Well, first grab a job from the board. There's short and long jobs: pick whichever you fancy. Then you stock up on wood from the piles and stack it in the hopper. The machine will do its magic and, before you know it, you'll have a stack of planks at the other end. Take these, with a saw, to the workbench to cut the planks you need. All the finished planks go straight into the cart, but you can take out any excess planks and use them for the next batch, if you like. Just let me know when you're ready to send an order."] = "Bueno, primero consigue un trabajo del tablero. Hay trabajos cortos y largos: elige el que más te guste. Luego se abastece de madera de las pilas y se apila en la tolva. La máquina hará su magia y, antes de que te des cuenta, tendrás una pila de planks en el otro extremo. Llévalos, con una sierra, al banco de trabajo para cortar el planks que necesitas. Todo el planks terminado va directamente al carrito, pero puedes sacar el exceso de planks y usarlo para el siguiente lote, si lo deseas. Sólo avíseme cuando esté listo para enviar un pedido.",
    ["Bye."] = "Adiós.",
    ["Hello. What are you doing?"] = "Hola. ¿Qué estás haciendo?",
    ["I'm the rat keeper, it's my job to look after these here rats."] = "Soy el cuidador de las ratas, mi trabajo es cuidar de estas ratas.",
    ["You do know that there are some rats running loose?"] = "¿Sabes que hay algunas ratas sueltas?",
    ["Some nibble their way out from time to time. Don't worry there's enough cats down here to sort anything that gets out."] = "Algunos mordisquean para salir de vez en cuando. No te preocupes, hay suficientes gatos aquí abajo para clasificar cualquier cosa que salga.",
    ["So how do these rat pits work?"] = "Entonces, ¿cómo funcionan estos pozos de ratas?",
    ["The Keldagrim pits cater for those with the larger variety of cats."] = "Las fosas Keldagrim atienden a aquellos con una mayor variedad de gatos.",
    ["If you have an overgrown cat and a couple of coins you can challenge someone else who also has an overgrown cat and some spare change."] = "Si tienes un gato grande y un par de coins, puedes desafiar a otra persona que también tenga un gato grande y algo de cambio.",
    ["That sounds simple enough so far."] = "Eso suena bastante simple hasta ahora.",
    ["You then agree on a wager. It's rumoured that some ratcatchers can talk to their own cats and give them tactics to aid them."] = "Luego aceptas una apuesta. Se rumorea que algunos cazadores de ratas pueden hablar con sus propios gatos y darles tácticas para ayudarlos.",
    ["So then how do you win the challenge?"] = "Entonces, ¿cómo se gana el desafío?",
    ["I was just getting to that. Both the gamblers' cats are placed inside of the fenced off area, and whoever kills 9 rats first wins."] = "Estaba llegando a eso. Los gatos de ambos jugadores se colocan dentro del área vallada y quien mate primero a 9 ratas gana.",
    ["That sounds vile and cruel."] = "Eso suena vil y cruel.",
    ["It's a cruel world and the pits are no exception."] = "Es un mundo cruel y los boxes no son una excepción.",
    ["Each to their own I say."] = "Cada uno por su lado digo.",
    ["One more thing..."] = "Una cosa más...",
    ["Thanks for your help."] = "Gracias por tu ayuda.",
    ["It sounds a little dangerous for my cat."] = "Suena un poco peligroso para mi gato.",
    ["I agree. Cats have been known to be killed in fights."] = "Estoy de acuerdo. Se sabe que los gatos mueren en peleas.",
    ["Oh how terrible. Is there nothing you can do to save your cat?"] = "Oh, qué terrible. ¿No hay nada que puedas hacer para salvar a tu gato?",
    ["Of course there is, you can instruct it to be cautious, and it will leave once it feels as if it is in danger."] = "Por supuesto que sí, puedes indicarle que tenga cuidado y se irá una vez que sienta que está en peligro.",
    ["Oh that sounds quite wise."] = "Oh, eso suena muy sabio.",
    ["That depends on how you value your cat."] = "Eso depende de cómo valoras a tu gato.",
    ["Sorry, I don't follow."] = "Lo siento, no te sigo.",
    ["Well if your cat dies or it runs away you lose."] = "Bueno, si tu gato muere o se escapa, pierdes.",
    ["So the longer it stays in the fight the better chance you have of winning."] = "Entonces, cuanto más tiempo permanezca en la pelea, más posibilidades tendrás de ganar.",
    ["Wow that sounds like fun!"] = "¡Vaya, eso suena divertido!",
    ["I don't know about that."] = "No sé nada de eso.",
    ["One thing I know though is that it's a quick way to make and lose money."] = "Una cosa que sé es que es una forma rápida de ganar y perder dinero.",
    ["Is there a limit to how much you can bet?"] = "¿Existe un límite de cuánto puedes apostar?",
    ["Hmmm...let me see. If I'm not mistaken, you can currently bet up to a maximum of [number] coins."] = "Hmmm... déjame ver. Si no me equivoco, actualmente puedes apostar hasta un máximo de [número] coins.",
    ["That sounds like a silly amount of money to bet on a cat fight."] = "Suena como una cantidad tonta de dinero para apostar en una pelea de gatos.",
    ["You'd be surprised what some people would be willing to bet."] = "Te sorprendería lo que algunas personas estarían dispuestas a apostar.",
    ["There is a minimum bet of 100 coins too."] = "También hay una apuesta mínima de 100 coins.",
    ["Can I challenge you and your cat?"] = "¿Puedo desafiarte a ti y a tu gato?",
    ["No, not now, we don't really bet with outsiders."] = "No, ahora no, realmente no apostamos con forasteros.",
    ["But I'm not an outsider, am I not inside in the pits now?"] = "Pero no soy un outsider, ¿no estoy ahora en boxes?",
    ["I don't know, maybe once you've done something to win over my trust."] = "No lo sé, tal vez una vez que hayas hecho algo para ganarte mi confianza.",
    ["Can it be bought?"] = "¿Se puede comprar?",
    ["Your trust."] = "Tu confianza.",
    ["No. Regular townsfolk don't like us, which leads us to distrust them and anyone else."] = "No. No agradamos a la gente común del pueblo, lo que nos lleva a desconfiar de ellos y de cualquier otra persona.",
    ["It was you?"] = "¿Fuiste tú?",
    ["Ha ha ha!"] = "¡Ja, ja, ja!",
    ["It's not funny, Ozan!"] = "¡No es gracioso, Ozan!",
    ["It is, though! The look on your face..."] = "¡Pero lo es! La mirada en tu cara...",
    ["I risked life and limb to retrieve those artefacts for the museum. Then I find out that you had stolen them from the museum again!"] = "Arriesgué mi vida para recuperar esos artefactos para el museo. ¡Entonces descubrí que los habías robado otra vez del museo!",
    ["The artefacts were in storage. They'd finished studying them."] = "Los artefactos estaban almacenados. Habían terminado de estudiarlos.",
    ["You never finish studying something."] = "Nunca terminas de estudiar algo.",
    ["We've often had to steal museum artefacts for a mission."] = "A menudo hemos tenido que robar objetos de museo para una misión.",
    ["Yes, when we needed something and the museum wouldn't give it up, and then we returned them afterwards. Ozan stole these for private collectors."] = "Sí, cuando necesitábamos algo y el museo no nos lo daba, y luego lo devolvíamos. Ozan los robó para coleccionistas privados.",
    ["Aw, it was just from a museum. It wasn't like I took food from poor families..."] = "Ah, era sólo de un museo. No era como si tomara comida de familias pobres...",
    ["That old man nearly took down the Tower. Traiborn had to break out one of his thingummywuts."] = "Ese old man casi derriba la Torre. Traiborn tuvo que sacar una de sus cositas.",
    ["Ozan, you must have heard stories about him."] = "Ozan, debes haber escuchado historias sobre él.",
    ["Hundreds. They can't possibly be true, though. I know exaggeration when I see it."] = "Cientos. Sin embargo, no es posible que sean ciertas. Reconozco la exageración cuando la veo.",
    ["Hey, it's our newest guild member!"] = "¡Oye, es nuestro miembro más nuevo del gremio!",
    ["I told you Player would make it into the guild. Didn't I tell you?"] = "Te dije que Player entraría al gremio. ¿No te lo dije?",
    ["Several times, at length."] = "Varias veces, extensamente.",
    ["It was nothing."] = "No fue nada.",
    ["I don't think you understand what being an adventurer is all about."] = "No creo que entiendas de qué se trata ser un aventurero.",
    ["It's about the legend! The glory! Bards will sing of our exploits for generations - but only if we teach them the songs!"] = "¡Se trata de la leyenda! ¡La gloria! Los bardos cantarán nuestras hazañas durante generaciones, ¡pero sólo si les enseñamos las canciones!",
    ["What about you, Ariane?"] = "¿Y tú, Ariane?",
    ["It's about making the world a better place."] = "Se trata de hacer del mundo un lugar mejor.",
    ["It was one of many epic adventures!"] = "¡Fue una de muchas aventuras épicas!",
    ["I know! I've heard the stories about you. I've passed some of them on myself!"] = "¡Lo sé! He oído historias sobre ti. ¡Me he pasado algunos de ellos!",
    ["Changing them to stories about you."] = "Cambiándolas a historias sobre ti.",
    ["Or inserting yourself as the one who saves the day."] = "O insertarte como quien salva el día.",
    ["Don't listen to her, Player! All my stories are the unembellished facts."] = "¡No la escuches, Player! Todas mis historias son hechos sin adornos.",
    ["That's the tallest tale I've heard for a while."] = "Ese es el cuento más fantástico que he escuchado en mucho tiempo.",
    ["Who are you people?"] = "¿Quiénes son ustedes?",
    ["I'm sorry, I thought you knew each other."] = "Lo siento, pensé que se conocían.",
    ["Player, sadly there's just the two of us at the moment. This is Ozan."] = "Player, lamentablemente solo estamos nosotros dos en este momento. Este es Ozan.",
    ["We have not seen Sir Owen here for some time..."] = "Hace tiempo que no vemos a Sir Owen por aquí...",
    ["No need to introduce yourself, Player. Ariane has told me all about you."] = "No es necesario que te presentes, Player. Ariane me ha contado todo sobre ti.",
    ["You're a worthy addition to the guild."] = "Eres una valiosa incorporación al gremio.",
    ["Okay, you got into the tomb. How big was it?"] = "Está bien, entraste en la tumba. ¿Qué tan grande era?",
    ["It was about fifty metres long, ten wide, and five high."] = "Tenía unos cincuenta metros de largo, diez de ancho y cinco de alto.",
    ["No, no! I don't want to know its measurements. You've got to say how big it was!"] = "¡No, no! No quiero saber sus medidas. ¡Tienes que decir lo grande que era!",
    ["I just said..."] = "Acabo de decir...",
    ["You need to give a sense of how big it was. Your flickering torchlight could not penetrate the dust to the far wall. The sound of your footfalls was lost in the immensity as the weight of ages pressed down on you..."] = "Tienes que dar una idea de lo grande que era. La luz parpadeante de tu antorcha no pudo atravesar el polvo hasta la pared del fondo. El sonido de tus pasos se perdió en la inmensidad mientras el peso de las edades te presionaba...",
    ["Um, alright. It was...very big?"] = "Mmm, está bien. Era... ¿muy grande?",
    ["That's a start. What did you find in the tomb?"] = "Eso es un comienzo. ¿Qué encontraste en la tumba?",
    ["There were fourteen skeletons in various states of-"] = "Había catorce esqueletos en varios estados de-",
    ["Ah! So you battled with the skeletons! Unsleeping guardians, enraged at your intrusion into-"] = "¡Ah! ¡Así que luchaste con los esqueletos! Guardianes insomnes, enfurecidos por vuestra intrusión en...",
    ["No, ordinary skeletons. The old king's servants had been buried in the outer chamber to provide for him in the next life."] = "No, esqueletos ordinarios. Los sirvientes del viejo rey habían sido enterrados en la cámara exterior para sustentarlo en la próxima vida.",
    ["The old king's guards had been buried there to protect him, and you fought them with magic fireballs! No one wants to hear a story about burial customs."] = "Los guardias del viejo rey habían sido enterrados allí para protegerlo, ¡y tú luchaste contra ellos con bolas de fuego mágicas! Nadie quiere oír una historia sobre costumbres funerarias.",
    ["Well, okay. Whgen I had...got past...the skeletons, there was a locked door. I had to figure out its mechanism."] = "Bueno, está bien. Cuando había... superado... los esqueletos, había una puerta cerrada con llave. Tuve que descubrir su mecanismo.",
    ["While the walls were closing in? With spikes?"] = "¿Mientras los muros se cerraban? ¿Con púas?",
    ["No, there was no pressure. Actually, I left the tomb at that point to read up on that type of mechanism, back at the Tower."] = "No, no hubo presión. En realidad, salí de la tumba en ese momento para leer sobre ese tipo de mecanismo, allá en la Torre.",
    ["You can't make an exciting story about reading books! No, the walls were closing in, and you got the door open just in time. And, on the other side, you saw..."] = "¡No se puede crear una historia emocionante leyendo libros! No, las paredes se estaban cerrando y abriste la puerta justo a tiempo. Y, del otro lado, viste...",
    ["There was a marble sarcophagus about three metres-"] = "Había un sarcófago de mármol de unos tres metros-",
    ["*Ahem*"] = "*Ejem*",
    ["A...huge...marble sarcophagus...studded with jewels, and carved into a...terrifying visage."] = "Un... enorme... sarcófago de mármol... tachonado de joyas y tallado en un... rostro aterrador.",
    ["That's better. And then?"] = "Eso está mejor. ¿Y luego?",
    ["Inside the sarcophagus...inside the sarcophagus, I found the king's burial mask, solid gold and carved all over with hieroglyphics."] = "Dentro del sarcófago... dentro del sarcófago, encontré la máscara funeraria del rey, de oro macizo y tallada con jeroglíficos por todas partes.",
    ["An ancient artefact of mystical power!"] = "¡Un antiguo artefacto de poder místico!",
    ["It wasn't..."] = "No fue...",
    ["An ancient artefact...whose powers we have yet to unlock."] = "Un artefacto antiguo... cuyos poderes aún tenemos que desbloquear.",
    ["There! You're getting the idea. Now change the main character to me, and you've got the perfect story!"] = "¡Ahí! Estás entendiendo la idea. ¡Ahora cambia el personaje principal por mí y tendrás la historia perfecta!",
    ["I found Sir Prysin in the Blue Moon Inn the other day, telling everyone how he single-handedly defeated Delrith!"] = "¡Encontré a Sir Prysin en el Blue Moon Inn el otro día, contándoles a todos cómo derrotó a Delrith sin ayuda de nadie!",
    ["Don't worry, I set the record straight and told everyone it was you who killed the demon."] = "No te preocupes, dejé las cosas claras y les dije a todos que fuiste tú quien mató al demonio.",
    ["After that, I turned the conversation back around to myself and my own fantastic demon-slaying exploits, of course! I can't let your reputation to surpass mine!"] = "Después de eso, volví a centrar la conversación en mí y en mis fantásticas hazañas para matar demonios, ¡por supuesto! ¡No puedo permitir que tu reputación supere la mía!",
    ["I heard the story that Radimus Erkle's been telling about you in the Legends' Guild. I don't know how you got him to buy it! I mean, I've been known to exaggerate, but I keep it plausible."] = "Escuché la historia que Radimus Erkle ha estado contando sobre ti en Legends' Guild. ¡No sé cómo conseguiste que lo comprara! Quiero decir, se sabe que exagero, pero lo mantengo plausible.",
    ["Mapping a whole swathe of jungle by yourself! Going toe-to-toe with Nezikchened and defeating him - three times?"] = "¡Mapea toda una franja de jungla tú mismo! ¿Enfrentarse cara a cara con Nezikchened y derrotarlo... tres veces?",
    ["Normally I embellish the stories I tell about you, but this one I'm having to tone down or people will laugh me off the stage!"] = "Normalmente embellezco las historias que cuento sobre ti, pero esta tengo que bajarle el tono o la gente se reirá de mí fuera del escenario.",
    ["Hazelmere, dead. Cyrisus, dead. Lucien is going to pay for that someday."] = "Hazelmere, muerto. Cyrisus, muerto. Lucien va a pagar por eso algún día.",
    ["I should have been there. The Crux Eqal recruited me, Owen and Ariane to attack another of Lucien's bases, but it turned out he'd already abandoned it."] = "Debería haber estado allí. El Crux Eqal nos reclutó a Owen, a Ariane y a mí para atacar otra de las bases de Lucien, pero resultó que ya la había abandonado.",
    ["So, the other day, I went out with a cute wizard apprentice, Ilona, and she told me how you rescued her from a cult in the Lumbridge Catacombs."] = "Entonces, el otro día, salí con una linda aprendiz de mago, Ilona, y ella me contó cómo la rescataste de una secta en las catacumbas de Lumbridge.",
    ["I told her some stories about my adventures, but she kept turning the conversation back to you!"] = "Le conté algunas historias sobre mis aventuras, ¡pero ella siguió volviendo la conversación hacia ti!",
    ["If anyone asks about the time you and I got shipwrecked together and had to fight a horde of zombie trolls, or the time I saved you from the lair of the fire spiders, just nod, okay?"] = "Si alguien pregunta sobre la vez que tú y yo naufragamos juntos y tuvimos que luchar contra una horda de trolls zombies, o la vez que te salvé de la guarida de las arañas de fuego, simplemente asiente, ¿de acuerdo?",
    ["I've been adventuring with your friend Zanik lately. We teamed up to steal back some gold that the H.A.M. group had taken from Varrock Palace."] = "Últimamente he estado de aventuras con tu amigo Zanik. Nos unimos para recuperar algo de oro que H.A.M. grupo había tomado del Palacio Varrock.",
    ["We got in and out without being spotted, and returned the money. Well, we returned most of the money. Some of it might have ended up paying for that holiday we took together down to Oo'glog..."] = "Entramos y salimos sin que nos vieran y devolvimos el dinero. Bueno, devolvimos la mayor parte del dinero. Parte de ello podría haber terminado pagando esas vacaciones que tomamos juntos hasta Oo'glog...",
    ["She thinks very highly of you, you know. She says you saved her city and defeated an evil god, and when I look into those big eyes I can't believe she's exaggerating."] = "Ella piensa muy bien en ti, ¿sabes? Ella dice que salvaste su ciudad y derrotaste a un dios maligno, y cuando miro esos grandes ojos no puedo creer que esté exagerando.",
    ["Whoa, slow down there with the world-saving! At this rate, people will be telling more stories about you than me!"] = "¡Vaya, más despacio con el salvamundos! ¡A este paso, la gente contará más historias sobre ti que sobre mí!",
    ["Still, I have to hand it to you, I couldn't have done much better myself."] = "Aún así, tengo que admitirlo: yo no podría haberlo hecho mucho mejor.",
    ["Hey, you're the Champion of Crandor! Eviscerator of Elvarg! Dragon's Doom!"] = "¡Oye, eres el campeón de Crandor! ¡Destripador de Elvarg! ¡La perdición del dragón!",
    ["How Elvarg burned Crandor used to be one of my standard stories, but no one wants to hear it any more - they want to hear how you killed the dragon."] = "Cómo Elvarg quemó Crandor solía ser una de mis historias estándar, pero ya nadie quiere escucharla: quieren escuchar cómo mataste al dragón.",
    ["So, congratulations: you've become a story, and you've earned me a few storytelling coins in the taverns around here."] = "Entonces, enhorabuena: te has convertido en una historia, y me has ganado unos cuantos coins de storytelling en las tabernas de por aquí.",
    ["Did you hear? Gudrun is settling down! She's marrying a dwarf poet!"] = "¿Escuchaste? ¡Gudrun se está calmando! ¡Se va a casar con un poeta enano!",
    ["I guess that means no more nights out on the town with her. All the times she drank me under the table at the Blue Moon Inn..."] = "Supongo que eso significa no más noches de fiesta con ella. Todas las veces que me bebió debajo de la mesa en el Blue Moon Inn...",
    ["If poetry can make someone marry you, I'd better watch out! I don't want to wake up one morning and find I'd accidentally gotten married the night before!"] = "Si la poesía puede hacer que alguien se case contigo, ¡será mejor que tenga cuidado! ¡No quiero despertarme una mañana y descubrir que me casé accidentalmente la noche anterior!",
    ["Hartwin tells me that you were there when those zombies attacked Varrock. I was there too - we must have missed each other."] = "Hartwin me dice que estabas allí cuando esos zombies atacaron a Varrock. Yo también estuve allí; debimos habernos extrañado.",
    ["I guess I should thank you for saving the city! We can't let Varrock be destroyed. It's where I keep all my things! And all the things that aren't mine yet, but I'll get around to stealing someday..."] = "¡Supongo que debería agradecerte por salvar la ciudad! No podemos permitir que Varrock sea destruido. ¡Es donde guardo todas mis cosas! Y todas las cosas que aún no son mías, pero que algún día empezaré a robar...",
    ["I'm going to have to step up my game, Player! After what you did for Darren Lightfinger and his guild, it looks like I've got a challenger for the title of Master Thief of RuneScape!"] = "¡Tendré que mejorar mi juego, Player! Después de lo que hiciste por Darren Lightfinger y su gremio, ¡parece que tengo un retador por el título de Maestro Ladrón de RuneScape!",
    ["I'll need to steal something truly epic. Perhaps the Crown Jewels of Falador...or the River Salve..."] = "Necesitaré robar algo realmente épico. Quizás las Joyas de la Corona de Falador... o el Río Salve...",
    ["I heard you're another Tear of Guthix drinker! Juna is one tough audience, isn't she?"] = "¡Escuché que eres otro bebedor de Lágrimas de Guthix! Juna es un público difícil, ¿no?",
    ["She peers at me with those reptile eyes and all my banter dries up. She's got mental powers or something - I think it might be impossible to lie to her."] = "Ella me mira con esos ojos de reptil y todas mis bromas se agotan. Tiene poderes mentales o algo así. Creo que sería imposible mentirle.",
    ["Olaf the Bard has been repeating the song you played in the Rellekka Longhall! It sounds like you're a contender for RuneScape's second-best musician. The very best being me, of course!"] = "¡Olaf the Bard ha estado repitiendo la canción que tocaste en el Rellekka Longhall! Parece que eres un candidato al segundo mejor músico de RuneScape. ¡El mejor soy yo, por supuesto!",
    ["I often play on the enchanted Fremennik harp. It's true! But when I tell Olaf of that, he accuses me of being dishonest."] = "A menudo toco el arpa encantada Fremennik. ¡Es cierto! Pero cuando se lo cuento a Olaf, me acusa de ser deshonesto.",
    ["Achiettes tells me she let you try for Heroes' Guild membership. Clearly she was impressed by all the stories I'd told about you! She says you got in, too. Congratulations!"] = "Achiettes me dice que te dejó probar la membresía de Heroes' Guild. ¡Claramente quedó impresionada por todas las historias que le conté sobre ti! Ella dice que tú también entraste. ¡Felicidades!",
    ["She set me a fiendish set of tasks, and every time I came back, she thought of another one. I'm not sure those later tasks were strictly to do with Heroes' Guild membership, though..."] = "Ella me asignó una serie de tareas diabólicas y cada vez que regresaba, pensaba en otra. Sin embargo, no estoy seguro de que esas tareas posteriores tuvieran que ver estrictamente con la membresía de Heroes' Guild...",
    ["I've got you now, you thief! You've broken into the palace for the last time."] = "¡Ya te tengo, ladrón! Has irrumpido en el palacio por última vez.",
    ["What's happening here?"] = "¿Qué está pasando aquí?",
    ["I caught this man breaking into the palace. I need to hold him here until Captain Rovin comes to take him into custody."] = "Atrapé a este hombre irrumpiendo en el palacio. Necesito retenerlo aquí hasta que venga Captain Rovin y lo detenga.",
    ["I was already inside. You caught me breaking out!"] = "Ya estaba dentro. ¡Me pillaste estallando!",
    ["Alright, I caught this man breaking out of the palace. He was stealing Queen Ellamaria's bedroom slippers!"] = "Muy bien, pillé a este hombre escapando del palacio. ¡Estaba robando las pantuflas de la reina Ellamaria!",
    ["Tell the story properly, man! I leaped from the battlements into the branches of a yew tree, scaled the perimeter wall, and jumped down here, where I knew my accomplice would be waiting."] = "¡Cuenta la historia correctamente, hombre! Salté desde las almenas a las ramas de un yew tree, escalé el muro perimetral y salté aquí, donde sabía que mi cómplice estaría esperando.",
    ["Accomplice!"] = "¡Cómplice!",
    ["Accomplice? What?"] = "¿Cómplice? ¿Qué?",
    ["Accomplice Watt! You're under arrest for aiding a notorious criminal!"] = "¡Cómplice Watt! ¡Estás arrestado por ayudar a un criminal notorio!",
    ["...that was a distraction. He's gone, isn't he?"] = "...eso fue una distracción. Se ha ido, ¿no?",
    ["Thank you, stranger! I will sing the tale of how you aided Ozan, the Master Thief!"] = "¡Gracias, extraño! ¡Cantaré la historia de cómo ayudaste a Ozan, el maestro ladrón!",
    ["Look at me! I'm in Port Sarim jail!"] = "¡Mírame! ¡Estoy en la cárcel de Port Sarim!",
    ["I'm sorry?"] = "¿Lo siento?",
    ["No prison cell can hold Ozan, the Master Thief! They say he's broken out of every prison cell in Gielinor!"] = "¡Ninguna celda de prisión puede albergar a Ozan, el maestro ladrón! ¡Dicen que se ha escapado de todas las celdas de la prisión en Gielinor!",
    ["At least that's what they should say. But no one believes I've broken out of Port Sarim."] = "Al menos eso es lo que deberían decir. Pero nadie cree que me he escapado de Port Sarim.",
    ["So, I let myself get caught smuggling Karamja Rum, in the bottom of the Entrana Monks' ship - but that's another story - and I waited here for someone to come along so you could..."] = "Entonces, me dejé atrapar contrabandeando ron Karamja, en el fondo del barco de los Monjes Entrana - pero esa es otra historia - y esperé aquí a que alguien viniera para que tú pudieras...",
    ["Watch this!"] = "¡Mira esto!",
    ["And there we are!"] = "¡Y ahí estamos!",
    ["Farewell! Tell your friends about the day you saw Ozan, Master Thief of Gielinor, escape from Port Sarim jail!"] = "¡Adiós! ¡Cuéntale a tus amigos sobre el día que viste a Ozan, el maestro ladrón de Gielinor, escapar de la cárcel de Port Sarim!",
    ["Player! I didn't know you were a member of the Thieves' Guild!"] = "¡Player! ¡No sabía que eras miembro del Gremio de Ladrones!",
    ["Not only a member, Ozan. Player helped us to get the Guild up and running."] = "No solo un miembro, Ozan. Player nos ayudó a poner en funcionamiento el gremio.",
    ["Haha! Darren, you rogue, I knew you'd swindle someone into doing all your work for you!"] = "¡Jaja! Darren, pícaro, ¡sabía que estafarías a alguien para que hiciera todo el trabajo por ti!",
    ["That's not how it was at all, Ozan. Player here may be the best thief in the Guild."] = "No fue así en absoluto, Ozan. Player aquí puede ser el mejor ladrón del Gremio.",
    ["I have a competitor! I must go and plan a truly elaborate heist. One that will live on in legend for a thousand years!"] = "¡Tengo un competidor! Debo ir y planear un atraco verdaderamente elaborado. ¡Uno que vivirá en la leyenda durante mil años!",
    ["Farewell, Player!"] = "¡Adiós, Player!",
    ["That Ozan...if the stories he told about himself were all true, he could be a guild full of thieves on his own. I think he's mostly hot air, though."] = "Ese Ozan... si las historias que contó sobre sí mismo fueran todas ciertas, podría ser un gremio lleno de ladrones por su cuenta. Aunque creo que es más que nada palabrería.",
    ["Anyway, back to work."] = "De todos modos, volvamos al trabajo.",
    ["Robin, have you seen my pocket watch? I'm sure I had it a moment ago..."] = "Robin, ¿has visto mi reloj de bolsillo? Estoy seguro de que lo tuve hace un momento...",
    ["Wait!"] = "¡Espera!",
    ["Come talk to me first. That is not a happy place."] = "Ven a hablar conmigo primero. Ese no es un lugar feliz.",
    ["So, about these tombs beneath the city?"] = "Entonces, ¿sobre estas tumbas debajo de la ciudad?",
    ["You should totally check them out - they are full of treasures!"] = "Deberías echarles un vistazo: ¡están llenos de tesoros!",
    ["I was more thinking about helping people and returning stolen property..."] = "Estaba pensando más en ayudar a la gente y devolver objetos robados...",
    ["Yeah, right! You want to know about the mad stacks of loot down there, and experience aplenty!"] = "¡Sí, claro! ¡Quieres saber más sobre los locos montones de botín que hay allí abajo y experimentar en abundancia!",
    ["In fact, if experience is your thing, you should check out these four statues and braziers before heading in, pick what you want to learn about."] = "De hecho, si lo tuyo es la experiencia, deberías ver estas cuatro estatuas y braseros antes de entrar y elegir lo que quieras aprender.",
    ["Well, I mean, I'm sure that will come in handy as well."] = "Bueno, quiero decir, estoy seguro de que eso también será útil.",
    ["You can't hang about down there, though. There's some magic protecting these old tombs."] = "Pero no puedes quedarte ahí abajo. Hay algo de magia protegiendo estas viejas tumbas.",
    ["They shift around all the time to disorient tomb robbers, and to protect the treasures and secrets of the pharaohs of old."] = "Se mueven todo el tiempo para desorientar a los ladrones de tumbas y proteger los tesoros y secretos de los faraones de antaño.",
    ["And whatever Amascut is doing down there is creating this icky, green corruption stuff."] = "Y lo que sea que Amascut esté haciendo ahí abajo está creando esta corrupción verde y repugnante.",
    ["I swear, I can't stay down there for more than five minutes before having to come up for fresh air."] = "Lo juro, no puedo quedarme ahí abajo más de cinco minutos antes de tener que salir a tomar aire fresco.",
    ["I dread to think what would happen to me if I stayed any longer."] = "Me da miedo pensar qué me pasaría si me quedara más tiempo.",
    ["Hey, how are things going down there? I haven't been able to find Amascut yet, nor the Kharid-ib, unfortunately. I hope you're having better luck...or at least having fun!"] = "Oye, ¿cómo van las cosas ahí abajo? Desafortunadamente, todavía no he podido encontrar a Amascut ni tampoco a Kharid-ib. Espero que tengas mejor suerte... ¡o al menos te diviertas!",
    ["**Ozan:** Any questions about these shifting tombs?"] = "**Ozan:** ¿Alguna pregunta sobre estas tumbas móviles?",
    ["Ask about shifting tombs?"] = "¿Preguntar sobre las tumbas móviles?",
    ["What's down there?"] = "¿Qué hay ahí abajo?",
    ["In one word: opportunity! There is a wealth of knowledge and, more importantly, valuable trinkets in the tombs of long-dead pharaohs below us."] = "En una palabra: ¡oportunidad! Hay una gran cantidad de conocimientos y, lo que es más importante, baratijas valiosas en las tumbas de faraones muertos hace mucho tiempo debajo de nosotros.",
    ["These tombs are magically warded to deter grave robbers, though, so you'll find that they are ever- changing."] = "Sin embargo, estas tumbas están protegidas mágicamente para disuadir a los ladrones de tumbas, por lo que descubrirás que están en constante cambio.",
    ["There do seem to be a few constants, though - the most notable of which are sealed chests - each requires a certain skill to unlock, sometimes one which you might not have...but if someone else unlocks it first, you can search"] = "Sin embargo, parece haber algunas constantes, la más notable de las cuales son los cofres sellados. Cada uno requiere una determinada habilidad para desbloquearse, a veces una que quizás no tengas... pero si alguien más la desbloquea primero, puedes buscar.",
    ["it for your share of loot."] = "tíralo por tu parte del botín.",
    ["Also, there is a crystallised form of the corruption to mine through, and lots of urns that you should smash."] = "Además, hay una forma cristalizada de corrupción que puedes extraer y muchas urnas que debes romper.",
    ["It may seem odd, but if you smash enough urns, you become empowered, and can mine through a lot of corrupt crystals very quickly!"] = "Puede parecer extraño, pero si rompes suficientes urnas, ganarás poder y podrás extraer muchos cristales corruptos muy rápidamente.",
    ["Then there are sarcophagi, each sealed with a combination - inspect each sarcophagus carefully, then look for nearby panels to open it."] = "Luego están los sarcófagos, cada uno sellado con una combinación: inspecciona cada sarcófago con atención y luego busca paneles cercanos para abrirlos.",
    ["Finally, you'll need to find the exit. If you don't escape within the time limit, you'll lose out on some of what you found, as it gets lost to the corruption."] = "Finalmente, necesitarás encontrar la salida. Si no escapas dentro del límite de tiempo, perderás parte de lo que encontraste, ya que se perderá en la corrupción.",
    ["Oh, there's actually one last thing! You won't have time to do everything alone...so take others with you. Together, you should be able to find everything, and everyone can share in the bounty. There is no downside for other people"] = "¡Oh, en realidad hay una última cosa! No tendrás tiempo para hacer todo solo... así que lleva a otros contigo. Juntos, deberían poder encontrar todo y todos podrán compartir la recompensa. No hay desventajas para otras personas.",
    ["helping you!"] = "¡ayudándote!",
    ["What are the statues and braziers for?"] = "¿Para qué sirven las estatuas y los braseros?",
    ["That's where you decide what sort of an experience you'll gain in the tombs. Each of the four statues you activate will gain the favour of a lesser god, and you'll learn different things from them."] = "Ahí es donde decides qué tipo de experiencia obtendrás en las tumbas. Cada una de las cuatro estatuas que actives obtendrá el favor de un dios menor y aprenderás cosas diferentes de ellas.",
    ["Activate each statue to start receiving XP in the relevant skill, from activities within the tombs below: Apmeken - Thieving Crondis - Construction"] = "Activa cada estatua para comenzar a recibir XP en la habilidad correspondiente, desde las actividades dentro de las tumbas a continuación: Apmeken - Thieving Crondis - Construction",
    ["It's the same deal with the braziers in front of each statue, though to a lesser degree. Those are for different skills that you'll gain less experience in, when within the tombs below."] = "Lo mismo ocurre con los braseros frente a cada estatua, aunque en menor grado. Estas son para diferentes habilidades en las que obtendrás menos experiencia cuando estés dentro de las tumbas de abajo.",
    ["Light each brazier to start receiving XP in the relevant skill, from activities within the tombs below: Apmeken - Runecrafting Crondis - Crafting"] = "Enciende cada brasero para comenzar a recibir XP en la habilidad correspondiente, de las actividades dentro de las tumbas a continuación: Apmeken - Runecrafting Crondis - Crafting",
    ["Het - Divination Scabaras - Prayer"] = "Het - Adivinación Scabaras - Prayer",
    ["The tombs will reward you more if you're higher levels in these skills too!"] = "¡Las tumbas te recompensarán más si también tienes niveles más altos en estas habilidades!",
    ["Once you reach a certain level across all the aforementioned skills, you will have access to higher tier experience rates: Tier 1: Level 50+ Tier 2: Level 70+"] = "Una vez que alcances un cierto nivel en todas las habilidades antes mencionadas, tendrás acceso a tasas de experiencia de niveles más altos: Nivel 1: Nivel 50+ Nivel 2: Nivel 70+",
    ["Tier 3: Level 90+"] = "Nivel 3: Nivel 90+",
    ["Don't just take my word for it, though. You should inspect each of the statues and braziers, and activate those of interest to you."] = "Pero no confíes sólo en mi palabra. Deberás inspeccionar cada una de las estatuas y braseros, y activar aquellos que sean de tu interés.",
    ["There's a time limit?"] = "¿Hay un límite de tiempo?",
    ["Yeah, whatever Amascut is doing down there, it's having some sort of corrupting effect. If we spend too long down there at one time, I fear it might affect us."] = "Sí, sea lo que sea que Amascut esté haciendo ahí abajo, está teniendo algún tipo de efecto corruptor. Si pasamos demasiado tiempo allí abajo, temo que nos afecte.",
    ["I wouldn't spend more than five minutes down there before coming back up for some fresh air."] = "No pasaría más de cinco minutos allí abajo antes de volver a subir para tomar un poco de aire fresco.",
    ["More importantly, you need to find and use the exit BEFORE your time runs out, else you'll lose out on some of what you've found down there."] = "Más importante aún, debes encontrar y usar la salida ANTES de que se acabe el tiempo; de lo contrario, perderás parte de lo que has encontrado allí abajo.",
    ["Will it affect me?"] = "¿Me afectará?",
    ["Hey, I'm sure you'll be fine - just don't risk it and put it to the test. Once your time is up, you can always just head straight back in."] = "Oye, estoy seguro de que estarás bien, pero no te arriesgues y ponlo a prueba. Una vez que se acabe el tiempo, siempre puedes regresar directamente.",
    ["Simply coming back to this area seems to be enough to clear any corruption that's attached itself to me."] = "Simplemente regresar a esta área parece ser suficiente para eliminar cualquier corrupción que se me haya adherido.",
    ["No questions."] = "Sin preguntas.",
    ["I heard about these sandcastles and had to come see them with my own eyes. I'd love to see a Menaphos-inspired one."] = "Escuché sobre estos castillos de arena y tuve que venir a verlos con mis propios ojos. Me encantaría ver uno inspirado en Menaphos.",
    ["You're not very subtle about what you want are you?"] = "No eres muy sutil acerca de lo que quieres, ¿verdad?",
    ["I never saw myself fighting side by side with an elf!"] = "¡Nunca me vi peleando al lado de un elfo!",
    ["Good day to you."] = "Buenos días para ti.",
    ["Aye, 'tis a fair day my friend."] = "Sí, es un buen día, amigo mío.",
    ["I'm not your friend."] = "No soy tu amigo.",
    ["I'm surprised if you're anyone's friend with those kind of manners."] = "Me sorprende que seas amigo de alguien con ese tipo de modales.",
    ["Yes, it's a very nice day."] = "Sí, es un día muy bonito.",
    ["Aye, may the gods walk by yer side. Now leave me alone."] = "Sí, que los dioses caminen a tu lado. Ahora déjame en paz.",
    ["I ain't got nothing to sell ye, adventurer. Leave me be!"] = "No tengo nada que venderte, aventurero. ¡Déjame en paz!",
    ["Do you want to reclaim your 18,650 [Strength/Defence] XP reward lamp? It has a level 40 requirement."] = "¿Quieres reclamar tu lámpara de recompensa de 18,650 [Strength/Defence] XP? Tiene un requisito de nivel 40.",
    ["Cancel"] = "Cancelar",
    ["[You have reclaimed your 18,650 [Strength/Defence] XP lamp.]"] = "[Ha reclamado su lámpara 18,650 [Strength/Defence] XP.]",
    ["Aye, 'tis a fair day, mighty dragon-slaying friend."] = "Sí, es un buen día, poderoso amigo cazador de dragones.",
    ["Can I buy a rune platebody now, please?"] = "¿Puedo comprar un cuerpo de placas rúnicas ahora, por favor?",
    ["Can I buy a rune platebody now please?"] = "¿Puedo comprar un cuerpo de placas rúnicas ahora, por favor?",
    ["Can I have another key to Melzar's Maze?"] = "¿Puedo tener otra llave del Laberinto de Melzar?",
    ["It's the Guildmaster in the Champion's Guild who hands those keys out now. Go talk to him. No need to bother me if you don't need armour."] = "Es el Guildmaster del Gremio de Campeones quien entrega esas llaves ahora. Ve a hablar con él. No es necesario que me molestes si no necesitas armadura.",
    ["Aye, 'tis a fair day, mighty dragon-slaying friend. That's an interesting shield yer wearing. Could I have a look at it?"] = "Sí, es un buen día, poderoso amigo cazador de dragones. Es un escudo interesante el que llevas. ¿Podría echarle un vistazo?",
    ["Here you go"] = "Aquí tienes",
    ["Hmm...where did ye get it?"] = "Hmm... ¿de dónde lo conseguiste?",
    ["The Duke of Lumbridge gave it to me. It's an anti-dragonbreath shield."] = "Me lo regaló el duque de Lumbridge. Es un escudo anti-aliento de dragón.",
    ["Ah, I thought as much!"] = "¡Ah, eso mismo pensé!",
    ["Feel how it's warm to the touch. This shield must be storing dragonfire and just letting it radiate away."] = "Siente lo cálido que es al tacto. Este escudo debe almacenar fuego de dragón y simplemente dejarlo irradiar.",
    ["Now, if there was only a way to get the dragonfire out again..."] = "Ahora, si solo hubiera una manera de sacar el fuego del dragón nuevamente...",
    ["What use would that be?"] = "¿De qué serviría eso?",
    ["Why, ain't it obvious? Ye could project blasts of dragonfire from yer shield!"] = "¿Por qué, no es obvio? ¡Podrías proyectar ráfagas de fuego de dragón desde tu escudo!",
    ["Ye know, I think there might be a way."] = "Sabes, creo que podría haber una manera.",
    ["What way?"] = "¿De qué manera?",
    ["I've heard legends of a thing called a 'draconic visage'. It was made by the dragonkin themselves, creators of the dragons, or so they say."] = "He oído leyendas sobre algo llamado \"rostro dracónico\". Fue hecho por los propios dragonantes, creadores de los dragones, o eso dicen.",
    ["This 'draconic visage' had the power to channel dragonfire. Now, if I could attach the visage to the front of this shield..."] = "Este 'rostro dracónico' tenía el poder de canalizar el fuego de dragón. Ahora, si pudiera unir el rostro al frente de este escudo...",
    ["I will look for this draconic visage!"] = "¡Buscaré este rostro dracónico!",
    ["Good luck wi' that. They're mighty rare, so yer quest will take some time. If any monsters have them, it'll be the dragons."] = "Buena suerte con eso. Son muy raros, por lo que tu búsqueda llevará algún tiempo. Si algún monstruo los tiene, serán los dragones.",
    ["Aye, 'tis a fair day, mighty dragon-slaying friend. Ye've got... Ye've found a draconic visage! Could I look at it?"] = "Sí, es un buen día, poderoso amigo cazador de dragones. Tienes... ¡Has encontrado un rostro dracónico! ¿Podría mirarlo?",
    ["Amazin'! Ye can almost feel it pulsing with draconic power!"] = "¡Increíble! ¡Casi puedes sentirlo palpitar con poder dracónico!",
    ["Now, if ye bring me this and the anti-dragonbreath shield, I reckon I could combine them into something pretty special!"] = "Ahora, si me traes esto y el escudo anti-aliento de dragón, ¡creo que podría combinarlos en algo bastante especial!",
    ["Now, if ye want me to, I could attach this to yer anti-dragonbreath shield and make something pretty special."] = "Ahora, si quieres, podría adjuntar esto a tu escudo anti-aliento de dragón y hacer algo muy especial.",
    ["The shield won't be easy to wield though; ye'll need level 70 Defence."] = "Sin embargo, el escudo no será fácil de manejar; Necesitarás el nivel 70 Defence.",
    ["I'll charge 1,250,000 coins to construct it. What d'ye say?"] = "Cobraré 1.250.000 coins por construirlo. ¿Qué dices?",
    ["Yes, please!"] = "¡Sí, por favor!",
    ["Oh yeah - how did yer want this smithed exactly?."] = "Oh, sí, ¿cómo querías que se forjara esto exactamente?",
    ["How would you like Oziach to forge the shield?"] = "¿Cómo te gustaría que Oziach forjara el escudo?",
    ["Forge towards Melee."] = "Forja hacia cuerpo a cuerpo.",
    ["[Oziach skillfully forges the shield and visage into a new shield.]"] = "[Oziach forja hábilmente el escudo y el rostro en un nuevo escudo.]",
    ["Forge towards Magic."] = "Avanza hacia Magic.",
    ["Forge towards Ranged."] = "Avanza hacia Ranged.",
    ["Forge towards Necromancy."] = "Avanza hacia Necromancy.",
    ["There ye go. Now, the more dragonfire the shield absorbs, the more powerful it'll become."] = "Ahí tienes. Ahora, cuanto más fuego de dragón absorba el escudo, más poderoso se volverá.",
    ["Suit yerself."] = "Haz lo que quieras.",
    ["That's a bit expensive!"] = "¡Eso es un poco caro!",
    ["Yes it is. But I'm a master smith so I reckon I can charge what I like. Unless ye've got level 90 Smithing too, which I doubt!"] = "Sí, lo es. Pero soy un maestro herrero así que creo que puedo cargar lo que quiera. A menos que también tengas el nivel 90 de Smithing, ¡lo cual lo dudo!",
    ["No, I don't have level 90 Smithing."] = "No, no tengo el nivel 90 de Smithing.",
    ["I thought not. I'm the master smith of Misthalin! So, shall I construct the shield for you?"] = "Pensé que no. ¡Soy el maestro herrero de Misthalin! Entonces, ¿te construyo el escudo?",
    ["Actually, I have got level 90 Smithing."] = "En realidad, tengo el nivel 90 Smithing.",
    ["Oh! Well, I suppose ye don't need me for this then."] = "¡Oh! Bueno, entonces supongo que no me necesitas para esto.",
    ["The solving of this puzzle could be the key to your treasure."] = "Resolver este rompecabezas podría ser la clave para encontrar tu tesoro.",
    ["[Oziach has given you a puzzle box!]"] = "[¡Oziach te ha regalado una caja de rompecabezas!]",
    ["That isn't right, keep trying."] = "Eso no está bien, sigue intentándolo.",
    ["[Oziach has given you another clue scroll!]"] = "[¡Oziach te ha dado otro pergamino de pistas!]",
    ["Well done, traveller."] = "Bien hecho, viajero.",
}

